import bisect

def table_zone_eval(zone, ops):
    # Validation
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("zone must be a 2-tuple/list")
    initial, transitions = zone
    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("initial must be int")
    if abs(initial) > 50400:
        raise ValueError("initial out of range")
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be list/tuple")

    n_trans = len(transitions)
    if n_trans > 100000:
        raise ValueError("too many transitions")

    T = []
    W_start = []
    prev_off = initial
    prev_t = None

    for item in transitions:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("transition format")
        t, off = item
        if not isinstance(t, int) or isinstance(t, bool):
            raise ValueError("t must be int")
        if not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("off must be int")
        if abs(off) > 50400:
            raise ValueError("off out of range")
        if abs(t) > 10**13:
            raise ValueError("t out of range")
        if prev_t is not None:
            if t <= prev_t:
                raise ValueError("t not increasing")
            if t - prev_t < 172800:
                raise ValueError("t gap too small")
            if abs(off - prev_off) > 86400:
                raise ValueError("off diff too large")
        if off != prev_off:
            T.append((t, off))
            W_start.append(t + off)
            prev_off = off
        prev_t = t

    T_len = len(T)
    T_t = [x[0] for x in T]
    T_off = [x[1] for x in T]

    def resolve(w, fold):
        if T_len == 0:
            return w - initial

        i = bisect.bisect_right(W_start, w)
        k = i - 1
        if k < 0:
            k = 0

        # Check transition k for fold/gap
        # Transition k is at T[k][0], off_a = initial if k==0 else T[k-1][1], off_b = T[k][1]
        # We check if w falls in the discontinuity of this transition.
        # Note: bisect_right ensures w >= W_start[k] = T[k][0] + off_b.
        # For a fold, off_b < off_a. Fold range is [T[k][0] + off_b, T[k][0] + off_a].
        # Since w >= T[k][0] + off_b, we only need to check upper bound.
        # For a gap, off_b > off_a. Gap range is [T[k][0] + off_a, T[k][0] + off_b).
        # Since w >= T[k][0] + off_b, w cannot be in a gap of transition k.

        if k > 0:
            off_a = T_off[k-1]
        else:
            off_a = initial
        off_b = T_off[k]
        t_k = T_t[k]

        if off_b < off_a:
            # Fold
            if w <= t_k + off_a:
                return w - off_a if fold == 0 else w - off_b
        elif off_b > off_a:
            # Gap (w cannot be here because w >= t_k + off_b)
            pass

        # Continuous region
        off = off_b
        x = w - off
        # If x is in a later segment due to offset increase, adjust
        if k < T_len - 1 and x >= T_t[k+1]:
            off = T_off[k+1]
            x = w - off
        return x

    def get_wall(x):
        idx = bisect.bisect_right(T_t, x) - 1
        if idx < 0:
            off = initial
        else:
            off = T_off[idx]
        w = x + off
        f = 0
        if idx >= 0:
            # Check if x is in the fold region of transition idx
            # Transition idx: t = T[idx][0], off_a = initial if idx==0 else T[idx-1][1], off_b = T[idx][1]
            # Fold if off_b < off_a. Range for x: [t, t + off_a - off_b]
            if idx > 0:
                off_a = T_off[idx-1]
            else:
                off_a = initial
            off_b = T_off[idx]
            t_trans = T[idx][0]
            if off_b < off_a:
                if t_trans <= x <= t_trans + off_a - off_b:
                    f = 1
        return (w, f)

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("op format")
        cmd = op[0]
        if cmd == "instant":
            if len(op) != 3:
                raise ValueError("instant arity")
            w, fold = op[1], op[2]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("w type")
            if not isinstance(fold, int) or isinstance(fold, bool):
                raise ValueError("fold type")
            if fold not in (0, 1):
                raise ValueError("fold value")
            if abs(w) > 10**13:
                raise ValueError("w range")
            results.append(resolve(w, fold))

        elif cmd == "wall":
            if len(op) != 2:
                raise ValueError("wall arity")
            x = op[1]
            if not isinstance(x, int) or isinstance(x, bool):
                raise ValueError("x type")
            if abs(x) > 10**13:
                raise ValueError("x range")
            results.append(get_wall(x))

        elif cmd == "add":
            if len(op) != 5:
                raise ValueError("add arity")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(w, int) or isinstance(w, bool):
                raise ValueError("w type")
            if not isinstance(fold, int) or isinstance(fold, bool):
                raise ValueError("fold type")
            if fold not in (0, 1):
                raise ValueError("fold value")
            if not isinstance(days, int) or isinstance(days, bool):
                raise ValueError("days type")
            if not isinstance(secs, int) or isinstance(secs, bool):
                raise ValueError("secs type")
            if abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
                raise ValueError("range")

            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs
            results.append(get_wall(x2))
        else:
            raise ValueError("unknown op")

    return results

import bisect

def table_zone_eval(zone, ops):
    # --- Strict Input Validation ---
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("zone must be a 2-tuple/list")

    initial, transitions = zone

    if isinstance(initial, bool) or not isinstance(initial, int):
        raise ValueError("initial must be an int")
    if abs(initial) > 50400:
        raise ValueError("initial out of range")

    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be a list/tuple")

    n_trans = len(transitions)
    if n_trans > 100000:
        raise ValueError("too many transitions")

    trans_list = []
    prev_t = None
    prev_off = initial

    for item in transitions:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("transition item must be 2-tuple/list")
        t, off = item
        if isinstance(t, bool) or isinstance(off, bool):
            raise ValueError("t and off must be ints (not bools)")
        if not isinstance(t, int) or not isinstance(off, int):
            raise ValueError("t and off must be ints")
        if abs(off) > 50400:
            raise ValueError("offset out of range")
        if abs(t) > 10**13:
            raise ValueError("t out of range")

        if prev_t is not None:
            if t <= prev_t:
                raise ValueError("transitions not strictly increasing")
            if t - prev_t < 172800:
                raise ValueError("t gap too small")
            if abs(off - prev_off) > 86400:
                raise ValueError("offset change too large")

        trans_list.append((t, off))
        prev_t = t
        prev_off = off

    # Precompute arrays for O(log N) lookups
    T_vals = [t for t, off in trans_list]
    Off_vals = [off for t, off in trans_list]
    W = [t + off for t, off in trans_list]

    # Helper resolve
    def resolve(w, fold):
        if fold not in (0, 1):
            raise ValueError("fold must be 0 or 1")

        idx = bisect.bisect_right(W, w)
        k = idx - 1

        # Case: w is before first transition's wall time start
        if idx == 0:
            return w - initial

        # k is the index of the transition associated with the LATER instant
        # Off_vals[k] is the offset for the later instant
        x_later = w - Off_vals[k]

        if fold == 1:
            return x_later

        # fold == 0: check if we are in a fold region for the earlier instant
        # A fold exists if Off_vals[k] < Off_vals[k-1]
        # The fold interval in wall time is [W[k], T[k] + Off_vals[k-1])
        if k > 0 and Off_vals[k] < Off_vals[k-1]:
            t_k = T_vals[k]
            if w < t_k + Off_vals[k-1]:
                return w - Off_vals[k-1]

        return x_later

    # --- Operation Dispatch ---
    results = []

    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("op must be list/tuple")

        name = op[0]
        if not isinstance(name, str):
            raise ValueError("op name must be str")

        if name == "instant":
            if len(op) != 3:
                raise ValueError("instant op needs 3 args")
            w, fold = op[1], op[2]
            if isinstance(w, bool) or isinstance(fold, bool):
                raise ValueError("w and fold must be ints")
            if not isinstance(w, int) or not isinstance(fold, int):
                raise ValueError("w and fold must be ints")
            if abs(w) > 10**13:
                raise ValueError("w out of range")
            if fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")

            x = resolve(w, fold)
            results.append(x)

        elif name == "wall":
            if len(op) != 2:
                raise ValueError("wall op needs 2 args")
            x = op[1]
            if isinstance(x, bool):
                raise ValueError("x must be int")
            if not isinstance(x, int):
                raise ValueError("x must be int")
            if abs(x) > 10**13:
                raise ValueError("x out of range")

            # Find offset at x
            idx = bisect.bisect_right(T_vals, x)
            k = idx - 1
            if k < 0:
                offset = initial
            else:
                offset = Off_vals[k]

            w = x + offset

            # Determine fold flag f
            f = 0
            if k >= 0:
                # Check if x is in the fold region of transition k
                # Fold condition: Off_vals[k] < Off_vals[k-1] (if k>0)
                # And x < T[k] + Off_vals[k-1] - Off_vals[k]
                if k > 0 and Off_vals[k] < Off_vals[k-1]:
                    limit = T_vals[k] + Off_vals[k-1] - Off_vals[k]
                    if x < limit:
                        f = 1

            results.append((w, f))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("add op needs 5 args")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if isinstance(w, bool) or isinstance(fold, bool) or isinstance(days, bool) or isinstance(secs, bool):
                raise ValueError("args must be ints")
            if not isinstance(w, int) or not isinstance(fold, int) or not isinstance(days, int) or not isinstance(secs, int):
                raise ValueError("args must be ints")
            if abs(w) > 10**13 or abs(secs) > 10**13:
                raise ValueError("w or secs out of range")
            if abs(days) > 10**6:
                raise ValueError("days out of range")
            if fold not in (0, 1):
                raise ValueError("fold must be 0 or 1")

            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs

            # Return wall result for x2
            idx = bisect.bisect_right(T_vals, x2)
            k = idx - 1
            if k < 0:
                offset = initial
            else:
                offset = Off_vals[k]

            w2_final = x2 + offset

            f2 = 0
            if k >= 0:
                if k > 0 and Off_vals[k] < Off_vals[k-1]:
                    limit = T_vals[k] + Off_vals[k-1] - Off_vals[k]
                    if x2 < limit:
                        f2 = 1

            results.append((w2_final, f2))

        else:
            raise ValueError("unknown operation")

    return results

