def table_zone_eval(zone, ops):
    # 1. Validate zone structure
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("zone must be a 2-tuple/list")

    initial, transitions = zone

    if not isinstance(initial, int) or isinstance(initial, bool):
        raise ValueError("initial must be an int")
    if abs(initial) > 50400:
        raise ValueError("initial out of range")

    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be a list/tuple")

    # Validate transitions
    if len(transitions) > 100000:
        raise ValueError("too many transitions")

    prev_t = None
    prev_off = initial
    clean_transitions = []

    for item in transitions:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("transition must be a 2-tuple/list")
        t, off = item
        if not isinstance(t, int) or isinstance(t, bool):
            raise ValueError("transition t must be an int")
        if not isinstance(off, int) or isinstance(off, bool):
            raise ValueError("transition off must be an int")
        if abs(off) > 50400:
            raise ValueError("transition off out of range")
        if abs(t) > 10**13:
            raise ValueError("transition t out of range")

        if prev_t is not None:
            if t <= prev_t:
                raise ValueError("transitions not strictly increasing")
            if t - prev_t < 172800:
                raise ValueError("transition gap too small")
            if abs(off - prev_off) > 86400:
                raise ValueError("offset change too large")

        # Filter out no-op transitions
        if off != prev_off:
            clean_transitions.append((t, off))
            prev_off = off

        prev_t = t

    # Precompute W for binary search
    # W[i] = t_i + off_i
    W = [t + off for t, off in clean_transitions]

    # 2. Helper for resolve
    def resolve(w, fold):
        if not isinstance(fold, int) or isinstance(fold, bool) or fold not in (0, 1):
            raise ValueError("fold must be 0 or 1")
        if not isinstance(w, int) or isinstance(w, bool):
            raise ValueError("w must be an int")
        if abs(w) > 10**13:
            raise ValueError("w out of range")

        n = len(W)
        if n == 0:
            # No transitions, constant offset
            return w - initial

        # Find position in W
        i = bisect.bisect_right(W, w)

        if i == 0:
            # Before first transition
            t0, off0 = clean_transitions[0]
            if w < t0 + initial:
                return w - initial
            else:
                # Gap
                a, b = initial, off0
                return w - a if fold == 0 else w - b

        elif i < n:
            # Between transitions
            # w >= W[i-1] and w < W[i]
            # Check if w is in the gap/fold at transition i
            # Transition i is at t_i with offset off_i
            # Previous offset is off_{i-1}
            t_i, off_i = clean_transitions[i]
            off_prev = clean_transitions[i-1][1]

            # Wall time at t_i from left is t_i + off_prev
            # If w >= t_i + off_prev, it's in the gap (since w < W[i] = t_i + off_i)
            # Note: if fold (off_prev > off_i), t_i + off_prev > W[i], so w < W[i] implies w < t_i + off_prev.
            # So logic holds for both gap and fold cases correctly identifying the segment.

            if w >= t_i + off_prev:
                # Gap
                a, b = off_prev, off_i
                return w - a if fold == 0 else w - b
            else:
                # Segment i-1
                return w - off_prev

        else:
            # After last transition
            off_last = clean_transitions[-1][1]
            return w - off_last

    # 3. Process operations
    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("op must be list/tuple")
        if len(op) < 1 or not isinstance(op[0], str):
            raise ValueError("op must start with string")

        cmd = op[0]

        if cmd == "instant":
            if len(op) != 3:
                raise ValueError("instant requires 3 args")
            w, fold = op[1], op[2]
            results.append(resolve(w, fold))

        elif cmd == "wall":
            if len(op) != 2:
                raise ValueError("wall requires 2 args")
            x = op[1]
            if not isinstance(x, int) or isinstance(x, bool):
                raise ValueError("x must be an int")
            if abs(x) > 10**13:
                raise ValueError("x out of range")

            # Find offset at x
            if not clean_transitions:
                offset = initial
            else:
                # Find index of transition <= x
                # We want largest t_i <= x
                # bisect_right on t's gives index after last t <= x
                ts = [t for t, off in clean_transitions]
                idx = bisect.bisect_right(ts, x) - 1

                if idx < 0:
                    offset = initial
                else:
                    offset = clean_transitions[idx][1]

            w = x + offset

            # Determine fold flag f
            # f=1 if x is the later match. This happens if there is a fold at some transition t_k
            # such that t_k <= x < t_{k+1} (or end) and offset(x) is the NEW offset (smaller).
            # Actually, simpler: check if x is in a fold region.
            # A fold occurs at t_k if off_{k-1} > off_k.
            # The fold region for wall time is [t_k + off_k, t_k + off_{k-1}].
            # But we need to check if x is the "later" instant.
            # The later instant uses the NEW offset (off_k).
            # So if x uses off_k and x >= t_k, and there was a fold, then x is the later one.

            f = 0
            if not clean_transitions:
                f = 0
            else:
                # Find which segment x is in
                idx = bisect.bisect_right(ts, x) - 1
                if idx >= 0:
                    # x is in segment idx (offset clean_transitions[idx][1])
                    # Check transition at idx+1 (if exists) for fold
                    # Wait, transition at idx is the one that SET the current offset.
                    # Transition at idx+1 sets the NEXT offset.
                    # We need to check if x is in the overlap caused by transition idx+1?
                    # No, x is in segment defined by transition idx.
                    # The fold would be caused by transition k where offset changes.
                    # If x is in segment k (offset off_k), and off_{k-1} > off_k (fold at k),
                    # then x could be the later match if x >= t_k.
                    # Since x is in segment k, x >= t_k is true.
                    # So if off_{k-1} > off_k, then x is the later match.

                    if idx > 0:
                        prev_off = clean_transitions[idx-1][1]
                        curr_off = clean_transitions[idx][1]
                        if prev_off > curr_off:
                            f = 1

            results.append((w, f))

        elif cmd == "add":
            if len(op) != 5:
                raise ValueError("add requires 5 args")
            w, fold, days, secs = op[1], op[2], op[3], op[4]
            if not isinstance(days, int) or isinstance(days, bool):
                raise ValueError("days must be int")
            if not isinstance(secs, int) or isinstance(secs, bool):
                raise ValueError("secs must be int")
            if abs(days) > 10**6:
                raise ValueError("days out of range")
            if abs(secs) > 10**13:
                raise ValueError("secs out of range")

            w2 = w + 86400 * days
            x1 = resolve(w2, fold)
            x2 = x1 + secs

            # Compute result for x2
            if not clean_transitions:
                offset = initial
            else:
                ts = [t for t, off in clean_transitions]
                idx = bisect.bisect_right(ts, x2) - 1
                if idx < 0:
                    offset = initial
                else:
                    offset = clean_transitions[idx][1]

            w_res = x2 + offset
            f_res = 0
            if idx >= 0:
                if idx > 0:
                    prev_off = clean_transitions[idx-1][1]
                    curr_off = clean_transitions[idx][1]
                    if prev_off > curr_off:
                        f_res = 1

            results.append((w_res, f_res))

        else:
            raise ValueError(f"Unknown operation: {cmd}")

    return results

import bisect

def table_zone_eval(zone, ops):
    # 1. Validate zone structure
    if not isinstance(zone, (list, tuple)) or len(zone) != 2:
        raise ValueError("zone must be a 2-tuple/list")

    initial, transitions = zone

    if type(initial) is not int or abs(initial) > 50400:
        raise ValueError("initial must be an int in range")

    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be a list/tuple")

    clean_transitions = []
    prev_offset = initial
    prev_t = None

    for item in transitions:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("Each transition must be a 2-tuple/list")

        t, off = item
        if type(t) is not int or type(off) is not int:
            raise ValueError("Transition values must be ints")
        if abs(t) > 10**13 or abs(off) > 50400:
            raise ValueError("Transition values out of range")

        if prev_t is not None:
            if t - prev_t < 172800 or abs(off - prev_offset) > 86400:
                raise ValueError("Transition constraints violated")

        if off != prev_offset:
            clean_transitions.append((t, off))
            prev_offset = off
        prev_t = t

    ts = [t for t, off in clean_transitions]
    offsets = [off for t, off in clean_transitions]
    W = [t + off for t, off in clean_transitions]
    n = len(clean_transitions)

    def resolve(w, fold):
        if type(w) is not int or type(fold) is not int:
            raise ValueError("Args must be ints")
        if fold not in (0, 1) or abs(w) > 10**13:
            raise ValueError("Args out of range")

        if n == 0:
            return w - initial

        i = bisect.bisect_right(W, w)

        if i == 0:
            a = initial
            b = offsets[0]
            T_val = ts[0]
            if b > a:
                if T_val + a <= w < W[0]:
                    return w - a if fold == 0 else w - b
            return w - a

        elif i == n:
            k = n - 1
            a = offsets[k-1] if k > 0 else initial
            b = offsets[k]
            T_val = ts[k]
            if b < a:
                if W[k] <= w < T_val + a:
                    return w - a if fold == 0 else w - b
            return w - b

        else:
            # W[i-1] <= w < W[i]
            # Check fold of transition i-1
            k = i - 1
            a = offsets[k-1] if k > 0 else initial
            b = offsets[k]
            T_val = ts[k]
            if b < a:
                if W[k] <= w < T_val + a:
                    return w - a if fold == 0 else w - b

            # Check gap of transition i
            a_next = offsets[k]
            b_next = offsets[i]
            T_val_next = ts[i]
            if b_next > a_next:
                if T_val_next + a_next <= w < W[i]:
                    return w - a_next if fold == 0 else w - b_next

            return w - a

    def wall(x):
        if type(x) is not int or abs(x) > 10**13:
            raise ValueError("x must be an int in range")

        idx = bisect.bisect_right(ts, x)
        off = offsets[idx-1] if idx > 0 else initial
        w = x + off

        f = 0
        if idx > 0:
            k = idx - 1
            prev_off = offsets[k-1] if k > 0 else initial
            if offsets[k] < prev_off:
                limit = ts[k] + prev_off - offsets[k]
                if x < limit:
                    f = 1
        return (w, f)

    def add_op(w, fold, days, secs):
        if type(w) is not int or type(fold) is not int or type(days) is not int or type(secs) is not int:
            raise ValueError("Args must be ints")
        if fold not in (0, 1) or abs(w) > 10**13 or abs(secs) > 10**13 or abs(days) > 10**6:
            raise ValueError("Args out of range")

        w2 = w + 86400 * days
        x1 = resolve(w2, fold)
        x2 = x1 + secs
        return wall(x2)

    results = []
    for op in ops:
        if not isinstance(op, (list, tuple)):
            raise ValueError("Op must be list/tuple")
        if len(op) < 1:
            raise ValueError("Op must have name")

        name = op[0]
        if type(name) is not str:
            raise ValueError("Op name must be str")

        if name == "instant":
            if len(op) != 3:
                raise ValueError("instant op needs 3 args")
            results.append(resolve(op[1], op[2]))

        elif name == "wall":
            if len(op) != 2:
                raise ValueError("wall op needs 2 args")
            results.append(wall(op[1]))

        elif name == "add":
            if len(op) != 5:
                raise ValueError("add op needs 5 args")
            results.append(add_op(op[1], op[2], op[3], op[4]))

        else:
            raise ValueError("Unknown operation")

    return results

