import math

# Constants
MAX_N_S = 10**16
EPOCH_YEAR = 1970
EPOCH_MONTH = 1
EPOCH_DAY = 1

# Precompute days from year 0 to start of year Y
# days_0_to_year_start(Y) = Y * 365 + floor(Y/4) - floor(Y/100) + floor(Y/400)
# We need days from 1970-01-01.
# days_from_epoch(Y, M, D) = days_0_to_year_start(Y) + days_in_months(Y, M) + (D - 1) - days_0_to_year_start(1970)

def _days_0_to_year_start(y):
    return y * 365 + (y // 4) - (y // 100) + (y // 400)

def _is_leap_year(y):
    return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

def _days_from_epoch_to_start_of_month(y, m):
    """Returns number of days from 1970-01-01 to the first day of month m in year y."""
    # Days from year 0 to start of y
    days_y = _days_0_to_year_start(y)
    # Days from year 0 to start of 1970
    days_epoch = _days_0_to_year_start(EPOCH_YEAR)

    diff_years = days_y - days_epoch

    # Days in months before m in year y
    # Month lengths for non-leap year
    month_lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    days_months = sum(month_lengths[:m-1])

    # If leap year and past Feb, add 1
    if m > 2 and _is_leap_year(y):
        days_months += 1

    return diff_years + days_months

def _validate_leaps(leaps):
    if not isinstance(leaps, (list, tuple)):
        raise ValueError("leaps must be a list or tuple")
    if len(leaps) > 100:
        raise ValueError("leaps length must be <= 100")

    prev_y, prev_m = 0, 0
    for entry in leaps:
        if not isinstance(entry, (list, tuple)):
            raise ValueError("Each leap entry must be a list or tuple")
        if len(entry) != 3:
            raise ValueError("Each leap entry must have 3 elements")

        y, m, d = entry

        if not isinstance(y, int) or isinstance(y, bool):
            raise ValueError("Year must be an int")
        if not isinstance(m, int) or isinstance(m, bool):
            raise ValueError("Month must be an int")
        if not isinstance(d, int) or isinstance(d, bool):
            raise ValueError("Delta must be an int")

        if not (1970 <= y <= 2400):
            raise ValueError(f"Year {y} out of range [1970, 2400]")
        if not (1 <= m <= 12):
            raise ValueError(f"Month {m} out of range [1, 12]")
        if d not in (1, -1):
            raise ValueError(f"Delta {d} must be 1 or -1")

        if (y, m) == (1970, 1):
            raise ValueError("Leap at (1970, 1) is not allowed")

        if (y, m) <= (prev_y, prev_m):
            raise ValueError("Leaps must be in strictly increasing (year, month) order")

        prev_y, prev_m = y, m

def _compute_E_list(leaps):
    """Computes E_k for each leap."""
    E_list = []
    cum_delta = 0
    for y, m, delta in leaps:
        # D_k is days from 1970-01-01 to the first day of the month AFTER leap k's month
        # If leap is at (y, m), next month is m+1. If m=12, next is (y+1, 1).
        if m == 12:
            next_y, next_m = y + 1, 1
        else:
            next_y, next_m = y, m + 1

        D_k = _days_from_epoch_to_start_of_month(next_y, next_m)

        # E_k = 86400000 * D_k + 1000 * cum_delta
        # Note: cum_delta includes delta_k for the current leap in the formula?
        # "E_k = 86400000 * D_k + 1000 * (delta_0 + ... + delta_k)"
        # Yes, sum up to k.
        E_k = 86400000 * D_k + 1000 * cum_delta

        E_list.append((E_k, delta))
        cum_delta += delta

    return E_list

def smeared_ms(n, leaps):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an int")
    if not (0 <= n <= MAX_N_S):
        raise ValueError(f"n must be in [0, {MAX_N_S}]")

    _validate_leaps(leaps)

    E_list = _compute_E_list(leaps)

    correction = 0
    for E_k, delta in E_list:
        start = E_k - 1000000
        # g_k(n) = min(1000, max(0, (n - start) // 1000))
        # Optimization: if n < start, g=0. If n >= E_k, g=1000.
        if n < start:
            g = 0
        elif n >= E_k:
            g = 1000
        else:
            g = (n - start) // 1000

        correction += delta * g

    return n - correction

def unsmeared_ms(s, leaps):
    if not isinstance(s, int) or isinstance(s, bool):
        raise ValueError("s must be an int")
    if not (0 <= s <= MAX_N_S):
        raise ValueError(f"s must be in [0, {MAX_N_S}]")

    _validate_leaps(leaps)

    # Binary search for smallest n such that smeared_ms(n) >= s
    # Range [0, 10**16 + buffer]
    # Max possible n is around 10**16 + 1000*100 (max correction)
    # But since s can be 10**16, n can be slightly larger if correction is negative?
    # Correction is sum(delta * g). Max delta=1, g=1000. Max correction = 100 * 1000 = 100000.
    # If delta=-1, correction is negative. s = n - (-corr) = n + corr.
    # So n = s - corr. If corr is large negative, n is larger than s.
    # Max negative correction: 100 leaps * -1 * 1000 = -100000.
    # So n can be up to s + 100000.
    # 10**16 + 200000 is safe.

    low = 0
    high = MAX_N_S + 200000
    ans = -1

    # Precompute E_list to avoid recomputing in every check
    E_list = _compute_E_list(leaps)

    def check(n):
        # Inline smeared_ms logic for speed
        correction = 0
        for E_k, delta in E_list:
            start = E_k - 1000000
            if n < start:
                g = 0
            elif n >= E_k:
                g = 1000
            else:
                g = (n - start) // 1000
            correction += delta * g
        return n - correction

    while low <= high:
        mid = (low + high) // 2
        val = check(mid)
        if val >= s:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    if ans != -1 and check(ans) == s:
        return ans
    else:
        raise ValueError(f"No n found for s={s}")

