import heapq

def petri_starts(places, transitions, until, limit):
    # 1. Validation

    # Helper to check int but not bool
    def is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    # Check places
    if not isinstance(places, dict):
        raise ValueError("places must be a dict")
    for p, n in places.items():
        if not isinstance(p, str) or not p:
            raise ValueError("Place name must be a non-empty string")
        if not is_int(n):
            raise ValueError("Place token count must be an integer")
        if n < 0 or n > 10**6:
            raise ValueError("Place token count out of range")

    # Check until and limit
    if not is_int(until):
        raise ValueError("until must be an integer")
    if until < 0 or until > 10**12:
        raise ValueError("until out of range")

    if not is_int(limit):
        raise ValueError("limit must be an integer")
    if limit < 1 or limit > 2000:
        raise ValueError("limit out of range")

    # Check transitions
    if not isinstance(transitions, (list, tuple)):
        raise ValueError("transitions must be a list or tuple")
    if len(transitions) > 50:
        raise ValueError("Too many transitions")

    seen_names = set()
    trans_objects = []

    for i, t in enumerate(transitions):
        if not isinstance(t, tuple) or len(t) != 6:
            raise ValueError("Each transition must be a tuple of 6 elements")

        name, inputs, outputs, duration, priority, servers = t

        # Name
        if not isinstance(name, str) or not name:
            raise ValueError("Transition name must be a non-empty string")
        if name in seen_names:
            raise ValueError("Duplicate transition name")
        seen_names.add(name)

        # Inputs
        if not isinstance(inputs, dict):
            raise ValueError("Inputs must be a dict")
        if not inputs:
            raise ValueError("Inputs must not be empty")
        for p, w in inputs.items():
            if not isinstance(p, str) or p not in places:
                raise ValueError("Input place must exist in places")
            if not is_int(w):
                raise ValueError("Input weight must be an integer")
            if w < 1 or w > 1000:
                raise ValueError("Input weight out of range")

        # Outputs
        if not isinstance(outputs, dict):
            raise ValueError("Outputs must be a dict")
        for p, w in outputs.items():
            if not isinstance(p, str) or p not in places:
                raise ValueError("Output place must exist in places")
            if not is_int(w):
                raise ValueError("Output weight must be an integer")
            if w < 1 or w > 1000:
                raise ValueError("Output weight out of range")

        # Duration
        if not is_int(duration):
            raise ValueError("Duration must be an integer")
        if duration < 0 or duration > 10**12:
            raise ValueError("Duration out of range")

        # Priority
        if not is_int(priority):
            raise ValueError("Priority must be an integer")

        # Servers
        if not is_int(servers):
            raise ValueError("Servers must be an integer")
        if servers < 1 or servers > 10**6:
            raise ValueError("Servers out of range")

        trans_objects.append({
            'name': name,
            'inputs': inputs,
            'outputs': outputs,
            'duration': duration,
            'priority': priority,
            'servers': servers,
            'index': i
        })

    # 2. Data Structures
    tokens = dict(places)
    active_counts = {t['name']: 0 for t in trans_objects}
    events = [] # Min-heap of (completion_time, transition_index)
    results = []

    # 3. Simulation Loop
    current_time = 0

    while len(results) < limit:
        # If current time exceeds until, we cannot start any more transitions
        # (starts are only recorded if time <= until)
        if current_time > until:
            break

        # Process completions at current_time
        while events and events[0][0] == current_time:
            t, idx = heapq.heappop(events)
            trans = trans_objects[idx]
            # Add outputs
            for p, w in trans['outputs'].items():
                tokens[p] += w
            # Decrement active count
            active_counts[trans['name']] -= 1

        # Process starts
        # We loop as long as we can start a transition at current_time
        # This handles 0-duration transitions that might enable others
        started_anything = True
        while started_anything and len(results) < limit:
            started_anything = False

            best_idx = -1
            best_priority = float('inf')

            # Find best enabled transition
            # Enabled: inputs available AND active_count < servers
            for i, trans in enumerate(trans_objects):
                # Check inputs
                enabled = True
                for p, w in trans['inputs'].items():
                    if tokens[p] < w:
                        enabled = False
                        break
                if not enabled:
                    continue

                # Check servers
                if active_counts[trans['name']] >= trans['servers']:
                    continue

                # Check priority (lower is better), tie-break by index
                pri = trans['priority']
                if pri < best_priority or (pri == best_priority and (best_idx == -1 or i < best_idx)):
                    best_priority = pri
                    best_idx = i

            if best_idx == -1:
                started_anything = False
                break # No transitions enabled

            # Execute start
            trans = trans_objects[best_idx]

            # Consume inputs
            for p, w in trans['inputs'].items():
                tokens[p] -= w

            # Record start
            results.append((current_time, trans['name']))

            # Handle duration
            if trans['duration'] > 0:
                # Push to events
                heapq.heappush(events, (current_time + trans['duration'], best_idx))
                active_counts[trans['name']] += 1
                # Starting a >0 duration transition consumes tokens, unlikely to enable others immediately.
                # However, we must continue loop in case 0-duration transitions were processed before?
                # Actually, if we just started a >0 transition, we consumed tokens.
                # It's possible that this transition had duration 0? No, checked above.
                # So tokens decreased.
                # But maybe we started a 0-duration transition in a previous iteration of this loop?
                # Yes.
                # So we must continue loop.
                started_anything = True
            else:
                # duration == 0
                # Add outputs immediately
                for p, w in trans['outputs'].items():
                    tokens[p] += w
                # active count doesn't change (never in progress)
                # Outputs might enable other transitions
                started_anything = True

        # If no transitions enabled, try to advance time
        if not started_anything:
            if not events:
                break # Deadlock

            next_t = events[0][0]
            if next_t > until:
                break # Next instant is out of bounds

            current_time = next_t

    return results

