        if out in gates_by_out:
            raise ValueError("Duplicate out in gates")
        if op not in valid_ops:
            raise ValueError("Invalid op")
        if not isinstance(ins, (list, tuple)):
            raise ValueError("ins must be a list or tuple")
        if len(ins) == 0:
            raise ValueError("ins must be non-empty")
        for i in ins:
            if not isinstance(i, str) or not i:
                raise ValueError("ins elements must be non-empty strs")
        if op in ("NOT", "BUF") and len(ins) != 1:
            raise ValueError("NOT/BUF must have exactly 1 input")
        if op not in ("NOT", "BUF") and (len(ins) < 2 or len(ins) > 4):
            raise ValueError("Other gates must have 2..4 inputs")
        if not isinstance(delay, int) or isinstance(delay, bool) or delay < 0 or delay > 10**12:
            raise ValueError("delay must be int 0..10**12")

        gates_by_out[out] = (op, ins, delay)
        gates_list.append((out, op, ins, delay))
        all_signals.add(out)
        for i in ins:
            all_signals.add(i)

    # Graph cycle detection
    # Build adjacency: input -> [out]
    adj = {s: [] for s in all_signals}
    for out, op, ins, delay in gates_list:
        for i in ins:
            adj[i].append(out)

    # DFS for cycle detection
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {s: WHITE for s in all_signals}
    def has_cycle(u):
        color[u] = GRAY
        for v in adj[u]:
            if color[v] == GRAY:
                return True
            if color[v] == WHITE and has_cycle(v):
                return True
        color[u] = BLACK
        return False

