    event_times.add(0)
    for t in stimuli_at_time:
        if t <= until:
            event_times.add(t)

    sorted_times = sorted(event_times)

    for t in sorted_times:
        changed = set()
        round_num = 0

        while True:
            pending_due = [(out, val) for out, (val, due) in pending.items() if due == t]

            if not pending_due and round_num > 0:
                break

            if round_num == 0:
                # Apply stimuli
                if t in stimuli_at_time:
                    for signal, value in stimuli_at_time[t]:
                        values[signal] = value
                        changed.add(signal)

                # Apply pending
                for out, val in pending_due:
                    if values[out] != val:
                        changed.add(out)
                    values[out] = val
                    del pending[out]
            else:
                # Apply pending
                for out, val in pending_due:
                    if values[out] != val:
                        changed.add(out)
                    values[out] = val
                    del pending[out]

            # Evaluate
            gates_to_eval = []
            if t == 0 and round_num == 0:
                gates_to_eval = gates_list
            else:
                for out, op, ins, delay in gates_list:
                    if any(i in changed for i in ins):
                        gates_to_eval.append((out, op, ins, delay))

            for out, op, ins, delay in gates_to_eval:
                if out in pending:
                    del pending[out]

                # Compute value
                if op == "AND":
                    val = 1
                    for i in ins:
                        val &= values[i]
                elif op == "OR":
                    val = 0
                    for i in ins:
                        val |= values[i]
                elif op == "XOR":
                    val = 0
                    for i in ins:
                        val ^= values[i]
                elif op == "NAND":
                    val = 1
                    for i in ins:
                        val &= values[i]
                    val = 1 - val
                elif op == "NOR":
                    val = 0
                    for i in ins:
                        val |= values[i]
                    val = 1 - val
                elif op == "NOT":
                    val = 1 - values[ins[0]]
                elif op == "BUF":
                    val = values[ins[0]]

                if val != values[out]:
                    new_due = t + delay
                    if new_due <= until:
                        pending[out] = (val, new_due)

            round_num += 1

        # Trace update
        for w in watch:
            if values[w] != prev_value[w]:
                trace[w].append((t, values[w]))
                prev_value[w] = values[w]

    return trace

