        time, signal, value = s
        if isinstance(time, bool) or not isinstance(time, int) or time < 0 or time > 10**12:
            raise ValueError("Stimulus time must be int 0..10**12")
        if not isinstance(signal, str) or not signal:
            raise ValueError("Stimulus signal must be non-empty str")
        if signal not in primary_inputs:
            raise ValueError("Stimulus signal must be a primary input")
        if isinstance(value, bool) or not isinstance(value, int) or value not in (0, 1):
            raise ValueError("Stimulus value must be int 0 or 1")

        if time not in stimuli_at_time:
            stimuli_at_time[time] = []
        stimuli_at_time[time].append((signal, value))

    # Watch validation
    for w in watch:
        if not isinstance(w, str) or not w:
            raise ValueError("Watch elements must be non-empty strs")
        if w not in all_signals:
            raise ValueError("Watch signal must be a known signal")

    # Simulation
    values = {s: 0 for s in all_signals}
    pending = {}  # out -> (value, due_time)
    trace = {w: [] for w in watch}
    prev_value = {w: 0 for w in watch}

    pq = [0]
    heapq.heapify(pq)
    for t in stimuli_at_time:
        if t <= until:
            heapq.heappush(pq, t)

    processed_times = set()

    while pq:
        t = heapq.heappop(pq)
        if t > until or t in processed_times:
            continue
        processed_times.add(t)

        round_num = 0
        while True:
            changed = set()
            pending_due = [(out, val) for out, (val, due) in pending.items() if due == t]

            if not pending_due and round_num > 0:
                break

            if round_num == 0:
                # Apply stimuli
                if t in stimuli_at_time:
                    for signal, value in stimuli_at_time[t]:
                        if values[signal] != value:
                            changed.add(signal)
                        values[signal] = value
                # Apply pending
                for out, val in pending_due:
                    if values[out] != val:
                        changed.add(out)
                    values[out] = val
                    del pending[out]
            else:
                # Apply pending
                for out, val in pending_due:
                    if values[out] != val:
                        changed.add(out)
                    values[out] = val
                    del pending[out]

            # Evaluate gates
            gates_to_eval = []
            if t == 0 and round_num == 0:
                gates_to_eval = gates_list
            else:
                for out, op, ins, delay in gates_list:
                    if any(i in changed for i in ins):
                        gates_to_eval.append((out, op, ins, delay))

            for out, op, ins, delay in gates_to_eval:
                if out in pending:
                    del pending[out]

                # Compute value
                if op == "AND":
                    val = 1
                    for i in ins: val &= values[i]
                elif op == "OR":
                    val = 0
                    for i in ins: val |= values[i]
                elif op == "XOR":
                    val = 0
                    for i in ins: val ^= values[i]
                elif op == "NAND":
                    val = 1
                    for i in ins: val &= values[i]
                    val = 1 - val
                elif op == "NOR":
                    val = 0
                    for i in ins: val |= values[i]
                    val = 1 - val
                elif op == "NOT":
                    val = 1 - values[ins[0]]
                elif op == "BUF":
                    val = values[ins[0]]

                if val != values[out]:
                    new_due = t + delay
                    if new_due <= until:
                        pending[out] = (val, new_due)
                        heapq.heappush(pq, new_due)

            round_num += 1

        # Trace update
        for w in watch:
            if values[w] != prev_value[w]:
                trace[w].append((t, values[w]))
                prev_value[w] = values[w]

    return trace

