                            changed.add(s)
                due_list = [(out, val) for out, (val, due) in pending.items() if due == t]
                for out, val in due_list:
                    if values[out] != val:
                        values[out] = val
                        changed.add(out)
                    del pending[out]
            else:
                due_list = [(out, val) for out, (val, due) in pending.items() if due == t]
                for out, val in due_list:
                    if values[out] != val:
                        values[out] = val
                        changed.add(out)
                    del pending[out]

