    # Cycle detection
    adj = {s: [] for s in all_signals}
    in_deg = {s: 0 for s in all_signals}
    for u, v in edges:
        if v not in adj[u]:
            adj[u].append(v)
            in_deg[v] += 1

    q = [s for s in all_signals if in_deg[s] == 0]
    cnt = 0
    while q:
        u = q.pop(0)
        cnt += 1
        for v in adj[u]:
            in_deg[v] -= 1
            if in_deg[v] == 0:
                q.append(v)
    if cnt != len(all_signals):
        raise ValueError("Cycle detected in signal graph")

    # Fan-in map
    fan_in = {s: [] for s in all_signals}
    for g_out, g in gates_by_out.items():
        for inp in g["ins"]:
            fan_in[inp].append(g_out)

    # Precompute stimulus map preserving order
    stim_map = {}
    for t, s, v in stimuli:
        if t <= until:
            stim_map.setdefault(t, []).append((s, v))

    # --- 2. Simulation ---
    pq = []
    if until >= 0:
        heapq.heappush(pq, 0)
    for t in stim_map:
        heapq.heappush(pq, t)

    processed = set()
    values = {s: 0 for s in all_signals}
    pending = {}
    trace = {w: [] for w in watch}
    prev_values = {w: 0 for w in watch}

    while pq:
        t = heapq.heappop(pq)
        if t > until or t in processed:
            continue
        processed.add(t)

        round_idx = 0
        while True:
            changed = set()
            start_values = {s: values[s] for s in all_signals}
            modified = set()

            # Batch Phase
            if round_idx == 0:
                if t in stim_map:
                    for s, v in stim_map[t]:
                        values[s] = v
                        modified.add(s)
                due_list = [(out, val) for out, (val, due) in pending.items() if due == t]
                for out, val in due_list:
                    values[out] = val
                    modified.add(out)
                    del pending[out]
            else:
                due_list = [(out, val) for out, (val, due) in pending.items() if due == t]
                for out, val in due_list:
                    values[out] = val
                    modified.add(out)
                    del pending[out]

            for s in modified:
                if values[s] != start_values[s]:
                    changed.add(s)

            # Evaluate Phase
            if t == 0 and round_idx == 0:
                gates_to_eval = list(gates_by_out.keys())
            else:
                eval_set = set()
                for s in changed:
                    if s in fan_in:
                        eval_set.update(fan_in[s])
                gates_to_eval = list(eval_set)

            for g_out in gates_to_eval:
                g = gates_by_out[g_out]
                if g_out in pending:
                    del pending[g_out]

                ins_vals = [values[inp] for inp in g["ins"]]
                op = g["op"]
                if op == "NOT": new_val = 1 - ins_vals[0]
                elif op == "BUF": new_val = ins_vals[0]
                elif op == "AND": new_val = 1 if all(ins_vals) else 0
                elif op == "OR": new_val = 1 if any(ins_vals) else 0
                elif op == "XOR": new_val = sum(ins_vals) % 2
                elif op == "NAND": new_val = 0 if all(ins_vals) else 1
                elif op == "NOR": new_val = 1 if not any(ins_vals) else 0
                else: new_val = 0

                if new_val != values[g_out]:
                    new_due = t + g["delay"]
                    if new_due <= until:
                        pending[g_out] = (new_val, new_due)
                        if new_due not in processed:
                            heapq.heappush(pq, new_due)

            if any(due == t for _, (_, due) in pending.items()):
                round_idx += 1
            else:
                break

        # Trace Update
        for w in watch:
            if values[w] != prev_values[w]:
                trace[w].append((t, values[w]))
                prev_values[w] = values[w]

    return trace

import heapq

def gate_trace(gates, stimuli, watch, until):
    # --- 1. Validation ---
    if not isinstance(gates, (list, tuple)): raise ValueError("gates must be a list or tuple")
    if not isinstance(stimuli, (list, tuple)): raise ValueError("stimuli must be a list or tuple")
    if not isinstance(watch, (list, tuple)): raise ValueError("watch must be a list or tuple")
    if isinstance(until, bool) or not isinstance(until, int) or not (0 <= until <= 10**12): raise ValueError("until must be an integer in range")
    if len(gates) > 60: raise ValueError("gates count exceeds 60")
    if len(stimuli) > 200: raise ValueError("stimuli count exceeds 200")

    valid_ops = {"AND", "OR", "XOR", "NAND", "NOR", "NOT", "BUF"}
    gates_by_out = {}
    all_signals = set()
    outputs = set()
    edges = []

    for i, g in enumerate(gates):
        if not isinstance(g, (list, tuple)) or len(g) != 4:
            raise ValueError(f"Gate {i} must be a 4-tuple")
        out, op, ins, delay = g
        if not isinstance(out, str) or not out:
            raise ValueError(f"Gate {i} out must be a non-empty string")
        if out in gates_by_out:
            raise ValueError(f"Duplicate gate output '{out}'")
        if op not in valid_ops:
            raise ValueError(f"Gate {i} invalid op '{op}'")
        if not isinstance(ins, (list, tuple)):
            raise ValueError(f"Gate {i} ins must be a list or tuple")
        for s in ins:
            if not isinstance(s, str) or not s:
                raise ValueError(f"Gate {i} ins contains invalid signal name")
        if isinstance(delay, bool) or not isinstance(delay, int) or not (0 <= delay <= 10**12):
            raise ValueError(f"Gate {i} delay must be an integer in range")

        if op in ("NOT", "BUF"):
            if len(ins) != 1:
                raise ValueError(f"Gate {i} ({op}) requires exactly 1 input")
        else:
            if len(ins) < 2 or len(ins) > 4:
                raise ValueError(f"Gate {i} ({op}) requires 2-4 inputs")

        gates_by_out[out] = {"out": out, "op": op, "ins": list(ins), "delay": delay}
        outputs.add(out)
        all_signals.add(out)
        for s in ins:
            all_signals.add(s)
            edges.append((s, out))

    for i, st in enumerate(stimuli):
        if not isinstance(st, (list, tuple)) or len(st) != 3:
            raise ValueError(f"Stimulus {i} must be a 3-tuple")
        time, signal, value = st
        if isinstance(time, bool) or not isinstance(time, int) or not (0 <= time <= 10**12):
            raise ValueError(f"Stimulus {i} time must be an integer in range")
        if not isinstance(signal, str) or not signal:
            raise ValueError(f"Stimulus {i} signal must be a non-empty string")
        if isinstance(value, bool) or not isinstance(value, int) or value not in (0, 1):
            raise ValueError(f"Stimulus {i} value must be 0 or 1")
        if signal not in all_signals:
            raise ValueError(f"Stimulus {i} signal '{signal}' is unknown")
        if signal in outputs:
            raise ValueError(f"Stimulus {i} signal '{signal}' is driven")

    for w in watch:
        if not isinstance(w, str) or not w:
            raise ValueError(f"Watch entry '{w}' invalid")
        if w not in all_signals:
            raise ValueError(f"Watch signal '{w}' is unknown")

    # Cycle detection
    adj = {s: [] for s in all_signals}
    in_deg = {s: 0 for s in all_signals}
    for u, v in edges:
        adj[u].append(v)
        in_deg[v] += 1

    q = [s for s in all_signals if in_deg[s] == 0]
    cnt = 0
    while q:
        u = q.pop(0)
        cnt += 1
        for v in adj[u]:
            in_deg[v] -= 1
            if in_deg[v] == 0:
                q.append(v)
    if cnt != len(all_signals):
        raise ValueError("Cycle detected in signal graph")

    # Fan-in map
    fan_in = {s: [] for s in all_signals}
    for g_out, g in gates_by_out.items():
        for inp in g["ins"]:
            fan_in[inp].append(g_out)

    # Precompute stimulus map preserving order
    stim_map = {}
    for t, s, v in stimuli:
        if t <= until:
            stim_map.setdefault(t, []).append((s, v))

    # --- 2. Simulation ---
    pq = []
    if until >= 0:
        heapq.heappush(pq, 0)
    for t in stim_map:
        heapq.heappush(pq, t)

    processed = set()
    values = {s: 0 for s in all_signals}
    pending = {}
    trace = {w: [] for w in watch}
    prev_values = {w: 0 for w in watch}

    while pq:
        t = heapq.heappop(pq)
        if t > until or t in processed:
            continue
        processed.add(t)

        round_idx = 0
        while True:
            changed = set()
            start_values = {s: values[s] for s in all_signals}
            modified = set()

            # Batch Phase
            if round_idx == 0:
                if t in stim_map:
                    for s, v in stim_map[t]:
                        values[s] = v
                        modified.add(s)
                due_list = [(out, val) for out, (val, due) in pending.items() if due == t]
                for out, val in due_list:
                    values[out] = val
                    modified.add(out)
                    del pending[out]
            else:
                due_list = [(out, val) for out, (val, due) in pending.items() if due == t]
                for out, val in due_list:
                    values[out] = val
                    modified.add(out)
                    del pending[out]

            for s in modified:
                if values[s] != start_values[s]:
                    changed.add(s)

            # Evaluate Phase
            if t == 0 and round_idx == 0:
                gates_to_eval = list(gates_by_out.keys())
            else:
                eval_set = set()
                for s in changed:
                    if s in fan_in:
                        eval_set.update(fan_in[s])
                gates_to_eval = list(eval_set)

            for g_out in gates_to_eval:
                g = gates_by_out[g_out]
                if g_out in pending:
                    del pending[g_out]

                ins_vals = [values[inp] for inp in g["ins"]]
                op = g["op"]
                if op == "NOT": new_val = 1 - ins_vals[0]
                elif op == "BUF": new_val = ins_vals[0]
                elif op == "AND": new_val = 1 if all(ins_vals) else 0
                elif op == "OR": new_val = 1 if any(ins_vals) else 0
                elif op == "XOR": new_val = sum(ins_vals) % 2
                elif op == "NAND": new_val = 0 if all(ins_vals) else 1
                elif op == "NOR": new_val = 1 if not any(ins_vals) else 0
                else: new_val = 0

                if new_val != values[g_out]:
                    new_due = t + g["delay"]
                    if new_due <= until:
                        pending[g_out] = (new_val, new_due)
                        if new_due not in processed:
                            heapq.heappush(pq, new_due)

            if any(due == t for _, (_, due) in pending.items()):
                round_idx += 1
            else:
                break

        # Trace Update
        for w in watch:
            if values[w] != prev_values[w]:
                trace[w].append((t, values[w]))
                prev_values[w] = values[w]

    return trace

import sys

# Prevent recursion limit issues for deeply nested terms
sys.setrecursionlimit(10000)

class TVar:
    def __init__(self, id):
        self.id = id
    def __repr__(self): return f"TVar({self.id})"

class Int: pass
class Bool: pass
class Str: pass
class Unit: pass

class List:
    def __init__(self, elem): self.elem = elem
class Ref:
    def __init__(self, content): self.content = content

class Func:
    def __init__(self, params, ret):
        self.params = params
        self.ret = ret

class Scheme:
    def __init__(self, quantified_vars, type_):
        self.quantified_vars = set(quantified_vars)
        self.type_ = type_
    def instantiate(self, fresh_id_counter):
        subst = {}
        for tv in self.quantified_vars:
            fresh_id_counter[0] += 1
            subst[tv.id] = TVar(fresh_id_counter[0])
        return apply(self.type_, subst)

def apply(t, subst):
    if isinstance(t, TVar):
        while t.id in subst:
            t = subst[t.id]
        return t
    elif isinstance(t, List):
        return List(apply(t.elem, subst))
    elif isinstance(t, Ref):
        return Ref(apply(t.content, subst))
    elif isinstance(t, Func):
        return Func(tuple(apply(p, subst) for p in t.params), apply(t.ret, subst))
    return t

def occurs(id, t):
    t = apply(t, {})
    if isinstance(t, TVar):
        return t.id == id
    elif isinstance(t, List):
        return occurs(id, t.elem)
    elif isinstance(t, Ref):
        return occurs(id, t.content)
    elif isinstance(t, Func):
        return any(occurs(id, p) for p in t.params) or occurs(id, t.ret)
    return False

def unify(t1, t2, subst):
    t1 = apply(t1, subst)
    t2 = apply(t2, subst)
    if isinstance(t1, TVar) and isinstance(t2, TVar):
        if t1.id != t2.id:
            subst[t1.id] = t2
    elif isinstance(t1, TVar):
        if occurs(t1.id, t2):
            raise ValueError("Infinite type")
        subst[t1.id] = t2
    elif isinstance(t2, TVar):
        if occurs(t2.id, t1):
            raise ValueError("Infinite type")
        subst[t2.id] = t1
    elif isinstance(t1, Int) and isinstance(t2, Int):
        pass
    elif isinstance(t1, Bool) and isinstance(t2, Bool):
        pass
    elif isinstance(t1, Str) and isinstance(t2, Str):
        pass
    elif isinstance(t1, Unit) and isinstance(t2, Unit):
        pass
    elif isinstance(t1, List) and isinstance(t2, List):
        unify(t1.elem, t2.elem, subst)
    elif isinstance(t1, Ref) and isinstance(t2, Ref):
        unify(t1.content, t2.content, subst)
    elif isinstance(t1, Func) and isinstance(t2, Func):
        if len(t1.params) != len(t2.params):
            raise ValueError("Arity mismatch")
        for p1, p2 in zip(t1.params, t2.params):
            unify(p1, p2, subst)
        unify(t1.ret, t2.ret, subst)
    else:
        raise ValueError("Type mismatch")
    return subst

def get_free_vars(t):
    if isinstance(t, TVar):
        return {t.id}
    elif isinstance(t, List):
        return get_free_vars(t.elem)
    elif isinstance(t, Ref):
        return get_free_vars(t.content)
    elif isinstance(t, Func):
        res = set()
        for p in t.params:
            res |= get_free_vars(p)
        res |= get_free_vars(t.ret)
        return res
    return set()

def get_free_vars_in_env(env):
    res = set()
    for scope in env:
        for name, type_ in scope.items():
            if isinstance(type_, Scheme):
                continue
            elif isinstance(type_, Type):
                res |= get_free_vars(type_)
    return res

def check_malformed(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")
    tag, *args = term
    if not isinstance(tag, str):
        raise ValueError("Malformed tag")

    if tag == "int":
        if len(args) != 1 or not isinstance(args[0], int) or isinstance(args[0], bool):
            raise ValueError("Malformed int")
    elif tag == "bool":
        if len(args) != 1 or not isinstance(args[0], bool):
            raise ValueError("Malformed bool")
    elif tag == "str":
        if len(args) != 1 or not isinstance(args[0], str):
            raise ValueError("Malformed str")
    elif tag == "unit":
        if len(args) != 0:
            raise ValueError("Malformed unit")
    elif tag == "var":
        if len(args) != 1 or not isinstance(args[0], str) or not args[0]:
            raise ValueError("Malformed var")
    elif tag == "fn":
        if len(args) != 2:
            raise ValueError("Malformed fn")
        params, body = args
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("Malformed fn params")
        if len(set(params)) != len(params):
            raise ValueError("Duplicate fn params")
        if not all(isinstance(p, str) and p for p in params):
            raise ValueError("Malformed fn param names")
        check_malformed(body)
    elif tag == "call":
        if len(args) != 2:
            raise ValueError("Malformed call")
        f, arg_list = args
        if not isinstance(arg_list, tuple) or len(arg_list) == 0:
            raise ValueError("Malformed call args")
        check_malformed(f)
        for arg in arg_list:
            check_malformed(arg)
    elif tag == "let":
        if len(args) != 3:
            raise ValueError("Malformed let")
        name, e1, e2 = args
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed let name")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "letrec":
        if len(args) != 3:
            raise ValueError("Malformed letrec")
        name, e1, e2 = args
        if not isinstance(name, str) or not name:
            raise ValueError("Malformed letrec name")
        check_malformed(e1)
        check_malformed(e2)
        if e1[0] != "fn":
            raise ValueError("letrec e1 must be fn")
    elif tag == "nil":
        if len(args) != 0:
            raise ValueError("Malformed nil")
    elif tag == "cons":
        if len(args) != 2:
            raise ValueError("Malformed cons")
        check_malformed(args[0])
        check_malformed(args[1])
    elif tag == "match":
        if len(args) != 5:
            raise ValueError("Malformed match")
        s, e_nil, hn, tn, e_cons = args
        if not isinstance(hn, str) or not hn:
            raise ValueError("Malformed match hn")
        if not isinstance(tn, str) or not tn:
            raise ValueError("Malformed match tn")
        if hn == tn:
            raise ValueError("match hn and tn must differ")
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(e_cons)
    elif tag == "ref":
        if len(args) != 1:
            raise ValueError("Malformed ref")
        check_malformed(args[0])
    elif tag == "get":
        if len(args) != 1:
            raise ValueError("Malformed get")
        check_malformed(args[0])
    elif tag == "set":
        if len(args) != 2:
            raise ValueError("Malformed set")
        check_malformed(args[0])
        check_malformed(args[1])
    else:
        raise ValueError("Unknown tag")

def is_value(term):
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "nil"):
        return True
    elif tag == "fn":
        return True
    elif tag == "cons":
        h, t = term[1], term[2]
        return is_value(h) and is_value(t)
    return False

def lookup(name, env):
    for scope in env:
        if name in scope:
            return scope[name]
    raise ValueError(f"Unbound variable: {name}")

def infer(term, env, ctx):
    tag = term[0]
    args = term[1:]

    if tag == "int":
        return Int()
    elif tag == "bool":
        return Bool()
    elif tag == "str":
        return Str()
    elif tag == "unit":
        return Unit()
    elif tag == "var":
        name = args[0]
        type_ = lookup(name, env)
        if isinstance(type_, Scheme):
            return type_.instantiate(ctx)
        else:
            return apply(type_, ctx.subst)
    elif tag == "fn":
        _, params, body = term
        param_types = tuple(TVar(ctx.fresh_id_counter[0] + i + 1) for i in range(len(params)))
        ctx.fresh_id_counter[0] += len(params)
        new_env = env + [{p: t for p, t in zip(params, param_types)}]
        body_type = infer(body, new_env, ctx)
        return Func(param_types, body_type)
    elif tag == "call":
        _, f, arg_terms = term
        f_type = infer(f, env, ctx)
        arg_types = [infer(a, env, ctx) for a in arg_terms]
        if not isinstance(f_type, Func):
            raise ValueError("Call on non-function")
        f_type = apply(f_type, ctx.subst)
        if len(f_type.params) != len(arg_types):
            raise ValueError("Arity mismatch")
        for p, a in zip(f_type.params, arg_types):
            unify(p, a, ctx.subst)
        return apply(f_type.ret, ctx.subst)
    elif tag == "let":
        _, name, e1, e2 = term
        e1_type = infer(e1, env, ctx)
        if is_value(e1):
            e1_type = apply(e1_type, ctx.subst)
            free_vars = get_free_vars(e1_type)
            env_vars = get_free_vars_in_env(env)
            quantified = free_vars - env_vars
            if quantified:
                scheme = Scheme(quantified, e1_type)
            else:
                scheme = Scheme(frozenset(), e1_type)
            new_env = env + [{name: scheme}]
        else:
            new_env = env + [{name: apply(e1_type, ctx.subst)}]
        return infer(e2, new_env, ctx)
    elif tag == "letrec":
        _, name, e1, e2 = term
        rec_var = TVar(ctx.fresh_id_counter[0] + 1)
        ctx.fresh_id_counter[0] += 1
        new_env = env + [{name: rec_var}]
        e1_type = infer(e1, new_env, ctx)
        e1_type = apply(e1_type, ctx.subst)
        free_vars = get_free_vars(e1_type)
        env_vars_before = get_free_vars_in_env(env)
        quantified = free_vars - env_vars_before
        scheme = Scheme(quantified, e1_type)
        new_env2 = env + [{name: scheme}]
        return infer(e2, new_env2, ctx)
    elif tag == "nil":
        return List(TVar(ctx.fresh_id_counter[0] + 1))
    elif tag == "cons":
        h, t = args
        h_type = infer(h, env, ctx)
        t_type = infer(t, env, ctx)
        elem_var = TVar(ctx.fresh_id_counter[0] + 1)
        ctx.fresh_id_counter[0] += 1
        unify(t_type, List(elem_var), ctx.subst)
        unify(h_type, elem_var, ctx.subst)
        return List(apply(elem_var, ctx.subst))
    elif tag == "match":
        s, e_nil, hn, tn, e_cons = args
        s_type = infer(s, env, ctx)
        A = TVar(ctx.fresh_id_counter[0] + 1)
        ctx.fresh_id_counter[0] += 1
        unify(s_type, List(A), ctx.subst)
        new_env = env + [{hn: A, tn: List(A)}]
        t_nil = infer(e_nil, new_env, ctx)
        t_cons = infer(e_cons, new_env, ctx)
        unify(t_nil, t_cons, ctx.subst)
        return apply(t_nil, ctx.subst)
    elif tag == "ref":
        e = args[0]
        e_type = infer(e, env, ctx)
        return Ref(e_type)
    elif tag == "get":
        r = args[0]
        r_type = infer(r, env, ctx)
        if not isinstance(r_type, Ref):
            raise ValueError("Get on non-ref")
        return apply(r_type.content, ctx.subst)
    elif tag == "set":
        r, e = args
        r_type = infer(r, env, ctx)
        e_type = infer(e, env, ctx)
        if not isinstance(r_type, Ref):
            raise ValueError("Set on non-ref")
        unify(r_type.content, e_type, ctx.subst)
        return Unit()
    else:
        raise ValueError("Unknown tag")

def collect_vars_preorder(t, visited, order):
    if isinstance(t, TVar):
        if t.id not in visited:
            visited.add(t.id)
            order.append(t.id)
    elif isinstance(t, List):
        collect_vars_preorder(t.elem, visited, order)
    elif isinstance(t, Ref):
        collect_vars_preorder(t.content, visited, order)
    elif isinstance(t, Func):
        for p in t.params:
            collect_vars_preorder(p, visited, order)
        collect_vars_preorder(t.ret, visited, order)

def print_type(t):
    t = apply(t, {})
    visited = set()
    order = []
    collect_vars_preorder(t, visited, order)
    var_map = {vid: f"t{i+1}" for i, vid in enumerate(order)}

    def fmt(t):
        if isinstance(t, TVar):
            return var_map[t.id]
        elif isinstance(t, Int):
            return "Int"
        elif isinstance(t, Bool):
            return "Bool"
        elif isinstance(t, Str):
            return "Str"
        elif isinstance(t, Unit):
            return "Unit"
        elif isinstance(t, List):
            return f"List<{fmt(t.elem)}>"
        elif isinstance(t, Ref):
            return f"Ref<{fmt(t.content)}>"
        elif isinstance(t, Func):
            params_str = ", ".join(fmt(p) for p in t.params)
            ret_str = fmt(t.ret)
            if len(t.params) == 1:
                p_str = fmt(t.params[0])
                if isinstance(t.params[0], Func):
                    return f"({p_str}) -> {ret_str}"
                else:
                    return f"{p_str} -> {ret_str}"
            else:
                return f"({params_str}) -> {ret_str}"
        return "?"
    return fmt(t)

def weak_infer(term):
    check_malformed(term)
    fresh_id_counter = [0]
    # Create initial schemes
    a = TVar(fresh_id_counter[0] + 1)
    fresh_id_counter[0] += 1
    init_schemes = [
        {"plus": Scheme(frozenset(), Func((Int(), Int()), Int()))},
        {"eq": Scheme(frozenset({a.id}), Func((a, a), Bool()))},
        {"size": Scheme(frozenset(), Func((Str(),), Int()))}
    ]
    ctx = type('Ctx', (), {'fresh_id_counter': fresh_id_counter, 'subst': {}})()
    env = init_schemes
    result_type = infer(term, env, ctx)
    return print_type(result_type)

class TVar:
    __slots__ = ('id',)
    def __init__(self, id): self.id = id
    def __eq__(self, other): return isinstance(other, TVar) and self.id == other.id
    def __hash__(self): return self.id

class Int: pass
class Bool: pass
class Str: pass
class Unit: pass
class List:
    __slots__ = ('T',)
    def __init__(self, T): self.T = T
    def __eq__(self, other): return isinstance(other, List) and self.T == other.T
class Ref:
    __slots__ = ('T',)
    def __init__(self, T): self.T = T
    def __eq__(self, other): return isinstance(other, Ref) and self.T == other.T
class Func:
    __slots__ = ('params', 'ret')
    def __init__(self, params, ret): self.params = params; self.ret = ret
    def __eq__(self, other): return isinstance(other, Func) and self.params == other.params and self.ret == other.ret

def free_vars(t):
    if isinstance(t, TVar): return {t.id}
    if isinstance(t, Func):
        res = set()
        for p in t.params: res.update(free_vars(p))
        res.update(free_vars(t.ret))
        return res
    if isinstance(t, (List, Ref)): return free_vars(t.T)
    return set()

def free_vars_in_env(env):
    res = set()
    for d in env:
        for typ, poly in d.values():
            res.update(free_vars(typ))
    return res

def apply(sub, t):
    if isinstance(t, TVar):
        return sub.get(t.id, t)
    if isinstance(t, Func):
        return Func(tuple(apply(sub, p) for p in t.params), apply(sub, t.ret))
    if isinstance(t, (List, Ref)):
        return type(t)(apply(sub, t.T))
    return t

def compose(s1, s2):
    return {k: apply(s1, v) for k, v in s2.items()} | {k: v for k, v in s1.items() if k not in s2}

def occurs(id, t):
    if isinstance(t, TVar): return t.id == id
    if isinstance(t, Func):
        return occurs(id, t.ret) or any(occurs(id, p) for p in t.params)
    if isinstance(t, (List, Ref)): return occurs(id, t.T)
    return False

def unify(t1, t2, sub):
    if t1 == t2: return sub
    if isinstance(t1, TVar):
        if t1.id in sub: return unify(sub[t1.id], t2, sub)
        if occurs(t1.id, t2): raise ValueError("Infinite type")
        return compose(sub, {t1.id: t2})
    if isinstance(t2, TVar): return unify(t2, t1, sub)
    if type(t1) != type(t2): raise ValueError("Type mismatch")
    if isinstance(t1, Func):
        if len(t1.params) != len(t2.params): raise ValueError("Arity mismatch")
        sub = unify(t1.ret, t2.ret, sub)
        for p1, p2 in zip(t1.params, t2.params):
            sub = unify(p1, p2, sub)
        return sub
    if isinstance(t1, (List, Ref)):
        return unify(t1.T, t2.T, sub)
    raise ValueError("Unknown type")

def is_value(term):
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"): return True
    if tag == "cons":
        return is_value(term[1]) and is_value(term[2])
    return False

def check_malformed(term):
    if not isinstance(term, tuple) or len(term) == 0: raise ValueError("Malformed")
    tag = term[0]
    if not isinstance(tag, str): raise ValueError("Malformed")
    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool): raise ValueError("Malformed")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool): raise ValueError("Malformed")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str): raise ValueError("Malformed")
    elif tag == "unit":
        if len(term) != 1: raise ValueError("Malformed")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed")
    elif tag == "fn":
        if len(term) != 3: raise ValueError("Malformed")
        params = term[1]
        if not isinstance(params, tuple) or len(params) == 0: raise ValueError("Malformed")
        if len(set(params)) != len(params): raise ValueError("Malformed")
        if not all(isinstance(p, str) and p for p in params): raise ValueError("Malformed")
        check_malformed(term[2])
    elif tag == "call":
        if len(term) != 3: raise ValueError("Malformed")
        if not isinstance(term[2], tuple) or len(term[2]) == 0: raise ValueError("Malformed")
        check_malformed(term[1])
        for a in term[2]: check_malformed(a)
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed")
        check_malformed(term[2])
        check_malformed(term[3])
    elif tag == "letrec":
        if len(term) != 4: raise ValueError("Malformed")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed")
        check_malformed(term[2])
        if term[2][0] != "fn": raise ValueError("Malformed")
        check_malformed(term[3])
    elif tag == "nil":
        if len(term) != 1: raise ValueError("Malformed")
    elif tag == "cons":
        if len(term) != 3: raise ValueError("Malformed")
        check_malformed(term[1])
        check_malformed(term[2])
    elif tag == "match":
        if len(term) != 5: raise ValueError("Malformed")
        if term[2] == term[3]: raise ValueError("Malformed")
        check_malformed(term[1])
        check_malformed(term[2])
        check_malformed(term[3])
        check_malformed(term[4])
    elif tag == "ref":
        if len(term) != 2: raise ValueError("Malformed")
        check_malformed(term[1])
    elif tag == "get":
        if len(term) != 2: raise ValueError("Malformed")
        check_malformed(term[1])
    elif tag == "set":
        if len(term) != 3: raise ValueError("Malformed")
        check_malformed(term[1])
        check_malformed(term[2])
    else:
        raise ValueError("Malformed")

class FreshId:
    def __init__(self): self.c = 0
    def next(self): self.c += 1; return self.c

def make_initial_env(fresh):
    env = []
    t1, t2 = TVar(fresh.next()), TVar(fresh.next())
    env.append({"plus": (Func((t1, t2), Int()), set())})
    t3 = TVar(fresh.next())
    env.append({"eq": (Func((t3, t3), Bool()), {t3.id})})
    env.append({"size": (Func((Str(),), Int()), set())})
    return env

def infer(term, env, fresh):
    tag = term[0]
    if tag == "int": return Int()
    if tag == "bool": return Bool()
    if tag == "str": return Str()
    if tag == "unit": return Unit()
    if tag == "var":
        name = term[1]
        for d in env:
            if name in d:
                typ, poly_vars = d[name]
                inst = {pid: TVar(fresh.next()) for pid in poly_vars}
                return apply(inst, typ)
        raise ValueError("Unbound variable")
    if tag == "fn":
        params = term[1]
        body = term[2]
        param_types = [TVar(fresh.next()) for _ in params]
        new_env = [{p: (t, set()) for p, t in zip(params, param_types)}] + env
        body_type = infer(body, new_env, fresh)
        return Func(tuple(param_types), body_type)
    if tag == "call":
        f = term[1]
        args = term[2]
        f_type = infer(f, env, fresh)
        if not isinstance(f_type, Func): raise ValueError("Type mismatch")
        if len(f_type.params) != len(args): raise ValueError("Arity mismatch")
        arg_types = [infer(a, env, fresh) for a in args]
        sub = unify(f_type, Func(tuple(arg_types), f_type.ret), {})
        return apply(sub, f_type.ret)
    if tag == "let":
        name = term[1]
        e1 = term[2]
        e2 = term[3]
        e1_type = infer(e1, env, fresh)
        if is_value(e1):
            env_vars = free_vars_in_env(env)
            poly = free_vars(e1_type) - env_vars
            new_env = [{name: (e1_type, poly)}] + env
        else:
            new_env = [{name: (e1_type, set())}] + env
        return infer(e2, new_env, fresh)
    if tag == "letrec":
        name = term[1]
        e1 = term[2]
        e2 = term[3]
        f_type = TVar(fresh.next())
        new_env = [{name: (f_type, set())}] + env
        e1_type = infer(e1, new_env, fresh)
        if not isinstance(e1_type, Func): raise ValueError("Type mismatch")
        env_vars_before = free_vars_in_env(env)
        poly = free_vars(e1_type) - env_vars_before
        new_env2 = [{name: (e1_type, poly)}] + env
        return infer(e2, new_env2, fresh)
    if tag == "nil":
        return List(TVar(fresh.next()))
    if tag == "cons":
        h = term[1]
        t = term[2]
        h_type = infer(h, env, fresh)
        t_type = infer(t, env, fresh)
        elem = TVar(fresh.next())
        sub = unify(t_type, List(elem), {})
        unify(h_type, elem, sub)
        return List(apply(sub, elem))
    if tag == "match":
        s = term[1]
        e_nil = term[2]
        hn = term[3]
        tn = term[4]
        e_cons = term[5]
        s_type = infer(s, env, fresh)
        A = TVar(fresh.next())
        sub = unify(s_type, List(A), {})
        new_env = [{hn: (apply(sub, A), set()), tn: (List(apply(sub, A)), set())}] + env
        t_nil = infer(e_nil, new_env, fresh)
        t_cons = infer(e_cons, new_env, fresh)
        unify(t_nil, t_cons, {})
        return t_nil
    if tag == "ref":
        e = term[1]
        e_type = infer(e, env, fresh)
        return Ref(e_type)
    if tag == "get":
        r = term[1]
        r_type = infer(r, env, fresh)
        T = TVar(fresh.next())
        unify(r_type, Ref(T), {})
        return T
    if tag == "set":
        r = term[1]
        e = term[2]
        r_type = infer(r, env, fresh)
        e_type = infer(e, env, fresh)
        T = TVar(fresh.next())
        unify(r_type, Ref(T), {})
        unify(e_type, T, {})
        return Unit()
    raise ValueError("Unknown tag")

def print_type(t):
    ids = []
    id_map = {}
    def get_id(tv):
        if tv.id not in id_map:
            id_map[tv.id] = len(ids) + 1
            ids.append(tv.id)
        return id_map[tv.id]

    def fmt(t):
        if isinstance(t, TVar):
            return f"t{get_id(t)}"
        if isinstance(t, Int): return "Int"
        if isinstance(t, Bool): return "Bool"
        if isinstance(t, Str): return "Str"
        if isinstance(t, Unit): return "Unit"
        if isinstance(t, List): return f"List<{fmt(t.T)}>"
        if isinstance(t, Ref): return f"Ref<{fmt(t.T)}>"
        if isinstance(t, Func):
            params_str = ", ".join(fmt(p) for p in t.params)
            ret_str = fmt(t.ret)
            if len(t.params) == 1:
                p = t.params[0]
                if isinstance(p, Func):
                    return f"({fmt(p)}) -> {ret_str}"
                else:
                    return f"{fmt(p)} -> {ret_str}"
            else:
                return f"({params_str}) -> {ret_str}"
        return ""

    return fmt(t)

def weak_infer(term: tuple) -> str:
    check_malformed(term)
    fresh = FreshId()
    env = make_initial_env(fresh)
    t = infer(term, env, fresh)
    return print_type(t)

import itertools

class TVar:
    __slots__ = ('id',)
    def __init__(self, id): self.id = id
    def __repr__(self): return f"TVar({self.id})"
    def __eq__(self, other): return isinstance(other, TVar) and self.id == other.id
    def __hash__(self): return self.id

class Int: pass
class Bool: pass
class Str: pass
class Unit: pass

class ListT:
    __slots__ = ('t',)
    def __init__(self, t): self.t = t
    def __eq__(self, other): return isinstance(other, ListT) and self.t == other.t
    def __hash__(self): return hash(('List', self.t))

class RefT:
    __slots__ = ('t',)
    def __init__(self, t): self.t = t
    def __eq__(self, other): return isinstance(other, RefT) and self.t == other.t
    def __hash__(self): return hash(('Ref', self.t))

class Func:
    __slots__ = ('params', 'ret')
    def __init__(self, params, ret): self.params = params; self.ret = ret
    def __eq__(self, other): return isinstance(other, Func) and self.params == other.params and self.ret == other.ret
    def __hash__(self): return hash(('Func', self.params, self.ret))

def _fresh():
    return TVar(next(_counter))

_counter = itertools.count(1)

def free_vars(t):
    if isinstance(t, TVar): return {t.id}
    if isinstance(t, (Int, Bool, Str, Unit)): return set()
    if isinstance(t, ListT): return free_vars(t.t)
    if isinstance(t, RefT): return free_vars(t.t)
    if isinstance(t, Func):
        fv = set()
        for p in t.params: fv |= free_vars(p)
        fv |= free_vars(t.ret)
        return fv
    return set()

def apply(sub, t):
    if isinstance(t, TVar):
        res = sub.get(t.id)
        if res is not None: return apply(sub, res)
        return t
    if isinstance(t, (Int, Bool, Str, Unit)): return t
    if isinstance(t, ListT):
        new_t = apply(sub, t.t)
        return ListT(new_t) if new_t is not t.t else t
    if isinstance(t, RefT):
        new_t = apply(sub, t.t)
        return RefT(new_t) if new_t is not t.t else t
    if isinstance(t, Func):
        new_params = tuple(apply(sub, p) for p in t.params)
        new_ret = apply(sub, t.ret)
        if new_params is t.params and new_ret is t.ret: return t
        return Func(new_params, new_ret)
    return t

def unify(t1, t2, sub=None):
    if sub is None: sub = {}
    t1 = apply(sub, t1)
    t2 = apply(sub, t2)
    if t1 == t2: return sub
    if isinstance(t1, TVar):
        if t1.id in free_vars(t2): raise ValueError("Infinite type")
        return {**sub, t1.id: t2}
    if isinstance(t2, TVar):
        if t2.id in free_vars(t1): raise ValueError("Infinite type")
        return {**sub, t2.id: t1}
    if isinstance(t1, ListT) and isinstance(t2, ListT):
        return unify(t1.t, t2.t, sub)
    if isinstance(t1, RefT) and isinstance(t2, RefT):
        return unify(t1.t, t2.t, sub)
    if isinstance(t1, Func) and isinstance(t2, Func):
        if len(t1.params) != len(t2.params): raise ValueError("Arity mismatch")
        for p1, p2 in zip(t1.params, t2.params):
            sub = unify(p1, p2, sub)
        return unify(t1.ret, t2.ret, sub)
    raise ValueError("Type mismatch")

def is_value(term):
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "nil"): return True
    if tag == "fn": return True
    if tag == "cons":
        return is_value(term[1]) and is_value(term[2])
    return False

def generalize(t, env, sub):
    t_applied = apply(sub, t)
    fv_t = free_vars(t_applied)
    fv_env = set()
    for scope in env:
        for ty in scope.values():
            fv_env |= free_vars(apply(sub, ty))
    # In HM, generalization means quantifying vars not free in env.
    # We just return the type; the printer will handle var naming.
    # The "monomorphic sharing" for non-values is handled by not generalizing.
    return t_applied

def check_malformed(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed: not a non-empty tuple")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed: tag not str")

    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
            raise ValueError("Malformed int")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed bool")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed str")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Malformed unit")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or len(term[1]) == 0:
            raise ValueError("Malformed var")
    elif tag == "fn":
        if len(term) != 3: raise ValueError("Malformed fn")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0: raise ValueError("Malformed fn params")
        if len(set(params)) != len(params): raise ValueError("Malformed fn params distinct")
        if not all(isinstance(p, str) and len(p) > 0 for p in params): raise ValueError("Malformed fn params")
        check_malformed(body)
    elif tag == "call":
        if len(term) != 3: raise ValueError("Malformed call")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or len(args) == 0: raise ValueError("Malformed call args")
        check_malformed(f)
        for a in args: check_malformed(a)
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed let")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0: raise ValueError("Malformed let name")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "letrec":
        if len(term) != 4: raise ValueError("Malformed letrec")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0: raise ValueError("Malformed letrec name")
        if not isinstance(e1, tuple) or e1[0] != "fn": raise ValueError("Malformed letrec e1 not fn")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "nil":
        if len(term) != 1: raise ValueError("Malformed nil")
    elif tag == "cons":
        if len(term) != 3: raise ValueError("Malformed cons")
        check_malformed(term[1])
        check_malformed(term[2])
    elif tag == "match":
        if len(term) != 5: raise ValueError("Malformed match")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(hn, str) or not isinstance(tn, str) or hn == tn:
            raise ValueError("Malformed match hn/tn")
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(e_cons)
    elif tag == "ref":
        if len(term) != 2: raise ValueError("Malformed ref")
        check_malformed(term[1])
    elif tag == "get":
        if len(term) != 2: raise ValueError("Malformed get")
        check_malformed(term[1])
    elif tag == "set":
        if len(term) != 3: raise ValueError("Malformed set")
        check_malformed(term[1])
        check_malformed(term[2])
    else:
        raise ValueError(f"Malformed unknown tag: {tag}")

def infer(term, env, sub):
    tag = term[0]
    if tag == "int": return (Int, sub)
    if tag == "bool": return (Bool, sub)
    if tag == "str": return (Str, sub)
    if tag == "unit": return (Unit, sub)
    if tag == "var":
        name = term[1]
        for scope in env:
            if name in scope:
                return (apply(sub, scope[name]), sub)
        raise ValueError("Unbound variable")
    if tag == "fn":
        params, body = term[1], term[2]
        param_types = [_fresh() for _ in params]
        new_env = [{p: pt for p, pt in zip(params, param_types)}] + env
        body_type, sub = infer(body, new_env, sub)
        return (Func(tuple(param_types), body_type), sub)
    if tag == "call":
        f, args = term[1], term[2]
        f_type, sub = infer(f, env, sub)
        arg_types = []
        for a in args:
            at, sub = infer(a, env, sub)
            arg_types.append(at)
        if isinstance(f_type, Func):
            if len(f_type.params) != len(arg_types):
                raise ValueError("Arity mismatch")
            for p, at in zip(f_type.params, arg_types):
                sub = unify(p, at, sub)
            return (apply(sub, f_type.ret), sub)
        else:
            raise ValueError("Not a function")
    if tag == "let":
        name, e1, e2 = term[1], term[2], term[3]
        e1_type, sub = infer(e1, env, sub)
        if is_value(e1):
            gen_type = generalize(e1_type, env, sub)
        else:
            gen_type = e1_type
        new_env = [{name: gen_type}] + env
        return infer(e2, new_env, sub)
    if tag == "letrec":
        name, e1, e2 = term[1], term[2], term[3]
        params, body = e1[1], e1[2]
        name_type = _fresh()
        new_env = [{name: name_type}] + env
        e1_type, sub = infer(e1, new_env, sub)
        if not isinstance(e1_type, Func):
            raise ValueError("letrec e1 not function")
        gen_type = generalize(e1_type, env, sub)
        new_env2 = [{name: gen_type}] + env
        return infer(e2, new_env2, sub)
    if tag == "nil":
        t = _fresh()
        return (ListT(t), sub)
    if tag == "cons":
        h, t_term = term[1], term[2]
        h_type, sub = infer(h, env, sub)
        t_type, sub = infer(t_term, env, sub)
        elem = _fresh()
        sub = unify(t_type, ListT(elem), sub)
        sub = unify(h_type, elem, sub)
        return (ListT(elem), sub)
    if tag == "match":
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        s_type, sub = infer(s, env, sub)
        A = _fresh()
        sub = unify(s_type, ListT(A), sub)
        new_env = [{hn: A, tn: ListT(A)}] + env
        t_nil, sub = infer(e_nil, new_env, sub)
        t_cons, sub = infer(e_cons, new_env, sub)
        sub = unify(t_nil, t_cons, sub)
        return (apply(sub, t_nil), sub)
    if tag == "ref":
        e, = term[1:]
        e_type, sub = infer(e, env, sub)
        return (RefT(e_type), sub)
    if tag == "get":
        r, = term[1:]
        r_type, sub = infer(r, env, sub)
        if isinstance(r_type, RefT):
            return (r_type.t, sub)
        raise ValueError("Not a ref")
    if tag == "set":
        r, e = term[1], term[2]
        r_type, sub = infer(r, env, sub)
        e_type, sub = infer(e, env, sub)
        if isinstance(r_type, RefT):
            sub = unify(r_type.t, e_type, sub)
            return (Unit, sub)
        raise ValueError("Not a ref")
    raise ValueError("Unknown tag")

def print_type(t):
    seen = {}
    counter = [1]
    def collect(tt):
        if isinstance(tt, TVar):
            if tt.id not in seen:
                seen[tt.id] = f"t{counter[0]}"
                counter[0] += 1
        elif isinstance(tt, ListT):
            collect(tt.t)
        elif isinstance(tt, RefT):
            collect(tt.t)
        elif isinstance(tt, Func):
            for p in tt.params:
                collect(p)
            collect(tt.ret)
    collect(t)

    def fmt(tt):
        if isinstance(tt, TVar):
            return seen[tt.id]
        if isinstance(tt, (Int, Bool, Str, Unit)):
            return tt.__class__.__name__
        if isinstance(tt, ListT):
            return f"List<{fmt(tt.t)}>"
        if isinstance(tt, RefT):
            return f"Ref<{fmt(tt.t)}>"
        if isinstance(tt, Func):
            params = tt.params
            ret = fmt(tt.ret)
            if len(params) == 1:
                p = fmt(params[0])
                if isinstance(params[0], Func):
                    return f"({p}) -> {ret}"
                return f"{p} -> {ret}"
            else:
                ps = ", ".join(fmt(p) for p in params)
                return f"({ps}) -> {ret}"
        return str(tt)
    return fmt(t)

def weak_infer(term):
    # Reset counter for each top-level call to ensure t1, t2... order
    global _counter
    _counter = itertools.count(1)

    check_malformed(term)

    a = _fresh()
    init_env = [{
        "plus": Func((Int, Int), Int),
        "eq": Func((a, a), Bool),
        "size": Func((Str,), Int)
    }]

    final_type, _ = infer(term, init_env, {})
    return print_type(final_type)

class Type:
    pass

class TVar(Type):
    def __init__(self, id):
        self.id = id
    def __eq__(self, other):
        return isinstance(other, TVar) and self.id == other.id
    def __hash__(self):
        return hash(self.id)
    def __repr__(self):
        return f"TVar({self.id})"

class Int(Type): pass
class Bool(Type): pass
class Str(Type): pass
class Unit(Type): pass

class List(Type):
    def __init__(self, elem): self.elem = elem
class Ref(Type):
    def __init__(self, content): self.content = content

class Func(Type):
    def __init__(self, params, ret):
        self.params = params
        self.ret = ret

def apply_sub(sub, t):
    if isinstance(t, TVar):
        return sub.get(t.id, t)
    if isinstance(t, List):
        return List(apply_sub(sub, t.elem))
    if isinstance(t, Ref):
        return Ref(apply_sub(sub, t.content))
    if isinstance(t, Func):
        return Func(tuple(apply_sub(sub, p) for p in t.params), apply_sub(sub, t.ret))
    return t

def occurs(var_id, t):
    if isinstance(t, TVar): return t.id == var_id
    if isinstance(t, List): return occurs(var_id, t.elem)
    if isinstance(t, Ref): return occurs(var_id, t.content)
    if isinstance(t, Func):
        return any(occurs(var_id, p) for p in t.params) or occurs(var_id, t.ret)
    return False

def unify(t1, t2, subst):
    t1 = apply_sub(subst, t1)
    t2 = apply_sub(subst, t2)
    if isinstance(t1, TVar) and isinstance(t2, TVar) and t1.id == t2.id:
        return subst
    if isinstance(t1, TVar):
        if occurs(t1.id, t2): raise ValueError("Infinite type")
        return {**subst, t1.id: t2}
    if isinstance(t2, TVar):
        if occurs(t2.id, t1): raise ValueError("Infinite type")
        return {**subst, t2.id: t1}
    if type(t1) != type(t2):
        raise ValueError("Type mismatch")
    if isinstance(t1, List):
        return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, Ref):
        return unify(t1.content, t2.content, subst)
    if isinstance(t1, Func):
        if len(t1.params) != len(t2.params):
            raise ValueError("Arity mismatch")
        for p1, p2 in zip(t1.params, t2.params):
            subst = unify(p1, p2, subst)
        return unify(t1.ret, t2.ret, subst)
    return subst

def check_malformed(t):
    if not isinstance(t, tuple) or len(t) == 0:
        raise ValueError("Malformed")
    tag = t[0]
    if not isinstance(tag, str):
        raise ValueError("Tag not str")
    if tag == "int":
        if len(t) != 2 or not isinstance(t[1], int) or isinstance(t[1], bool): raise ValueError("Malformed")
    elif tag == "bool":
        if len(t) != 2 or not isinstance(t[1], bool): raise ValueError("Malformed")
    elif tag == "str":
        if len(t) != 2 or not isinstance(t[1], str): raise ValueError("Malformed")
    elif tag == "unit":
        if len(t) != 1: raise ValueError("Malformed")
    elif tag == "var":
        if len(t) != 2 or not isinstance(t[1], str) or not t[1]: raise ValueError("Malformed")
    elif tag == "fn":
        if len(t) != 3: raise ValueError("Malformed")
        params, body = t[1], t[2]
        if not isinstance(params, tuple) or len(params) == 0: raise ValueError("Malformed")
        if len(set(params)) != len(params): raise ValueError("Malformed")
        for p in params:
            if not isinstance(p, str) or not p: raise ValueError("Malformed")
        check_malformed(body)
    elif tag == "call":
        if len(t) != 3: raise ValueError("Malformed")
        f, args = t[1], t[2]
        if not isinstance(args, tuple) or len(args) == 0: raise ValueError("Malformed")
        check_malformed(f)
        for a in args: check_malformed(a)
    elif tag == "let":
        if len(t) != 4: raise ValueError("Malformed")
        name, e1, e2 = t[1], t[2], t[3]
        if not isinstance(name, str) or not name: raise ValueError("Malformed")
        check_malformed(e1); check_malformed(e2)
    elif tag == "letrec":
        if len(t) != 4: raise ValueError("Malformed")
        name, e1, e2 = t[1], t[2], t[3]
        if not isinstance(name, str) or not name: raise ValueError("Malformed")
        if t[2][0] != "fn": raise ValueError("Malformed")
        check_malformed(e1); check_malformed(e2)
    elif tag == "nil":
        if len(t) != 1: raise ValueError("Malformed")
    elif tag == "cons":
        if len(t) != 3: raise ValueError("Malformed")
        check_malformed(t[1]); check_malformed(t[2])
    elif tag == "match":
        if len(t) != 6: raise ValueError("Malformed")
        s, e_nil, hn, tn, e_cons = t[1], t[2], t[3], t[4], t[5]
        check_malformed(s); check_malformed(e_nil); check_malformed(e_cons)
        if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn: raise ValueError("Malformed")
        if hn == tn: raise ValueError("Malformed")
    elif tag == "ref":
        if len(t) != 2: raise ValueError("Malformed")
        check_malformed(t[1])
    elif tag == "get":
        if len(t) != 2: raise ValueError("Malformed")
        check_malformed(t[1])
    elif tag == "set":
        if len(t) != 3: raise ValueError("Malformed")
        check_malformed(t[1]); check_malformed(t[2])
    else:
        raise ValueError("Unknown tag")

def weak_infer(term):
    check_malformed(term)
    fresh_counter = [0]
    def fresh():
        fresh_counter[0] += 1
        return TVar(fresh_counter[0])

    env = []

    def lookup(name):
        for scope in env:
            if name in scope:
                return scope[name]
        raise ValueError(f"Unbound variable: {name}")

    def is_value(t):
        tag = t[0]
        if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"):
            return True
        if tag == "cons":
            return is_value(t[1]) and is_value(t[2])
        return False

    def free_vars(t, acc):
        if isinstance(t, TVar): acc.add(t.id)
        elif isinstance(t, List): free_vars(t.elem, acc)
        elif isinstance(t, Ref): free_vars(t.content, acc)
        elif isinstance(t, Func):
            for p in t.params: free_vars(p, acc)
            free_vars(t.ret, acc)

    def generalize(t, env, fresh):
        tvs = set()
        free_vars(t, tvs)
        env_tvs = set()
        for scope in env:
            for typ in scope.values():
                free_vars(typ, env_tvs)
        to_quantify = tvs - env_tvs
        if to_quantify:
            sub = {vid: fresh() for vid in to_quantify}
            t = apply_sub(sub, t)
        return t

    def infer(t, env):
        tag = t[0]
        if tag == "int": return Int()
        if tag == "bool": return Bool()
        if tag == "str": return Str()
        if tag == "unit": return Unit()
        if tag == "var": return lookup(t[1])
        if tag == "fn":
            params, body = t[1], t[2]
            param_types = tuple(fresh() for _ in params)
            new_env = [{p: pt for p, pt in zip(params, param_types)}] + env
            body_type = infer(body, new_env)
            return Func(param_types, body_type)
        if tag == "call":
            f, args = t[1], t[2]
            f_type = infer(f, env)
            if not isinstance(f_type, Func):
                raise ValueError("Call on non-function")
            if len(f_type.params) != len(args):
                raise ValueError("Arity mismatch")
            arg_types = [infer(a, env) for a in args]
            subst = {}
            for p, a in zip(f_type.params, arg_types):
                subst = unify(p, a, subst)
            return apply_sub(subst, f_type.ret)
        if tag == "let":
            name, e1, e2 = t[1], t[2], t[3]
            e1_type = infer(e1, env)
            if is_value(e1):
                e1_type = generalize(e1_type, env, fresh)
            new_env = [{name: e1_type}] + env
            return infer(e2, new_env)
        if tag == "letrec":
            name, e1, e2 = t[1], t[2], t[3]
            t_name = fresh()
            new_env = [{name: t_name}] + env
            e1_type = infer(e1, new_env)
            e1_type = generalize(e1_type, env, fresh)
            new_env2 = [{name: e1_type}] + env
            return infer(e2, new_env2)
        if tag == "nil":
            return List(fresh())
        if tag == "cons":
            h, t_term = t[1], t[2]
            h_type = infer(h, env)
            t_type = infer(t_term, env)
            if not isinstance(t_type, List):
                raise ValueError("Cons tail must be list")
            subst = unify(h_type, t_type.elem, {})
            return apply_sub(subst, t_type)
        if tag == "match":
            s, e_nil, hn, tn, e_cons = t[1], t[2], t[3], t[4], t[5]
            s_type = infer(s, env)
            if not isinstance(s_type, List):
                raise ValueError("Match scrutinee must be list")
            A = s_type.elem
            new_env = [{hn: A, tn: List(A)}] + env
            t_nil = infer(e_nil, new_env)
            t_cons = infer(e_cons, new_env)
            subst = unify(t_nil, t_cons, {})
            return apply_sub(subst, t_nil)
        if tag == "ref":
            e = t[1]
            e_type = infer(e, env)
            return Ref(e_type)
        if tag == "get":
            r = t[1]
            r_type = infer(r, env)
            if not isinstance(r_type, Ref):
                raise ValueError("Get on non-ref")
            return r_type.content
        if tag == "set":
            r, e = t[1], t[2]
            r_type = infer(r, env)
            if not isinstance(r_type, Ref):
                raise ValueError("Set on non-ref")
            e_type = infer(e, env)
            unify(r_type.content, e_type, {})
            return Unit()
        raise ValueError("Unknown tag")

    final_type = infer(term, env)

    ids = []
    def collect(t):
        if isinstance(t, TVar):
            if t.id not in ids: ids.append(t.id)
        elif isinstance(t, List): collect(t.elem)
        elif isinstance(t, Ref): collect(t.content)
        elif isinstance(t, Func):
            for p in t.params: collect(p)
            collect(t.ret)
    collect(final_type)
    mapping = {vid: f"t{i+1}" for i, vid in enumerate(ids)}

    def fmt(t):
        if isinstance(t, TVar): return mapping[t.id]
        if isinstance(t, Int): return "Int"
        if isinstance(t, Bool): return "Bool"
        if isinstance(t, Str): return "Str"
        if isinstance(t, Unit): return "Unit"
        if isinstance(t, List): return f"List<{fmt(t.elem)}>"
        if isinstance(t, Ref): return f"Ref<{fmt(t.content)}>"
        if isinstance(t, Func):
            params_str = ", ".join(fmt(p) for p in t.params)
            ret_str = fmt(t.ret)
            if len(t.params) == 1:
                p_str = fmt(t.params[0])
                if isinstance(t.params[0], Func):
                    return f"({p_str}) -> {ret_str}"
                return f"{p_str} -> {ret_str}"
            return f"({params_str}) -> {ret_str}"
        return str(t)

    return fmt(final_type)

