    _fresh_counter[0] += 1
    return TVar(_fresh_counter[0])

def apply(sub, t):
    if isinstance(t, TVar):
        res = sub.get(t.id, t)
        if isinstance(res, TVar):
            return apply(sub, res)
        return res
    elif isinstance(t, List):
        return List(apply(sub, t.content))
    elif isinstance(t, Ref):
        return Ref(apply(sub, t.content))
    elif isinstance(t, Func):
        return Func(tuple(apply(sub, p) for p in t.params), apply(sub, t.ret))
    return t

def occurs_in(tvar, t):
    if isinstance(t, TVar):
        return t.id == tvar.id
    elif isinstance(t, List):
        return occurs_in(tvar, t.content)
    elif isinstance(t, Ref):
        return occurs_in(tvar, t.content)
    elif isinstance(t, Func):
        return any(occurs_in(tvar, p) for p in t.params) or occurs_in(tvar, t.ret)
    return False

def unify(t1, t2, sub):
    t1 = apply(sub, t1)
    t2 = apply(sub, t2)
    if t1 == t2:
        return sub
    if isinstance(t1, TVar):
        if occurs_in(t1, t2):
            raise ValueError("Infinite type")
        return {**sub, t1.id: t2}
    if isinstance(t2, TVar):
        if occurs_in(t2, t1):
            raise ValueError("Infinite type")
        return {**sub, t2.id: t1}
    if type(t1) != type(t2):
        raise ValueError("Type mismatch")
    if isinstance(t1, List):
        return unify(t1.content, t2.content, sub)
    if isinstance(t1, Ref):
        return unify(t1.content, t2.content, sub)
    if isinstance(t1, Func):
        if len(t1.params) != len(t2.params):
            raise ValueError("Arity mismatch")
        s = sub
        for p1, p2 in zip(t1.params, t2.params):
            s = unify(p1, p2, s)
        return unify(t1.ret, t2.ret, s)
    raise ValueError("Type mismatch")

