            "plus": Func((Int, Int), Int),
            "eq": Func((eq_var, eq_var), Bool),
            "size": Func((Str,), Int)
        }
    ]
    res_type = infer(term, init_env)

    var_map = {}
    var_counter = [0]
    def collect_vars(t):
        if isinstance(t, TVar):
            if t.id not in var_map:
                var_counter[0] += 1
                var_map[t.id] = f"t{var_counter[0]}"
        elif isinstance(t, List):
            collect_vars(t.content)
        elif isinstance(t, Ref):
            collect_vars(t.content)
        elif isinstance(t, Func):
            for p in t.params:
                collect_vars(p)
            collect_vars(t.ret)
    collect_vars(res_type)

    def fmt(t, force_parens=False):
        if isinstance(t, TVar):
            return var_map[t.id]
        if isinstance(t, Int): return "Int"
        if isinstance(t, Bool): return "Bool"
        if isinstance(t, Str): return "Str"
        if isinstance(t, Unit): return "Unit"
        if isinstance(t, List):
            return f"List<{fmt(t.content)}>"
        if isinstance(t, Ref):
            return f"Ref<{fmt(t.content)}>"
        if isinstance(t, Func):
            p_strs = [fmt(p) for p in t.params]
            r_str = fmt(t.ret)
            if len(t.params) == 1:
                if isinstance(t.params[0], Func):
                    return f"({p_strs[0]}) -> {r_str}"
                return f"{p_strs[0]} -> {r_str}"
            return f"({', '.join(p_strs)}) -> {r_str}"
        return "?"
    return fmt(res_type)

def weak_infer(term):
    # --- Type Definitions ---
    class TVar:
        __slots__ = ('id',)
        def __init__(self, i): self.id = i
        def __eq__(self, o): return isinstance(o, TVar) and self.id == o.id
        def __hash__(self): return self.id

    class Int: pass
    class Bool: pass
    class Str: pass
    class Unit: pass

    class List:
        __slots__ = ('elem',)
        def __init__(self, e): self.elem = e
        def __eq__(self, o): return isinstance(o, List) and self.elem == o.elem
        def __hash__(self): return hash(('L', self.elem))

    class Ref:
        __slots__ = ('content',)
        def __init__(self, c): self.content = c
        def __eq__(self, o): return isinstance(o, Ref) and self.content == o.content
        def __hash__(self): return hash(('R', self.content))

    class Func:
        __slots__ = ('params', 'ret')
        def __init__(self, p, r): self.params = tuple(p); self.ret = r
        def __eq__(self, o): return isinstance(o, Func) and self.params == o.params and self.ret == o.ret
        def __hash__(self): return hash(('F', self.params, self.ret))

    # --- Substitution & Unification ---
    def apply(sub, t):
        if isinstance(t, TVar):
            return sub.get(t.id, t)
        elif isinstance(t, List):
            return List(apply(sub, t.elem))
        elif isinstance(t, Ref):
            return Ref(apply(sub, t.content))
        elif isinstance(t, Func):
            return Func([apply(sub, p) for p in t.params], apply(sub, t.ret))
        return t

    def compose(sub1, sub2):
        res = dict(sub1)
        for k, v in sub2.items():
            res[k] = apply(sub1, v)
        return res

    def occurs_in(var_id, t):
        if isinstance(t, TVar):
            return t.id == var_id
        elif isinstance(t, List):
            return occurs_in(var_id, t.elem)
        elif isinstance(t, Ref):
            return occurs_in(var_id, t.content)
        elif isinstance(t, Func):
            return any(occurs_in(var_id, p) for p in t.params) or occurs_in(var_id, t.ret)
        return False

    def unify(t1, t2, sub):
        t1 = apply(sub, t1)
        t2 = apply(sub, t2)
        if isinstance(t1, TVar) and isinstance(t2, TVar) and t1.id == t2.id:
            return sub
        if isinstance(t1, TVar):
            if occurs_in(t1.id, t2):
                raise ValueError("Infinite type")
            new_sub = dict(sub)
            new_sub[t1.id] = t2
            return new_sub
        if isinstance(t2, TVar):
            if occurs_in(t2.id, t1):
                raise ValueError("Infinite type")
            new_sub = dict(sub)
            new_sub[t2.id] = t1
            return new_sub
        if isinstance(t1, Int) != isinstance(t2, Int) or \
           isinstance(t1, Bool) != isinstance(t2, Bool) or \
           isinstance(t1, Str) != isinstance(t2, Str) or \
           isinstance(t1, Unit) != isinstance(t2, Unit):
            raise ValueError("Type mismatch")
        if isinstance(t1, List) and isinstance(t2, List):
            return unify(t1.elem, t2.elem, sub)
        if isinstance(t1, Ref) and isinstance(t2, Ref):
            return unify(t1.content, t2.content, sub)
        if isinstance(t1, Func) and isinstance(t2, Func):
            if len(t1.params) != len(t2.params):
                raise ValueError("Arity mismatch")
            for p1, p2 in zip(t1.params, t2.params):
                sub = unify(p1, p2, sub)
            return unify(t1.ret, t2.ret, sub)
        raise ValueError("Type mismatch")

    def free_vars(t):
        if isinstance(t, TVar):
            return {t.id}
        elif isinstance(t, List):
            return free_vars(t.elem)
        elif isinstance(t, Ref):
            return free_vars(t.content)
        elif isinstance(t, Func):
            res = set()
            for p in t.params:
                res |= free_vars(p)
            res |= free_vars(t.ret)
            return res
        return set()

    def get_env_free_vars(env):
        res = set()
        for d in env:
            for t in d.values():
                res |= free_vars(t)
        return res

    # --- Malformed Check ---
    def check_malformed(term):
        if not isinstance(term, tuple) or not term:
            raise ValueError("Malformed")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Malformed")
        if tag == 'int':
            if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
                raise ValueError("Malformed")
        elif tag == 'bool':
            if len(term) != 2 or not isinstance(term[1], bool):
                raise ValueError("Malformed")
        elif tag == 'str':
            if len(term) != 2 or not isinstance(term[1], str):
                raise ValueError("Malformed")
        elif tag == 'unit':
            if len(term) != 1:
                raise ValueError("Malformed")
        elif tag == 'var':
            if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
                raise ValueError("Malformed")
        elif tag == 'fn':
            if len(term) != 3:
                raise ValueError("Malformed")
            params, body = term[1], term[2]
            if not isinstance(params, tuple) or not params or len(set(params)) != len(params):
                raise ValueError("Malformed")
            if not all(isinstance(p, str) and p for p in params):
                raise ValueError("Malformed")
            check_malformed(body)
        elif tag == 'call':
            if len(term) != 3:
                raise ValueError("Malformed")
            check_malformed(term[1])
            args = term[2]
            if not isinstance(args, tuple) or not args:
                raise ValueError("Malformed")
            for a in args:
                check_malformed(a)
        elif tag == 'let':
            if len(term) != 4:
                raise ValueError("Malformed")
            name, e1, e2 = term[1], term[2], term[3]
            if not isinstance(name, str) or not name:
                raise ValueError("Malformed")
            check_malformed(e1)
            check_malformed(e2)
        elif tag == 'letrec':
            if len(term) != 4:
                raise ValueError("Malformed")
            name, e1, e2 = term[1], term[2], term[3]
            if not isinstance(name, str) or not name:
                raise ValueError("Malformed")
            if e1[0] != 'fn':
                raise ValueError("Malformed")
            check_malformed(e1)
            check_malformed(e2)
        elif tag == 'nil':
            if len(term) != 1:
                raise ValueError("Malformed")
        elif tag == 'cons':
            if len(term) != 3:
                raise ValueError("Malformed")
            check_malformed(term[1])
            check_malformed(term[2])
        elif tag == 'match':
            if len(term) != 6:
                raise ValueError("Malformed")
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            if not isinstance(hn, str) or not hn or not isinstance(tn, str) or not tn:
                raise ValueError("Malformed")
            if hn == tn:
                raise ValueError("Malformed")
            check_malformed(s)
            check_malformed(e_nil)
            check_malformed(e_cons)
        elif tag == 'ref':
            if len(term) != 2:
                raise ValueError("Malformed")
            check_malformed(term[1])
        elif tag == 'get':
            if len(term) != 2:
                raise ValueError("Malformed")
            check_malformed(term[1])
        elif tag == 'set':
            if len(term) != 3:
                raise ValueError("Malformed")
            check_malformed(term[1])
            check_malformed(term[2])
        else:
            raise ValueError("Malformed")

    # --- Value Check ---
    def is_value(term):
        if term[0] in ('int', 'bool', 'str', 'unit', 'var'):
            return True
        if term[0] == 'fn':
            return True
        if term[0] == 'nil':
            return True
        if term[0] == 'cons':
            return is_value(term[1]) and is_value(term[2])
        return False

    # --- Fresh Counter ---
    fc = 0
    def fresh():
        nonlocal fc
        v = TVar(fc); fc += 1; return v

    # --- Initial Environment ---
    env = [
        {
            "plus": Func([Int, Int], Int),
            "eq": Func([fresh(), fresh()], Bool),
            "size": Func([Str], Int)
        }
    ]

    # --- Inference ---
    def infer(t, env):
        tag = t[0]
        if tag == 'int':
            return Int, {}
        elif tag == 'bool':
            return Bool, {}
        elif tag == 'str':
            return Str, {}
        elif tag == 'unit':
            return Unit, {}
        elif tag == 'var':
            name = t[1]
            for d in env:
                if name in d:
                    return d[name], {}
            raise ValueError("Unbound variable")
        elif tag == 'fn':
            params, body = t[1], t[2]
            p_types = [fresh() for _ in params]
            env2 = [{p: pt for p, pt in zip(params, p_types)}] + env
            body_t, sub1 = infer(body, env2)
            return Func(p_types, body_t), sub1
        elif tag == 'call':
            f_t, sub1 = infer(t[1], env)
            env1 = [{name: apply(sub1, t) for name, t in d.items()} for d in env]
            args = t[2]
            arg_types = []
            sub = sub1
            for a in args:
                at, s = infer(a, env1)
                arg_types.append(at)
                sub = compose(sub, s)
                env1 = [{name: apply(sub, t) for name, t in d.items()} for d in env1]
            if not isinstance(f_t, Func):
                raise ValueError("Call on non-function")
            if len(f_t.params) != len(arg_types):
                raise ValueError("Arity mismatch")
            for fp, at in zip(f_t.params, arg_types):
                sub = unify(fp, at, sub)
            return apply(sub, f_t.ret), sub
        elif tag == 'let':
            name, e1, e2 = t[1], t[2], t[3]
            e1_t, sub1 = infer(e1, env)
            env1 = [{name: apply(sub1, e1_t)}] + env
            return infer(e2, env1)
        elif tag == 'letrec':
            name, e1, e2 = t[1], t[2], t[3]
            T_f = fresh()
            env1 = [{name: T_f}] + env
            e1_t, sub1 = infer(e1, env1)
            sub1 = unify(T_f, e1_t, sub1)
            env2 = [{name: apply(sub1, e1_t)}] + env
            return infer(e2, env2)
        elif tag == 'nil':
            return List(fresh()), {}
        elif tag == 'cons':
            h_t, sub1 = infer(t[1], env)
            t_t, sub2 = infer(t[2], env)
            if not isinstance(t_t, List):
                raise ValueError("Cons tail not a list")
            sub2 = unify(h_t, t_t.elem, sub2)
            return List(t_t.elem), compose(sub1, sub2)
        elif tag == 'match':
            s, e_nil, hn, tn, e_cons = t[1], t[2], t[3], t[4], t[5]
            s_t, sub1 = infer(s, env)
            if not isinstance(s_t, List):
                raise ValueError("Match on non-list")
            A = s_t.elem
            env1 = [{hn: A, tn: List(A)}] + env
            e_nil_t, sub2 = infer(e_nil, env1)
            e_cons_t, sub3 = infer(e_cons, env1)
            sub3 = unify(e_nil_t, e_cons_t, sub3)
            return apply(sub3, e_cons_t), compose(sub1, compose(sub2, sub3))
        elif tag == 'ref':
            e_t, sub = infer(t[1], env)
            return Ref(e_t), sub
        elif tag == 'get':
            r_t, sub = infer(t[1], env)
            if not isinstance(r_t, Ref):
                raise ValueError("Get on non-ref")
            return r_t.content, sub
        elif tag == 'set':
            r_t, sub1 = infer(t[1], env)
            e_t, sub2 = infer(t[2], env)
            if not isinstance(r_t, Ref):
                raise ValueError("Set on non-ref")
            sub2 = unify(r_t.content, e_t, sub2)
            return Unit, compose(sub1, sub2)
        else:
            raise ValueError("Unknown tag")

    check_malformed(term)
    final_type, _ = infer(term, env)

    # --- Printing ---
    var_ids = []
    var_map = {}
    def collect_vars(t):
        if isinstance(t, TVar):
            if t.id not in var_map:
                var_map[t.id] = len(var_ids)
                var_ids.append(t.id)
        elif isinstance(t, List):
            collect_vars(t.elem)
        elif isinstance(t, Ref):
            collect_vars(t.content)
        elif isinstance(t, Func):
            for p in t.params:
                collect_vars(p)
            collect_vars(t.ret)

    collect_vars(final_type)
    def fmt(t):
        if isinstance(t, TVar):
            return f"t{var_map[t.id] + 1}"
        elif isinstance(t, Int):
            return "Int"
        elif isinstance(t, Bool):
            return "Bool"
        elif isinstance(t, Str):
            return "Str"
        elif isinstance(t, Unit):
            return "Unit"
        elif isinstance(t, List):
            return f"List<{fmt(t.elem)}>"
        elif isinstance(t, Ref):
            return f"Ref<{fmt(t.content)}>"
        elif isinstance(t, Func):
            if len(t.params) == 1:
                p = fmt(t.params[0])
                if isinstance(t.params[0], Func):
                    p = f"({p})"
                return f"{p} -> {fmt(t.ret)}"
            else:
                ps = ", ".join(fmt(p) for p in t.params)
                return f"({ps}) -> {fmt(t.ret)}"
        return ""

    return fmt(final_type)

import sys

# --- Type Representation ---
class TVar:
    def __init__(self, id): self.id = id
    def __eq__(self, other): return isinstance(other, TVar) and self.id == other.id
    def __hash__(self): return self.id

class Int: pass
class Bool: pass
class Str: pass
class Unit: pass

class ListT:
    def __init__(self, inner): self.inner = inner
class RefT:
    def __init__(self, inner): self.inner = inner
class Func:
    def __init__(self, params, ret): self.params = params; self.ret = ret

# --- Substitution & Unification ---
def apply_sub(sub, t):
    if isinstance(t, TVar):
        return sub.get(t.id, t)
    if isinstance(t, ListT): return ListT(apply_sub(sub, t.inner))
    if isinstance(t, RefT): return RefT(apply_sub(sub, t.inner))
    if isinstance(t, Func):
        return Func(tuple(apply_sub(sub, p) for p in t.params), apply_sub(sub, t.ret))
    return t

def free_vars(t):
    if isinstance(t, TVar): return {t.id}
    if isinstance(t, (Int, Bool, Str, Unit)): return set()
    if isinstance(t, ListT): return free_vars(t.inner)
    if isinstance(t, RefT): return free_vars(t.inner)
    if isinstance(t, Func):
        res = set()
        for p in t.params: res |= free_vars(p)
        return res | free_vars(t.ret)
    return set()

def occurs(tid, t):
    return tid in free_vars(t)

def unify(t1, t2, sub=None):
    if sub is None: sub = {}
    t1 = apply_sub(sub, t1)
    t2 = apply_sub(sub, t2)

    if isinstance(t1, TVar):
        if isinstance(t2, TVar):
            if t1.id == t2.id: return sub
            if occurs(t1.id, t2): raise ValueError("Infinite type")
            new_sub = {t1.id: t2}
            return {k: apply_sub(new_sub, v) for k, v in sub.items()} | new_sub
        if occurs(t1.id, t2): raise ValueError("Infinite type")
        new_sub = {t1.id: t2}
        return {k: apply_sub(new_sub, v) for k, v in sub.items()} | new_sub

    if isinstance(t2, TVar):
        return unify(t2, t1, sub)

    if isinstance(t1, Func) and isinstance(t2, Func):
        if len(t1.params) != len(t2.params): raise ValueError("Arity mismatch")
        s = sub
        for p1, p2 in zip(t1.params, t2.params):
            s = unify(p1, p2, s)
        return unify(t1.ret, t2.ret, s)

    if isinstance(t1, ListT) and isinstance(t2, ListT):
        return unify(t1.inner, t2.inner, sub)
    if isinstance(t1, RefT) and isinstance(t2, RefT):
        return unify(t1.inner, t2.inner, sub)

    raise ValueError("Type mismatch")

def unify_tuple(t1s, t2s, sub=None):
    if sub is None: sub = {}
    for t1, t2 in zip(t1s, t2s):
        sub = unify(t1, t2, sub)
    return sub

# --- Generalization ---
def free_vars_env(env):
    res = set()
    for frame in env:
        for t in frame.values():
            res |= free_vars(t)
    return res

def generalize(env, t):
    fv_t = free_vars(t)
    fv_env = free_vars_env(env)
    to_replace = fv_t & fv_env
    if not to_replace:
        return t
    fresh_map = {tid: TVar(fresh()) for tid in to_replace}
    def replace(t):
        if isinstance(t, TVar):
            return fresh_map.get(t.id, t)
        if isinstance(t, ListT): return ListT(replace(t.inner))
        if isinstance(t, RefT): return RefT(replace(t.inner))
        if isinstance(t, Func):
            return Func(tuple(replace(p) for p in t.params), replace(t.ret))
        return t
    return replace(t)

# --- Value Check ---
def is_value(term):
    if not isinstance(term, tuple) or len(term) == 0: return False
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var"): return True
    if tag == "fn": return True
    if tag == "nil": return True
    if tag == "cons":
        return is_value(term[1]) and is_value(term[2])
    return False

# --- Malformed Check ---
VALID_TAGS = {"int", "bool", "str", "unit", "var", "fn", "call", "let", "letrec", "nil", "cons", "match", "ref", "get", "set"}

def check_malformed(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed term")
    tag = term[0]
    if not isinstance(tag, str) or tag not in VALID_TAGS:
        raise ValueError("Unknown or invalid tag")

    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool):
            raise ValueError("Malformed int")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool):
            raise ValueError("Malformed bool")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str):
            raise ValueError("Malformed str")
    elif tag == "unit":
        if len(term) != 1:
            raise ValueError("Malformed unit")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or not term[1]:
            raise ValueError("Malformed var")
    elif tag == "fn":
        if len(term) != 3: raise ValueError("Malformed fn")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0:
            raise ValueError("fn params must be non-empty tuple")
        for p in params:
            if not isinstance(p, str) or not p:
                raise ValueError("fn param must be non-empty str")
        if len(params) != len(set(params)):
            raise ValueError("fn params must be distinct")
        check_malformed(body)
    elif tag == "call":
        if len(term) != 3: raise ValueError("Malformed call")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or len(args) == 0:
            raise ValueError("call args must be non-empty tuple")
        check_malformed(f)
        for a in args: check_malformed(a)
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed let")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("let name must be non-empty str")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "letrec":
        if len(term) != 4: raise ValueError("Malformed letrec")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or not name:
            raise ValueError("letrec name must be non-empty str")
        if not isinstance(e1, tuple) or len(e1) == 0 or e1[0] != "fn":
            raise ValueError("letrec e1 must be fn")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "nil":
        if len(term) != 1: raise ValueError("Malformed nil")
    elif tag == "cons":
        if len(term) != 3: raise ValueError("Malformed cons")
        check_malformed(term[1])
        check_malformed(term[2])
    elif tag == "match":
        if len(term) != 5: raise ValueError("Malformed match")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(e_cons)
        if not isinstance(hn, str) or not hn: raise ValueError("match hn")
        if not isinstance(tn, str) or not tn: raise ValueError("match tn")
        if hn == tn: raise ValueError("match hn and tn must differ")
    elif tag == "ref":
        if len(term) != 2: raise ValueError("Malformed ref")
        check_malformed(term[1])
    elif tag == "get":
        if len(term) != 2: raise ValueError("Malformed get")
        check_malformed(term[1])
    elif tag == "set":
        if len(term) != 3: raise ValueError("Malformed set")
        check_malformed(term[1])
        check_malformed(term[2])

# --- Inference Engine ---
class HMInfer:
    def __init__(self):
        self.fresh_id = 0
        v1 = self.fresh()
        self.env = [{"plus": Func((Int, Int), Int),
                     "eq": Func((TVar(v1), TVar(v1)), Bool),
                     "size": Func((Str,), Int)}]

    def fresh(self):
        self.fresh_id += 1
        return self.fresh_id

    def lookup(self, name):
        for frame in reversed(self.env):
            if name in frame:
                return frame[name]
        raise ValueError(f"Unbound variable: {name}")

    def extend_env(self, name, type_):
        self.env.append({name: type_})

    def infer(self, term):
        tag = term[0]
        if tag == "int": return Int
        if tag == "bool": return Bool
        if tag == "str": return Str
        if tag == "unit": return Unit
        if tag == "var": return self.lookup(term[1])
        if tag == "fn":
            params, body = term[1], term[2]
            param_types = tuple(TVar(self.fresh()) for _ in params)
            for p, pt in zip(params, param_types):
                self.extend_env(p, pt)
            body_type = self.infer(body)
            return Func(param_types, body_type)
        if tag == "call":
            f, args = term[1], term[2]
            f_type = self.infer(f)
            if not isinstance(f_type, Func): raise ValueError("Call on non-function")
            if len(f_type.params) != len(args): raise ValueError("Arity mismatch")
            arg_types = tuple(self.infer(a) for a in args)
            unify_tuple(f_type.params, arg_types)
            return f_type.ret
        if tag == "let":
            name, e1, e2 = term[1], term[2], term[3]
            t1 = self.infer(e1)
            if is_value(e1):
                t1 = self.generalize(t1)
            self.extend_env(name, t1)
            return self.infer(e2)
        if tag == "letrec":
            name, e1, e2 = term[1], term[2], term[3]
            t_fresh = TVar(self.fresh())
            self.extend_env(name, t_fresh)
            t1 = self.infer(e1)
            # Ensure recursive definition matches assigned type
            unify(t_fresh, t1)
            t1_gen = self.generalize(t1)
            # Update env with generalized type for subsequent uses
            self.env[-1][name] = t1_gen
            return self.infer(e2)
        if tag == "nil":
            return ListT(TVar(self.fresh()))
        if tag == "cons":
            h, t = term[1], term[2]
            th = self.infer(h)
            tt = self.infer(t)
            elem = TVar(self.fresh())
            unify(tt, ListT(elem))
            unify(th, elem)
            return ListT(elem)
        if tag == "match":
            s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
            ts = self.infer(s)
            A = TVar(self.fresh())
            unify(ts, ListT(A))
            self.extend_env(hn, A)
            self.extend_env(tn, ListT(A))
            t_nil = self.infer(e_nil)
            t_cons = self.infer(e_cons)
            unify(t_nil, t_cons)
            return t_nil
        if tag == "ref":
            e = term[1]
            te = self.infer(e)
            return RefT(te)
        if tag == "get":
            r = term[1]
            tr = self.infer(r)
            t = TVar(self.fresh())
            unify(tr, RefT(t))
            return t
        if tag == "set":
            r, e = term[1], term[2]
            tr = self.infer(r)
            te = self.infer(e)
            unify(tr, RefT(te))
            return Unit
        raise ValueError("Unknown tag")

    def generalize(self, t):
        return generalize(self.env, t)

# --- Printing ---
def print_type(t):
    # Collect TVar IDs in order of first appearance (pre-order)
    seen = set()
    order = []
    def collect(t):
        if isinstance(t, TVar):
            if t.id not in seen:
                seen.add(t.id)
                order.append(t.id)
        elif isinstance(t, ListT):
            collect(t.inner)
        elif isinstance(t, RefT):
            collect(t.inner)
        elif isinstance(t, Func):
            for p in t.params: collect(p)
            collect(t.ret)
    collect(t)
    var_map = {tid: f"t{i+1}" for i, tid in enumerate(order)}

    def fmt(t):
        if isinstance(t, TVar):
            return var_map[t.id]
        if isinstance(t, Int): return "Int"
        if isinstance(t, Bool): return "Bool"
        if isinstance(t, Str): return "Str"
        if isinstance(t, Unit): return "Unit"
        if isinstance(t, ListT):
            return f"List<{fmt(t.inner)}>"
        if isinstance(t, RefT):
            return f"Ref<{fmt(t.inner)}>"
        if isinstance(t, Func):
            ret_s = fmt(t.ret)
            if len(t.params) == 1:
                p_s = fmt(t.params[0])
                if isinstance(t.params[0], Func):
                    p_s = f"({p_s})"
                return f"{p_s} -> {ret_s}"
            else:
                ps_s = ", ".join(fmt(p) for p in t.params)
                return f"({ps_s}) -> {ret_s}"
        return "?"

    return fmt(t)

# --- Main Interface ---
def weak_infer(term):
    check_malformed(term)
    engine = HMInfer()
    res_type = engine.infer(term)
    return print_type(res_type)

import sys

# --- Type System ---

class TVar:
    __slots__ = ('id',)
    def __init__(self, id): self.id = id
    def __eq__(self, o): return isinstance(o, TVar) and self.id == o.id
    def __hash__(self): return self.id

class Int: pass
class Bool: pass
class Str: pass
class Unit: pass

class ListT:
    __slots__ = ('el',)
    def __init__(self, el): self.el = el
    def __eq__(self, o): return isinstance(o, ListT) and self.el == o.el
    def __hash__(self): return hash(self.el)

class RefT:
    __slots__ = ('el',)
    def __init__(self, el): self.el = el
    def __eq__(self, o): return isinstance(o, RefT) and self.el == o.el
    def __hash__(self): return hash(self.el)

class Func:
    __slots__ = ('params', 'ret')
    def __init__(self, params, ret):
        self.params = tuple(params)
        self.ret = ret
    def __eq__(self, o): return isinstance(o, Func) and self.params == o.params and self.ret == o.ret
    def __hash__(self): return hash((self.params, self.ret))

_fresh_counter = 0
def fresh():
    global _fresh_counter
    t = TVar(_fresh_counter)
    _fresh_counter += 1
    return t

def reset_fresh():
    global _fresh_counter
    _fresh_counter = 0

# --- Substitution & Free Vars ---

def apply_sub(sub, t):
    if isinstance(t, TVar):
        return sub.get(t.id, t)
    if isinstance(t, ListT): return ListT(apply_sub(sub, t.el))
    if isinstance(t, RefT): return RefT(apply_sub(sub, t.el))
    if isinstance(t, Func): return Func(tuple(apply_sub(sub, p) for p in t.params), apply_sub(sub, t.ret))
    return t

def free_vars(t):
    if isinstance(t, TVar): return {t.id}
    if isinstance(t, ListT): return free_vars(t.el)
    if isinstance(t, RefT): return free_vars(t.el)
    if isinstance(t, Func):
        fv = set()
        for p in t.params: fv |= free_vars(p)
        fv |= free_vars(t.ret)
        return fv
    return set()

# --- Unification ---

def unify(t1, t2, sub):
    t1 = apply_sub(sub, t1)
    t2 = apply_sub(sub, t2)
    if isinstance(t1, TVar):
        if t1.id in free_vars(t2): raise ValueError("Infinite type")
        return {**sub, t1.id: t2}
    if isinstance(t2, TVar):
        if t2.id in free_vars(t1): raise ValueError("Infinite type")
        return {**sub, t2.id: t1}
    if type(t1) != type(t2): raise ValueError("Type mismatch")
    if isinstance(t1, (Int, Bool, Str, Unit)): return sub
    if isinstance(t1, ListT): return unify(t1.el, t2.el, sub)
    if isinstance(t1, RefT): return unify(t1.el, t2.el, sub)
    if isinstance(t1, Func):
        if len(t1.params) != len(t2.params): raise ValueError("Arity mismatch")
        for p1, p2 in zip(t1.params, t2.params):
            sub = unify(p1, p2, sub)
        return unify(t1.ret, t2.ret, sub)
    return sub

# --- Malformed Check ---

def check_malformed(term):
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed")
    allowed = {"int", "bool", "str", "unit", "var", "fn", "call", "let", "letrec", "nil", "cons", "match", "ref", "get", "set"}
    if tag not in allowed:
        raise ValueError("Malformed")

    if tag == "int":
        if len(term) != 2 or not isinstance(term[1], int) or isinstance(term[1], bool): raise ValueError("Malformed")
    elif tag == "bool":
        if len(term) != 2 or not isinstance(term[1], bool): raise ValueError("Malformed")
    elif tag == "str":
        if len(term) != 2 or not isinstance(term[1], str): raise ValueError("Malformed")
    elif tag == "unit":
        if len(term) != 1: raise ValueError("Malformed")
    elif tag == "var":
        if len(term) != 2 or not isinstance(term[1], str) or len(term[1]) == 0: raise ValueError("Malformed")
    elif tag == "fn":
        if len(term) != 3: raise ValueError("Malformed")
        params, body = term[1], term[2]
        if not isinstance(params, tuple) or len(params) == 0: raise ValueError("Malformed")
        if len(set(params)) != len(params): raise ValueError("Malformed")
        if not all(isinstance(p, str) and len(p) > 0 for p in params): raise ValueError("Malformed")
        check_malformed(body)
    elif tag == "call":
        if len(term) != 3: raise ValueError("Malformed")
        f, args = term[1], term[2]
        if not isinstance(args, tuple) or len(args) == 0: raise ValueError("Malformed")
        check_malformed(f)
        for a in args: check_malformed(a)
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0: raise ValueError("Malformed")
        check_malformed(e1)
        check_malformed(e2)
    elif tag == "letrec":
        if len(term) != 4: raise ValueError("Malformed")
        name, e1, e2 = term[1], term[2], term[3]
        if not isinstance(name, str) or len(name) == 0: raise ValueError("Malformed")
        check_malformed(e1)
        if e1[0] != "fn": raise ValueError("Malformed")
        check_malformed(e2)
    elif tag == "nil":
        if len(term) != 1: raise ValueError("Malformed")
    elif tag == "cons":
        if len(term) != 3: raise ValueError("Malformed")
        check_malformed(term[1])
        check_malformed(term[2])
    elif tag == "match":
        if len(term) != 6: raise ValueError("Malformed")
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        if not isinstance(hn, str) or not isinstance(tn, str) or len(hn) == 0 or len(tn) == 0: raise ValueError("Malformed")
        if hn == tn: raise ValueError("Malformed")
        check_malformed(s)
        check_malformed(e_nil)
        check_malformed(e_cons)
    elif tag == "ref":
        if len(term) != 2: raise ValueError("Malformed")
        check_malformed(term[1])
    elif tag == "get":
        if len(term) != 2: raise ValueError("Malformed")
        check_malformed(term[1])
    elif tag == "set":
        if len(term) != 3: raise ValueError("Malformed")
        check_malformed(term[1])
        check_malformed(term[2])

# --- Value Restriction ---

def is_value(term):
    tag = term[0]
    if tag in ("int", "bool", "str", "unit", "var", "fn", "nil"):
        return True
    if tag == "cons":
        return is_value(term[1]) and is_value(term[2])
    return False

# --- Inference ---

def infer(term, env, sub):
    tag = term[0]
    if tag == "int": return Int
    if tag == "bool": return Bool
    if tag == "str": return Str
    if tag == "unit": return Unit
    if tag == "var":
        name = term[1]
        t = None
        for scope in env:
            if name in scope:
                t = scope[name]
                break
        if t is None: raise ValueError("Unbound variable")
        return apply_sub(sub, t)

    if tag == "fn":
        params = term[1]
        body = term[2]
        param_types = tuple(fresh() for _ in params)
        new_env = env + [dict(zip(params, param_types))]
        body_type = infer(body, new_env, sub)
        return Func(param_types, body_type)

    if tag == "call":
        f = term[1]
        args = term[2]
        f_type = apply_sub(sub, infer(f, env, sub))
        if not isinstance(f_type, Func): raise ValueError("Call on non-function")
        if len(f_type.params) != len(args): raise ValueError("Arity mismatch")
        arg_types = [infer(a, env, sub) for a in args]
        for p, at in zip(f_type.params, arg_types):
            sub = unify(p, at, sub)
        return apply_sub(sub, f_type.ret)

    if tag == "let":
        name, e1, e2 = term[1], term[2], term[3]
        e1_type = apply_sub(sub, infer(e1, env, sub))
        new_env = env + [{name: e1_type}]
        return infer(e2, new_env, sub)

    if tag == "letrec":
        name, e1, e2 = term[1], term[2], term[3]
        rec_type = fresh()
        new_env = env + [{name: rec_type}]
        e1_type = apply_sub(sub, infer(e1, new_env, sub))
        sub = unify(rec_type, e1_type, sub)
        new_env2 = env + [{name: e1_type}]
        return infer(e2, new_env2, sub)

    if tag == "nil":
        return ListT(fresh())

    if tag == "cons":
        h, t = term[1], term[2]
        h_type = infer(h, env, sub)
        t_type = infer(t, env, sub)
        elem_type = fresh()
        sub = unify(t_type, ListT(elem_type), sub)
        sub = unify(h_type, elem_type, sub)
        return ListT(elem_type)

    if tag == "match":
        s, e_nil, hn, tn, e_cons = term[1], term[2], term[3], term[4], term[5]
        s_type = apply_sub(sub, infer(s, env, sub))
        A = fresh()
        sub = unify(s_type, ListT(A), sub)
        new_env = env + [{hn: A, tn: ListT(A)}]
        t_nil = infer(e_nil, new_env, sub)
        t_cons = infer(e_cons, new_env, sub)
        sub = unify(t_nil, t_cons, sub)
        return apply_sub(sub, t_nil)

    if tag == "ref":
        e = term[1]
        e_type = infer(e, env, sub)
        return RefT(e_type)

    if tag == "get":
        r = term[1]
        r_type = apply_sub(sub, infer(r, env, sub))
        if not isinstance(r_type, RefT): raise ValueError("Get on non-ref")
        return r_type.el

    if tag == "set":
        r, e = term[1], term[2]
        r_type = apply_sub(sub, infer(r, env, sub))
        e_type = infer(e, env, sub)
        if not isinstance(r_type, RefT): raise ValueError("Set on non-ref")
        sub = unify(r_type.el, e_type, sub)
        return Unit

    raise ValueError("Unknown tag")

# --- Printing ---

def print_type(t):
    seen = {}
    order = []
    def collect(tv):
        if isinstance(tv, TVar):
            if tv.id not in seen:
                seen[tv.id] = len(order)
                order.append(tv.id)
        elif isinstance(tv, ListT): collect(tv.el)
        elif isinstance(tv, RefT): collect(tv.el)
        elif isinstance(tv, Func):
            for p in tv.params: collect(p)
            collect(tv.ret)
    collect(t)
    var_map = {tv_id: f"t{i+1}" for i, tv_id in enumerate(order)}

    def fmt(tv):
        if isinstance(tv, TVar): return var_map[tv.id]
        if isinstance(tv, Int): return "Int"
        if isinstance(tv, Bool): return "Bool"
        if isinstance(tv, Str): return "Str"
        if isinstance(tv, Unit): return "Unit"
        if isinstance(tv, ListT): return f"List<{fmt(tv.el)}>"
        if isinstance(tv, RefT): return f"Ref<{fmt(tv.el)}>"
        if isinstance(tv, Func):
            params_strs = [fmt(p) for p in tv.params]
            ret_str = fmt(tv.ret)
            if len(tv.params) == 1:
                p_str = params_strs[0]
                if isinstance(tv.params[0], Func):
                    return f"({p_str}) -> {ret_str}"
                return f"{p_str} -> {ret_str}"
            else:
                return f"({', '.join(params_strs)}) -> {ret_str}"
        return str(tv)
    return fmt(t)

# --- Main Interface ---

def weak_infer(term) -> str:
    check_malformed(term)
    reset_fresh()
    # Initial environment
    env = [{
        "plus": Func((Int, Int), Int),
        "eq": Func((fresh(), fresh()), Bool), # Will be unified to (a, a) -> Bool
        "size": Func((Str,), Int)
    }]
    # Actually, eq needs to be (a, a) -> Bool. We can represent it as fresh vars that get unified.
    # Better: create fresh vars for eq parameters and unify them.
    a1, a2 = fresh(), fresh()
    env[0]["eq"] = Func((a1, a2), Bool)
    # We'll handle the unification of a1 and a2 during inference? No, eq is in env.
    # To properly support (a, a) -> Bool, we can just store it as Func((fresh(), fresh()), Bool)
    # and rely on unification when called. That's standard.
    # But wait, if we call eq with Int and Bool, it should fail. Unification will catch it.

    # Re-create env properly
    reset_fresh()
    env = [{
        "plus": Func((Int, Int), Int),
        "eq": Func((fresh(), fresh()), Bool),
        "size": Func((Str,), Int)
    }]

    sub = {}
    res_type = infer(term, env, sub)
    res_type = apply_sub(sub, res_type)
    return print_type(res_type)

import string

# --- Type Definitions ---
class Type: pass
class TInt(Type): pass
class TBool(Type): pass
class TFun(Type):
    def __init__(self, arg, res): self.arg, self.res = arg, res
class TList(Type):
    def __init__(self, elem): self.elem = elem
class TTuple(Type):
    def __init__(self, elems): self.elems = elems
class TVar(Type):
    def __init__(self, id): self.id = id

# --- Global State ---
_var_counter = 0
def fresh():
    global _var_counter
    v = TVar(_var_counter)
    _var_counter += 1
    return v

# --- Type Operations ---
def free_vars(t):
    if isinstance(t, TVar): return {t}
    if isinstance(t, TFun): return free_vars(t.arg) | free_vars(t.res)
    if isinstance(t, TList): return free_vars(t.elem)
    if isinstance(t, TTuple): return set().union(*[free_vars(e) for e in t.elems])
    return set()

def apply(s, t):
    if isinstance(t, TVar): return s.get(t, t)
    if isinstance(t, TFun): return TFun(apply(s, t.arg), apply(s, t.res))
    if isinstance(t, TList): return TList(apply(s, t.elem))
    if isinstance(t, TTuple): return TTuple([apply(s, e) for e in t.elems])
    return t

def occurs(v, t):
    if isinstance(t, TVar): return t is v
    if isinstance(t, TFun): return occurs(v, t.arg) or occurs(v, t.res)
    if isinstance(t, TList): return occurs(v, t.elem)
    if isinstance(t, TTuple): return any(occurs(v, e) for e in t.elems)
    return False

def unify(t1, t2, s=None):
    if s is None: s = {}
    t1 = apply(s, t1)
    t2 = apply(s, t2)
    if isinstance(t1, TVar):
        if t1 in s: return unify(s[t1], t2, s)
        if occurs(t1, t2): raise ValueError("Infinite type")
        return {**s, t1: t2}
    if isinstance(t2, TVar):
        if t2 in s: return unify(t1, s[t2], s)
        if occurs(t2, t1): raise ValueError("Infinite type")
        return {**s, t2: t1}
    if type(t1) != type(t2): raise ValueError("Type mismatch")
    if isinstance(t1, TInt) or isinstance(t1, TBool): return s
    if isinstance(t1, TFun):
        s = unify(t1.arg, t2.arg, s)
        return unify(t1.res, t2.res, s)
    if isinstance(t1, TList): return unify(t1.elem, t2.elem, s)
    if isinstance(t1, TTuple):
        if len(t1.elems) != len(t2.elems): raise ValueError("Tuple size mismatch")
        for a, b in zip(t1.elems, t2.elems): s = unify(a, b, s)
        return s
    raise ValueError("Unknown type")

def instantiate(t):
    def sub(t):
        if isinstance(t, TVar): return fresh()
        if isinstance(t, TFun): return TFun(sub(t.arg), sub(t.res))
        if isinstance(t, TList): return TList(sub(t.elem))
        if isinstance(t, TTuple): return TTuple([sub(e) for e in t.elems])
        return t
    return sub(t)

def generalize(t, vars_to_gen):
    if not vars_to_gen: return t
    mapping = {v: fresh() for v in vars_to_gen}
    def sub(t):
        if isinstance(t, TVar): return mapping.get(t, t)
        if isinstance(t, TFun): return TFun(sub(t.arg), sub(t.res))
        if isinstance(t, TList): return TList(sub(t.elem))
        if isinstance(t, TTuple): return TTuple([sub(e) for e in t.elems])
        return t
    return sub(t)

def free_env(env):
    fv = set()
    for scope in env:
        for t in scope.values():
            fv |= free_vars(t)
    return fv

def lookup(name, env):
    for scope in reversed(env):
        if name in scope:
            return instantiate(scope[name])
    raise ValueError("Unbound variable")

# --- Validation ---
def validate(term, depth=0):
    if isinstance(term, bool): return
    if isinstance(term, int): return
    if isinstance(term, str):
        if not term: raise ValueError("Empty string variable")
        return
    if isinstance(term, tuple):
        if len(term) == 0: raise ValueError("Empty tuple")
        tag = term[0]
        if not isinstance(tag, str): raise ValueError("Non-string tag")
        if tag == "lam":
            if len(term) != 3: raise ValueError("Wrong arity for lam")
            if not isinstance(term[1], str) or not term[1]: raise ValueError("Bad name in lam")
            validate(term[2])
        elif tag == "app":
            if len(term) != 3: raise ValueError("Wrong arity for app")
            validate(term[1]); validate(term[2])
        elif tag == "if":
            if len(term) != 4: raise ValueError("Wrong arity for if")
            validate(term[1]); validate(term[2]); validate(term[3])
        elif tag == "let":
            if len(term) != 4: raise ValueError("Wrong arity for let")
            if not isinstance(term[1], str) or not term[1]: raise ValueError("Bad name in let")
            validate(term[2]); validate(term[3])
        elif tag == "letrec":
            if len(term) != 3: raise ValueError("Wrong arity for letrec")
            group = term[1]
            if not isinstance(group, tuple) or len(group) == 0: raise ValueError("letrec group must be non-empty tuple")
            names = set()
            for pair in group:
                if not isinstance(pair, tuple) or len(pair) != 2: raise ValueError("Bad group pair")
                name, expr = pair
                if not isinstance(name, str) or not name: raise ValueError("Bad name in letrec")
                if name in names: raise ValueError("Duplicate name in letrec")
                names.add(name)
                validate(expr)
            validate(term[2])
        elif tag == "tuple":
            n = len(term) - 1
            if n == 1: raise ValueError("Tuple n=1 is invalid")
            for i in range(1, len(term)):
                validate(term[i])
        elif tag == "proj":
            if len(term) != 4: raise ValueError("Wrong arity for proj")
            i, n, e = term[1], term[2], term[3]
            if isinstance(i, bool) or not isinstance(i, int): raise ValueError("i must be int not bool")
            if isinstance(n, bool) or not isinstance(n, int): raise ValueError("n must be int not bool")
            if n < 2: raise ValueError("n >= 2 required for proj")
            if i < 0 or i >= n: raise ValueError("i out of range")
            validate(e)
        else:
            raise ValueError(f"Unknown tag: {tag}")
    else:
        raise ValueError("Malformed term")

# --- Inference ---
INITIAL_ENV = [{
    "add": TFun(TInt, TFun(TInt, TInt)),
    "eq": TFun(TVar(0), TFun(TVar(0), TBool)),
    "nil": TList(TVar(1)),
    "cons": TFun(TVar(2), TFun(TList(TVar(2)), TList(TVar(2)))),
    "head": TFun(TList(TVar(3)), TVar(3)),
    "tail": TFun(TList(TVar(4)), TList(TVar(4))),
    "isnil": TFun(TList(TVar(5)), TBool)
}]

def infer(term, env):
    if isinstance(term, bool): return TBool
    if isinstance(term, int): return TInt
    if isinstance(term, str): return lookup(term, env)

    if isinstance(term, tuple):
        tag = term[0]
        if tag == "lam":
            _, x, body = term
            x_t = fresh()
            body_t = infer(body, env + [{x: x_t}])
            return TFun(x_t, body_t)
        elif tag == "app":
            _, f, a = term
            f_t = infer(f, env)
            a_t = infer(a, env)
            r_t = fresh()
            unify(f_t, TFun(a_t, r_t))
            return r_t
        elif tag == "if":
            _, c, t, e = term
            unify(infer(c, env), TBool)
            t_t = infer(t, env)
            e_t = infer(e, env)
            unify(t_t, e_t)
            return t_t
        elif tag == "let":
            _, x, e1, e2 = term
            t1 = infer(e1, env)
            env_fvs = free_env(env)
            fv1 = free_vars(t1)
            gen_vars = fv1 - env_fvs
            t_gen = generalize(t1, gen_vars)
            return infer(e2, env + [{x: t_gen}])
        elif tag == "letrec":
            _, group, body = term
            env_fvs = free_env(env)
            mono_vars = {name: fresh() for name, _ in group}
            env2 = env + mono_vars
            types = []
            for name, expr in group:
                t = infer(expr, env2)
                s = unify(mono_vars[name], t)
                t = apply(s, t)
                types.append(t)
            t_gens = []
            for t in types:
                fv = free_vars(t)
                gen_vars = fv - env_fvs
                t_gens.append(generalize(t, gen_vars))
            env3 = env + {name: tg for (_, name), tg in zip(group, t_gens)}
            return infer(body, env3)
        elif tag == "tuple":
            elems = [infer(e, env) for e in term[1:]]
            return TTuple(elems)
        elif tag == "proj":
            _, i, n, e = term
            t_t = infer(e, env)
            unify(t_t, TTuple([])) # Force tuple type
            if not isinstance(t_t, TTuple): raise ValueError("Proj on non-tuple")
            if len(t_t.elems) != n: raise ValueError("Proj size mismatch")
            return t_t.elems[i]
    raise ValueError("Malformed term")

# --- Output Formatting ---
def _to_base26(n):
    res = []
    n += 1
    while n > 0:
        n -= 1
        res.append(chr(ord('a') + (n % 26)))
        n //= 26
    return ''.join(reversed(res))

def collect_vars(t, order):
    if isinstance(t, TVar):
        if t not in order: order[t] = len(order)
    elif isinstance(t, TFun):
        collect_vars(t.arg, order)
        collect_vars(t.res, order)
    elif isinstance(t, TList):
        collect_vars(t.elem, order)
    elif isinstance(t, TTuple):
        for e in t.elems:
            collect_vars(e, order)

def print_type(t):
    order = {}
    collect_vars(t, order)
    var_names = {v: _to_base26(i) for v, i in order.items()}

    def fmt(t):
        if isinstance(t, TInt): return "Int"
        if isinstance(t, TBool): return "Bool"
        if isinstance(t, TVar): return var_names[t]
        if isinstance(t, TFun): return f"({fmt(t.arg)} {fmt(t.res)})"
        if isinstance(t, TList): return f"(List {fmt(t.elem)})"
        if isinstance(t, TTuple):
            if not t.elems: return "(Tuple)"
            return f"(Tuple {' '.join(fmt(e) for e in t.elems)})"
        return str(t)
    return fmt(t)

# --- Main Entry Point ---
def group_type(term):
    validate(term)
    _counter = 0 # Reset for fresh run
    global _var_counter
    _var_counter = 0
    t = infer(term, INITIAL_ENV)
    return print_type(t)

import sys

sys.setrecursionlimit(10000)

class TypeVar:
    def __init__(self, id):
        self.id = id
    def __repr__(self):
        return f"TVar({self.id})"
    def __hash__(self):
        return hash(self.id)
    def __eq__(self, other):
        return isinstance(other, TypeVar) and self.id == other.id

class TInt:
    pass

class TBool:
    pass

class TFun:
    def __init__(self, arg, res):
        self.arg = arg
        self.res = res
    def __eq__(self, other):
        return isinstance(other, TFun) and self.arg == other.arg and self.res == other.res
    def __hash__(self):
        return hash((TFun, self.arg, self.res))

class TList:
    def __init__(self, elem):
        self.elem = elem
    def __eq__(self, other):
        return isinstance(other, TList) and self.elem == other.elem
    def __hash__(self):
        return hash((TList, self.elem))

class TTuple:
    def __init__(self, elems):
        self.elems = elems
    def __eq__(self, other):
        return isinstance(other, TTuple) and self.elems == other.elems
    def __hash__(self):
        return hash((TTuple, self.elems))

class Scheme:
    def __init__(self, type, poly_vars):
        self.type = type
        self.poly_vars = poly_vars

var_counter = 0

def fresh():
    global var_counter
    t = TypeVar(var_counter)
    var_counter += 1
    return t

def free_vars(T):
    if isinstance(T, TypeVar):
        return {T}
    elif isinstance(T, TFun):
        return free_vars(T.arg) | free_vars(T.res)
    elif isinstance(T, TList):
        return free_vars(T.elem)
    elif isinstance(T, TTuple):
        res = set()
        for e in T.elems:
            res |= free_vars(e)
        return res
    else:
        return set()

def apply_sub(sub, T):
    if isinstance(T, TypeVar):
        return sub.get(T, T)
    elif isinstance(T, TFun):
        return TFun(apply_sub(sub, T.arg), apply_sub(sub, T.res))
    elif isinstance(T, TList):
        return TList(apply_sub(sub, T.elem))
    elif isinstance(T, TTuple):
        return TTuple(tuple(apply_sub(sub, e) for e in T.elems))
    else:
        return T

def unify(t1, t2, sub):
    t1 = apply_sub(sub, t1)
    t2 = apply_sub(sub, t2)
    if t1 == t2:
        return sub
    if isinstance(t1, TypeVar):
        if t1 in free_vars(t2):
            raise ValueError("Occurs check")
        sub[t1] = t2
        return sub
    if isinstance(t2, TypeVar):
        if t2 in free_vars(t1):
            raise ValueError("Occurs check")
        sub[t2] = t1
        return sub
    if isinstance(t1, TFun) and isinstance(t2, TFun):
        sub = unify(t1.arg, t2.arg, sub)
        return unify(t1.res, t2.res, sub)
    if isinstance(t1, TList) and isinstance(t2, TList):
        return unify(t1.elem, t2.elem, sub)
    if isinstance(t1, TTuple) and isinstance(t2, TTuple):
        if len(t1.elems) != len(t2.elems):
            raise ValueError("Tuple length mismatch")
        for e1, e2 in zip(t1.elems, t2.elems):
            sub = unify(e1, e2, sub)
        return sub
    raise ValueError("Type mismatch")

def gen(env, T):
    fv_env = free_env(env)
    fv_T = free_vars(T)
    poly_vars = fv_T - fv_env
    return Scheme(T, poly_vars)

def free_env(env):
    res = set()
    for d in env:
        for scheme in d.values():
            res |= free_vars(scheme.type) - scheme.poly_vars
    return res

def lookup(env, name):
    for d in reversed(env):
        if name in d:
            scheme = d[name]
            sub = {v: fresh() for v in scheme.poly_vars}
            return apply_sub(sub, scheme.type)
    raise ValueError(f"Unbound variable: {name}")

def initial_env():
    env = [{}]
    env[0]["add"] = Scheme(TFun(TInt, TFun(TInt, TInt)), set())
    a = fresh()
    env[0]["eq"] = Scheme(TFun(a, TFun(a, TBool)), {a})
    a = fresh()
    env[0]["nil"] = Scheme(TList(a), {a})
    a = fresh()
    env[0]["cons"] = Scheme(TFun(a, TFun(TList(a), TList(a))), {a})
    a = fresh()
    env[0]["head"] = Scheme(TFun(TList(a), a), {a})
    a = fresh()
    env[0]["tail"] = Scheme(TFun(TList(a), TList(a)), {a})
    a = fresh()
    env[0]["isnil"] = Scheme(TFun(TList(a), TBool), {a})
    return env

def validate_term(term):
    if isinstance(term, int):
        if isinstance(term, bool):
            raise ValueError("Bool is not Int")
        return
    if isinstance(term, bool):
        return
    if isinstance(term, str):
        if not term:
            raise ValueError("Empty string")
        return
    if not isinstance(term, tuple):
        raise ValueError("Malformed")
    if not term:
        raise ValueError("Empty tuple")
    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Non-str tag")
    if tag == "lam":
        if len(term) != 3:
            raise ValueError("Lam length")
        x, body = term[1], term[2]
        if not isinstance(x, str) or not x:
            raise ValueError("Lam var")
        validate_term(body)
    elif tag == "app":
        if len(term) != 3:
            raise ValueError("App length")
        f, a = term[1], term[2]
        validate_term(f)
        validate_term(a)
    elif tag == "if":
        if len(term) != 4:
            raise ValueError("If length")
        c, t, e = term[1], term[2], term[3]
        validate_term(c)
        validate_term(t)
        validate_term(e)
    elif tag == "let":
        if len(term) != 4:
            raise ValueError("Let length")
        x, e1, e2 = term[1], term[2], term[3]
        if not isinstance(x, str) or not x:
            raise ValueError("Let var")
        validate_term(e1)
        validate_term(e2)
    elif tag == "letrec":
        if len(term) != 3:
            raise ValueError("Letrec length")
        group, body = term[1], term[2]
        if not isinstance(group, tuple) or not group:
            raise ValueError("Letrec group")
        names = set()
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2:
                raise ValueError("Letrec item")
            n, e = item
            if not isinstance(n, str) or not n:
                raise ValueError("Letrec name")
            if n in names:
                raise ValueError("Duplicate name")
            names.add(n)
            validate_term(e)
        validate_term(body)
    elif tag == "tuple":
        if len(term) < 2:
            raise ValueError("Tuple length")
        if len(term) == 2:
            raise ValueError("Tuple n=1")
        for e in term[1:]:
            validate_term(e)
    elif tag == "proj":
        if len(term) != 4:
            raise ValueError("Proj length")
        i, n, e = term[1], term[2], term[3]
        if not isinstance(i, int) or isinstance(i, bool):
            raise ValueError("Proj i")
        if not isinstance(n, int) or isinstance(n, bool):
            raise ValueError("Proj n")
        if n < 2:
            raise ValueError("Proj n<2")
        if i < 0 or i >= n:
            raise ValueError("Proj i")
        validate_term(e)
    else:
        raise ValueError("Unknown tag")

def infer(term, env, sub):
    if isinstance(term, int):
        return TInt
    if isinstance(term, bool):
        return TBool
    if isinstance(term, str):
        return lookup(env, term)
    tag = term[0]
    if tag == "lam":
        x, body = term[1], term[2]
        t = fresh()
        new_env = env + [{x: Scheme(t, set())}]
        body_t = infer(body, new_env, sub)
        return TFun(t, body_t)
    elif tag == "app":
        f, a = term[1], term[2]
        f_t = infer(f, env, sub)
        a_t = infer(a, env, sub)
        r = fresh()
        sub = unify(f_t, TFun(a_t, r), sub)
        return r
    elif tag == "if":
        c, t, e = term[1], term[2], term[3]
        c_t = infer(c, env, sub)
        sub = unify(c_t, TBool, sub)
        t_t = infer(t, env, sub)
        e_t = infer(e, env, sub)
        sub = unify(t_t, e_t, sub)
        return t_t
    elif tag == "tuple":
        elems = term[1:]
        ts = [infer(e, env, sub) for e in elems]
        return TTuple(tuple(ts))
    elif tag == "proj":
        i, n, e = term[1], term[2], term[3]
        e_t = infer(e, env, sub)
        e_t = apply_sub(sub, e_t)
        if not isinstance(e_t, TTuple):
            raise ValueError("Proj on non-tuple")
        if len(e_t.elems) != n:
            raise ValueError("Proj length mismatch")
        return e_t.elems[i]
    elif tag == "let":
        x, e1, e2 = term[1], term[2], term[3]
        e1_t = infer(e1, env, sub)
        scheme = gen(env, e1_t)
        new_env = env + [{x: scheme}]
        return infer(e2, new_env, sub)
    elif tag == "letrec":
        group, body = term[1], term[2]
        names = [n for n, _ in group]
        exprs = [e for _, e in group]
        mono_vars = {fresh() for _ in names}
        new_env = env + [{n: Scheme(v, set()) for n, v in zip(names, mono_vars)}]
        ts = [infer(e, new_env, sub) for e in exprs]
        for v, t in zip(mono_vars, ts):
            sub = unify(v, t, sub)
        schemes = [gen(env, t) for t in ts]
        new_env = env + [{n: s for n, s in zip(names, schemes)}]
        return infer(body, new_env, sub)
    else:
        raise ValueError("Unknown tag")

def to_string(T, var_map):
    if isinstance(T, TInt):
        return "Int"
    if isinstance(T, TBool):
        return "Bool"
    if isinstance(T, TypeVar):
