import sys

# Type System
class Type:
    def __init__(self):
        pass

class TInt(Type):
    def __repr__(self): return "Int"

class TBool(Type):):
    def __repr__(self): return "Bool"

class TVar(Type):
    _counter = 0
    def __init__(self):
        self.id = TVar._counter
        TVar._counter += 1
    def __repr__(self): return f"TVar({self.id})"

class TFun(Type):
    def __init__(self, arg, res):
        self.arg = arg
        self.res = res
    def __repr__(self): return f"({self.arg} -> {self.res})"

class TList(Type):
    def __init__(self, elem):
        self.elem = elem
    def __repr__(self): return f"(List {self.elem})"

class TTuple(Type):
    def __init__(self, elems):
        self.elems = elems
    def __repr__(self):
        if not self.elems: return "(Tuple)"
        return f"(Tuple {' '.join(map(str, self.elems))})"

# Substitution
def apply_subst(subst, t):
    if isinstance(t, TVar):
        return subst.get(t.id, t)
    elif isinstance(t, TFun):
        return TFun(apply_subst(subst, t.arg), apply_subst(subst, t.res))
    elif isinstance(t, TList):
        return TList(apply_subst(subst, t.elem))
    elif isinstance(t, TTuple):
        return TTuple([apply_subst(subst, e) for e in t.elems])
    else:
        return t

def free_vars(t):
    if isinstance(t, TVar):
        return {t.id}
    elif isinstance(t, TFun):
        return free_vars(t.arg) | free_vars(t.res)
    elif isinstance(t, TList):
        return free_vars(t.elem)
    elif isinstance(t, TTuple):
        res = set()
        for e in t.elems:
            res |= free_vars(e)
        return res
    else:
        return set()

def unify(t1, t2, subst=None):
    if subst is None:
        subst = {}

    t1 = apply_subst(subst, t1)
    t2 = apply_subst(subst, t2)

    if t1 == t2:
        return subst

    if isinstance(t1, TVar):
        return unify_var(t1, t2, subst)
    if isinstance(t2, TVar):
        return unify_var(t2, t1, subst)

    if isinstance(t1, TFun) and isinstance(t2, TFun):
        s = unify(t1.arg, t2.arg, subst)
        return unify(t1.res, t2.res, s)
    if isinstance(t1, TList) and isinstance(t2, TList):
        return unify(t1.elem, t2.elem, subst)
    if isinstance(t1, TTuple) and isinstance(t2, TTuple):
        if len(t1.elems) != len(t2.elems):
            raise ValueError("Tuple length mismatch")
        s = subst
        for e1, e2 in zip(t1.elems, t2.elems):
            s = unify(e1, e2, s)
        return s

    raise ValueError(f"Type mismatch: {t1} vs {t2}")

def unify_var(v, t, subst):
    if isinstance(t, TVar) and v.id == t.id:
        return subst
    if isinstance(t, TVar) and v.id != t.id:
        return unify_var(t, v, subst)

    if v.id in free_vars(t):
        raise ValueError("Occurs check failed")

    new_subst = dict(subst)
    new_subst[v.id] = t
    return new_subst

# Environment
def instantiate(scheme, fresh_var_fn):
    bound, t = scheme
    mapping = {tv: TVar() for tv in bound}
    return apply_subst(mapping, t)

def generalize(t, env):
    fv = free_vars(t)
    env_fv = set()
    for scope in env:
        for name, (bound, scheme_type) in scope.items():
            env_fv |= free_vars(scheme_type)
    to_gen = fv - env_fv
    return (to_gen, t)

# Validation
def validate_term(term):
    if isinstance(term, bool):
        raise ValueError("Bool is not Int")
    if isinstance(term, int):
        return
    if term is True or term is False:
        return
    if isinstance(term, str):
        if len(term) == 0:
            raise ValueError("Empty string variable")
        return

    if not isinstance(term, tuple):
        raise ValueError("Term must be tuple or primitive")

    if len(term) == 0:
        raise ValueError("Empty tuple term")

    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Tag must be string")

    if tag == "lam":
        if len(term) != 3: raise ValueError("Lam arity")
        x, body = term[1], term[2]
        if not isinstance(x, str) or len(x) == 0: raise ValueError("Lam var")
        validate_term(body)
    elif tag == "app":
        if len(term) != 3: raise ValueError("App arity")
        validate_term(term[1])
        validate_term(term[2])
    elif tag == "if":
        if len(term) != 4: raise ValueError("If arity")
        validate_term(term[1])
        validate_term(term[2])
        validate_term(term[3])
    elif tag == "let":
        if len(term) != 4: raise ValueError("Let arity")
        x = term[1]
        if not isinstance(x, str) or len(x) == 0: raise ValueError("Let var")
        validate_term(term[2])
        validate_term(term[3])
    elif tag == "letrec":
        if len(term) != 3: raise ValueError("Letrec arity")
        group = term[1]
        if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Letrec group")
        names = set()
        for pair in group:
            if not isinstance(pair, tuple) or len(pair) != 2: raise ValueError("Letrec pair")
            n, e = pair
            if not isinstance(n, str) or len(n) == 0: raise ValueError("Letrec name")
            if n in names: raise ValueError("Letrec duplicate name")
            names.add(n)
            validate_term(e)
        validate_term(term[2])
    elif tag == "tuple":
        n = len(term) - 1
        if n == 1: raise ValueError("Tuple n=1")
        for i in range(1, len(term)):
            validate_term(term[i])
    elif tag == "proj":
        if len(term) != 4: raise ValueError("Proj arity")
        i, n, e = term[1], term[2], term[3]
        if not isinstance(i, int) or isinstance(i, bool): raise ValueError("Proj i")
        if not isinstance(n, int) or isinstance(n, bool): raise ValueError("Proj n")
        if n < 2: raise ValueError("Proj n<2")
        if i < 0 or i >= n: raise ValueError("Proj i out of range")
        validate_term(e)
    else:
        raise ValueError(f"Unknown tag {tag}")

# Inference
def infer(term, env):
    if isinstance(term, bool):
        return TBool
    if isinstance(term, int):
        return TInt
    if isinstance(term, str):
        for scope in reversed(env):
            if term in scope:
                bound, t = scope[term]
                mapping = {tv: TVar() for tv in bound}
                return apply_subst(mapping, t)
        raise ValueError(f"Unbound variable {term}")

    tag = term[0]

    if tag == "lam":
        x, body = term[1], term[2]
        tx = TVar()
        body_type = infer(body, env + [{x: (set(), tx)}])
        return TFun(tx, body_type)

    if tag == "app":
        f, a = term[1], term[2]
        f_type = infer(f, env)
        a_type = infer(a, env)
        r = TVar()
        unify(f_type, TFun(a_type, r))
        return r

    if tag == "if":
        c, t, e = term[1], term[2], term[3]
        c_type = infer(c, env)
        unify(c_type, TBool)
        t_type = infer(t, env)
        e_type = infer(e, env)
        unify(t_type, e_type)
        return t_type

    if tag == "let":
        x, e1, e2 = term[1], term[2], term[3]
        e1_type = infer(e1, env)
        scheme = generalize(e1_type, env)
        return infer(e2, env + [{x: scheme}])

    if tag == "letrec":
        group, body = term[1], term[2]
        bindings = {}
        for n, e in group:
            bindings[n] = TVar()

        new_env = env + [bindings]
        types = []
        for n, e in group:
            t = infer(e, new_env)
            types.append((n, t))

        for n, t in types:
            unify(bindings[n], t)

        final_bindings = {}
        for n, t in types:
            scheme = generalize(t, env)
            final_bindings[n] = scheme

        return infer(body, env + [final_bindings])

    if tag == "tuple":
        elems = term[1:]
        ts = [infer(e, env) for e in elems]
        return TTuple(ts)

    if tag == "proj":
        i, n, e = term[1], term[2], term[3]
        e_type = infer(e, env)
        fresh_elems = [TVar() for _ in range(n)]
        unify(e_type, TTuple(fresh_elems))
        return fresh_elems[i]

    raise ValueError(f"Unknown tag {tag}")

def get_name(idx):
    if idx < 26:
        return chr(ord('a') + idx)
    else:
        n = idx
        chars = []
        while n >= 0:
            n -= 1
            chars.append(chr(ord('a') + n % 26))
            n //= 26
            if n < 0: break
        return ''.join(reversed(chars))

def group_type(term):
    validate_term(term)
    TVar._counter = 0

    a = TVar()
    add_scheme = (set(), TFun(TInt, TFun(TInt, TInt)))
    eq_scheme = ({a}, TFun(a, TFun(a, TBool)))
    nil_scheme = ({a}, TList(a))
    cons_scheme = ({a}, TFun(a, TFun(TList(a), TList(a))))
    head_scheme = ({a}, TFun(TList(a), a))
    tail_scheme = ({a}, TFun(TList(a), TList(a)))
    isnil_scheme = ({a}, TFun(TList(a), TBool))

    initial_env = [{
        "add": add_scheme,
        "eq": eq_scheme,
        "nil": nil_scheme,
        "cons": cons_scheme,
        "head": head_scheme,
        "tail": tail_scheme,
        "isnil": isnil_scheme
    }]

    result_type = infer(term, initial_env)

    var_order = []
    seen_ids = set()

    def collect_vars(t):
        if isinstance(t, TVar):
            if t.id not in seen_ids:
                seen_ids.add(t.id)
                var_order.append(t)
        elif isinstance(t, TFun):
            collect_vars(t.arg)
            collect_vars(t.res)
        elif isinstance(t, TList):
            collect_vars(t.elem)
        elif isinstance(t, TTuple):
            for e in t.elems:
                collect_vars(e)

    collect_vars(result_type)

    id_to_name = {}
    for i, var in enumerate(var_order):
        id_to_name[var.id] = get_name(i)

    def format_type(t):
        if isinstance(t, TVar):
            return id_to_name[t.id]
        elif isinstance(t, TInt):
            return "Int"
        elif isinstance(t, TBool):
            return "Bool"
        elif isinstance(t, TFun):
            return f"({format_type(t.arg)} -> {format_type(t.res)})"
        elif isinstance(t, TList):
            return f"(List {format_type(t.elem)})"
        elif isinstance(t, TTuple):
            if not t.elems:
                return "(Tuple)"
            return f"(Tuple {' '.join(format_type(e) for e in t.elems)})"
        return str(t)

    return format_type(result_type)

import sys
sys.setrecursionlimit(10000)

class TVar:
    __slots__ = ('id',)
    def __init__(self, id): self.id = id
    def __repr__(self): return f"TVar({self.id})"
    def __eq__(self, other): return isinstance(other, TVar) and self.id == other.id
    def __hash__(self): return self.id

class TInt: pass
class TBool: pass
class TFun:
    __slots__ = ('arg', 'res')
    def __init__(self, arg, res): self.arg = arg; self.res = res
class TList:
    __slots__ = ('elem',)
    def __init__(self, elem): self.elem = elem
class TTuple:
    __slots__ = ('elems',)
    def __init__(self, elems): self.elems = elems

def free_vars(t):
    if isinstance(t, TVar): return {t}
    if isinstance(t, TFun): return free_vars(t.arg) | free_vars(t.res)
    if isinstance(t, TList): return free_vars(t.elem)
    if isinstance(t, TTuple): return set().union(*(free_vars(e) for e in t.elems))
    return set()

def free_env(env):
    fv = set()
    for scope in env:
        for t in scope.values():
            fv |= free_vars(t)
    return fv

def apply(sub, t):
    if isinstance(t, TVar):
        return sub.get(t, t)
    if isinstance(t, TFun):
        return TFun(apply(sub, t.arg), apply(sub, t.res))
    if isinstance(t, TList):
        return TList(apply(sub, t.elem))
    if isinstance(t, TTuple):
        return TTuple([apply(sub, e) for e in t.elems])
    return t

def occurs(x, t):
    if isinstance(t, TVar): return t is x
    if isinstance(t, TFun): return occurs(x, t.arg) or occurs(x, t.res)
    if isinstance(t, TList): return occurs(x, t.elem)
    if isinstance(t, TTuple): return any(occurs(x, e) for e in t.elems)
    return False

def unify(t1, t2, sub):
    t1 = apply(sub, t1)
    t2 = apply(sub, t2)
    if isinstance(t1, TVar):
        if t1 in sub: return unify(sub[t1], t2, sub)
        if occurs(t1, t2): raise ValueError
        sub[t1] = t2
        return sub
    if isinstance(t2, TVar):
        return unify(t2, t1, sub)
    if type(t1) != type(t2): raise ValueError
    if isinstance(t1, TFun):
        unify(t1.arg, t2.arg, sub)
        unify(t1.res, t2.res, sub)
    elif isinstance(t1, TList):
        unify(t1.elem, t2.elem, sub)
    elif isinstance(t1, TTuple):
        if len(t1.elems) != len(t2.elems): raise ValueError
        for e1, e2 in zip(t1.elems, t2.elems): unify(e1, e2, sub)
    elif isinstance(t1, (TInt, TBool)):
        pass
    return sub

def instantiate(t, var_counter):
    mapping = {}
    def get_fresh(tv):
        if tv not in mapping:
            mapping[tv] = TVar(var_counter[0])
            var_counter[0] += 1
        return mapping[tv]
    def apply_inst(t):
        if isinstance(t, TVar): return get_fresh(t)
        if isinstance(t, TFun): return TFun(apply_inst(t.arg), apply_inst(t.res))
        if isinstance(t, TList): return TList(apply_inst(t.elem))
        if isinstance(t, TTuple): return TTuple([apply_inst(e) for e in t.elems])
        return t
    return apply_inst(t)

def generalize(t, env, var_counter):
    fv = free_vars(t) - free_env(env)
    if not fv: return t, var_counter
    mapping = {}
    for tv in fv:
        mapping[tv] = TVar(var_counter[0])
        var_counter[0] += 1
    t_gen = apply(mapping, t)
    return t_gen, var_counter

def var_name(idx):
    name = ""
    idx += 1
    while idx > 0:
        idx, rem = divmod(idx - 1, 26)
        name = chr(ord('a') + rem) + name
    return name

def collect_vars(t):
    if isinstance(t, TVar): return {t.id}
    if isinstance(t, TFun): return collect_vars(t.arg) | collect_vars(t.res)
    if isinstance(t, TList): return collect_vars(t.elem)
    if isinstance(t, TTuple): return set().union(*(collect_vars(e) for e in t.elems))
    return set()

def print_type(t, var_map):
    if isinstance(t, TVar): return var_map[t.id]
    if isinstance(t, TInt): return "Int"
    if isinstance(t, TBool): return "Bool"
    if isinstance(t, TList): return f"(List {print_type(t.elem, var_map)})"
    if isinstance(t, TTuple):
        if not t.elems: return "(Tuple)"
        return f"(Tuple {' '.join(print_type(e, var_map) for e in t.elems)})"
    if isinstance(t, TFun):
        return f"(-> {print_type(t.arg, var_map)} {print_type(t.res, var_map)})"
    return "?"

def validate(term):
    if isinstance(term, int):
        if isinstance(term, bool): raise ValueError("Bool is not Int")
        return
    if term is True or term is False: return
    if isinstance(term, str):
        if not term: raise ValueError("Empty str")
        return
    if not isinstance(term, tuple) or len(term) == 0: raise ValueError("Malformed")
    tag = term[0]
    if not isinstance(tag, str): raise ValueError("Malformed")
    if tag == "lam":
        if len(term) != 3: raise ValueError("Malformed")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Bad name")
        validate(term[2])
    elif tag == "app":
        if len(term) != 3: raise ValueError("Malformed")
        validate(term[1]); validate(term[2])
    elif tag == "if":
        if len(term) != 4: raise ValueError("Malformed")
        validate(term[1]); validate(term[2]); validate(term[3])
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Bad name")
        validate(term[2]); validate(term[3])
    elif tag == "letrec":
        if len(term) != 3: raise ValueError("Malformed")
        group = term[1]; body = term[2]
        if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Malformed letrec")
        names = []
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2: raise ValueError("Malformed letrec group")
            nm = item[0]
            if not isinstance(nm, str) or not nm: raise ValueError("Bad name")
            names.append(nm)
            validate(item[1])
        if len(set(names)) != len(names): raise ValueError("Duplicate names")
        validate(body)
    elif tag == "tuple":
        elems = term[1:]
        if len(elems) == 1: raise ValueError("Tuple of length 1")
        for e in elems: validate(e)
    elif tag == "proj":
        if len(term) != 4: raise ValueError("Malformed")
        i, n, e = term[1], term[2], term[3]
        if isinstance(i, bool) or isinstance(n, bool): raise ValueError("i, n must be ints")
        if not isinstance(i, int) or not isinstance(n, int): raise ValueError("i, n must be ints")
        if n < 2 or not (0 <= i < n): raise ValueError("proj bounds")
        validate(e)
    else:
        raise ValueError(f"Unknown tag: {tag}")

def lookup(name, env, var_counter):
    for scope in reversed(env):
        if name in scope:
            return instantiate(scope[name], var_counter)
    raise ValueError(f"Unbound variable: {name}")

def infer(term, env, sub, var_counter):
    if isinstance(term, int) and not isinstance(term, bool):
        return TInt()
    if term is True or term is False:
        return TBool()
    if isinstance(term, str):
        return lookup(term, env, var_counter)

    tag = term[0]
    if tag == "lam":
        x, body = term[1], term[2]
        x_t = TVar(var_counter[0]); var_counter[0] += 1
        body_t = infer(body, env + [{x: x_t}], sub, var_counter)
        return TFun(x_t, body_t)
    elif tag == "app":
        f, a = term[1], term[2]
        f_t = infer(f, env, sub, var_counter)
        a_t = infer(a, env, sub, var_counter)
        r_t = TVar(var_counter[0]); var_counter[0] += 1
        unify(TFun(a_t, r_t), f_t, sub)
        return r_t
    elif tag == "if":
        c, t, e = term[1], term[2], term[3]
        c_t = infer(c, env, sub, var_counter)
        unify(c_t, TBool(), sub)
        t_t = infer(t, env, sub, var_counter)
        e_t = infer(e, env, sub, var_counter)
        unify(t_t, e_t, sub)
        return t_t
    elif tag == "tuple":
        ts = [infer(e, env, sub, var_counter) for e in term[1:]]
        return TTuple(ts)
    elif tag == "proj":
        i, n, e = term[1], term[2], term[3]
        e_t = infer(e, env, sub, var_counter)
        fresh_ts = [TVar(var_counter[0] + j) for j in range(n)]
        var_counter[0] += n
        unify(e_t, TTuple(fresh_ts), sub)
        return fresh_ts[i]
    elif tag == "let":
        x, e1, e2 = term[1], term[2], term[3]
        e1_t = infer(e1, env, sub, var_counter)
        e1_t_gen, var_counter = generalize(e1_t, env, var_counter)
        return infer(e2, env + [{x: e1_t_gen}], sub, var_counter)
    elif tag == "letrec":
        group, body = term[1], term[2]
        names = [item[0] for item in group]
        exprs = [item[1] for item in group]
        env_rec = [{nm: TVar(var_counter[0] + i) for i, nm in enumerate(names)}]
        var_counter[0] += len(names)
        rec_ts = [infer(ex, env + env_rec, sub, var_counter) for ex in exprs]
        for i, nm in enumerate(names):
            unify(env_rec[0][nm], rec_ts[i], sub)
        outer_fv = free_env(env)
        gen_ts = []
        for nm, rec_t in zip(names, rec_ts):
            fv = free_vars(rec_t) - outer_fv
            if fv:
                mapping = {}
                for tv in fv:
                    mapping[tv] = TVar(var_counter[0])
                    var_counter[0] += 1
                gen_t = apply(mapping, rec_t)
            else:
                gen_t = rec_t
            gen_ts.append(gen_t)
        env_rec[0] = {nm: gt for nm, gt in zip(names, gen_ts)}
        return infer(body, env + env_rec, sub, var_counter)
    else:
        raise ValueError(f"Unknown tag: {tag}")

def group_type(term):
    validate(term)
    env = []
    var_counter = [0]
    sub = {}
    result_t = infer(term, env, sub, var_counter)
    final_t = apply(sub, result_t)
    ids = sorted(collect_vars(final_t))
    var_map = {i: var_name(i) for i in ids}
    return print_type(final_t, var_map)

import sys

class Type:
    __slots__ = ('tag', 'args')
    def __init__(self, tag, *args):
        self.tag = tag
        self.args = args
    def __eq__(self, other):
        return isinstance(other, Type) and self.tag == other.tag and self.args == other.args
    def __hash__(self):
        return hash((self.tag, self.args))

TInt = Type("Int")
TBool = Type("Bool")

_var_counter = 0

def fresh_var():
    global _var_counter
    t = Type("Var", _var_counter)
    _var_counter += 1
    return t

def free_vars(t):
    if t.tag == "Var": return {t}
    if t.tag in ("Int", "Bool"): return set()
    if t.tag == "Fun": return free_vars(t.args[0]) | free_vars(t.args[1])
    if t.tag == "List": return free_vars(t.args[0])
    if t.tag == "Tuple":
        res = set()
        for e in t.args: res |= free_vars(e)
        return res
    return set()

def apply(subst, t):
    if t.tag == "Var" and t in subst:
        return apply(subst, subst[t])
    if t.tag == "Fun":
        return Type("Fun", apply(subst, t.args[0]), apply(subst, t.args[1]))
    if t.tag == "List":
        return Type("List", apply(subst, t.args[0]))
    if t.tag == "Tuple":
        return Type("Tuple", tuple(apply(subst, e) for e in t.args))
    return t

def occurs(v, t):
    if t.tag == "Var": return t == v
    if t.tag == "Fun": return occurs(v, t.args[0]) or occurs(v, t.args[1])
    if t.tag == "List": return occurs(v, t.args[0])
    if t.tag == "Tuple": return any(occurs(v, e) for e in t.args)
    return False

def unify(t1, t2, subst):
    t1 = apply(subst, t1)
    t2 = apply(subst, t2)
    if t1 == t2: return subst
    if t1.tag == "Var":
        if occurs(t1, t2): raise ValueError("Infinite type")
        return {**subst, t1: t2}
    if t2.tag == "Var":
        if occurs(t2, t1): raise ValueError("Infinite type")
        return {**subst, t2: t1}
    if t1.tag != t2.tag or len(t1.args) != len(t2.args):
        raise ValueError("Type mismatch")
    for a1, a2 in zip(t1.args, t2.args):
        subst = unify(a1, a2, subst)
    return subst

def generalize(t, fvs):
    sub = {}
    for v in fvs:
        sub[v] = fresh_var()
    return apply(sub, t)

def free_env(env):
    res = set()
    for scope in env:
        for t in scope.values():
            res |= free_vars(t)
    return res

def lookup(name, env):
    for scope in reversed(env):
        if name in scope:
            return scope[name]
    raise ValueError("Unbound variable")

def validate_term(term):
    if isinstance(term, bool):
        raise ValueError("Malformed: bool used as int")
    if isinstance(term, int):
        return
    if isinstance(term, str):
        if not term: raise ValueError("Malformed: empty str")
        return
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed: invalid term structure")

    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed: non-str tag")

    if tag == "lam":
        if len(term) != 3: raise ValueError("Malformed: lam arity")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed: lam param")
        validate_term(term[2])
    elif tag == "app":
        if len(term) != 3: raise ValueError("Malformed: app arity")
        validate_term(term[1])
        validate_term(term[2])
    elif tag == "if":
        if len(term) != 4: raise ValueError("Malformed: if arity")
        validate_term(term[1])
        validate_term(term[2])
        validate_term(term[3])
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed: let arity")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed: let name")
        validate_term(term[2])
        validate_term(term[3])
    elif tag == "letrec":
        if len(term) != 3: raise ValueError("Malformed: letrec arity")
        group = term[1]
        if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Malformed: letrec group")
        names = set()
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2: raise ValueError("Malformed: letrec pair")
            name, expr = item
            if not isinstance(name, str) or not name: raise ValueError("Malformed: letrec name")
            if name in names: raise ValueError("Malformed: letrec duplicate name")
            names.add(name)
            validate_term(expr)
        validate_term(term[2])
    elif tag == "tuple":
        if len(term) - 1 == 1: raise ValueError("Malformed: tuple n=1")
        for i in range(1, len(term)):
            validate_term(term[i])
    elif tag == "proj":
        if len(term) != 4: raise ValueError("Malformed: proj arity")
        i, n, e = term[1], term[2], term[3]
        if isinstance(i, bool) or not isinstance(i, int): raise ValueError("Malformed: proj i")
        if isinstance(n, bool) or not isinstance(n, int): raise ValueError("Malformed: proj n")
        if n < 2: raise ValueError("Malformed: proj n<2")
        if not (0 <= i < n): raise ValueError("Malformed: proj i out of range")
        validate_term(e)
    else:
        raise ValueError("Malformed: unknown tag")

def infer(term, env):
    if isinstance(term, int):
        return TInt
    if isinstance(term, bool):
        return TBool
    if isinstance(term, str):
        return lookup(term, env)

    tag = term[0]
    if tag == "lam":
        x, body = term[1], term[2]
        x_t = fresh_var()
        body_t = infer(body, env + [{x: x_t}])
        return Type("Fun", x_t, body_t)

    elif tag == "app":
        f, a = term[1], term[2]
        f_t = infer(f, env)
        a_t = infer(a, env)
        r_t = fresh_var()
        subst = unify(f_t, Type("Fun", a_t, r_t), {})
        return apply(subst, r_t)

    elif tag == "if":
        c, t, e = term[1], term[2], term[3]
        unify(infer(c, env), TBool, {})
        t_t = infer(t, env)
        e_t = infer(e, env)
        unify(t_t, e_t, {})
        return t_t

    elif tag == "tuple":
        es = term[1:]
        ts = [infer(e, env) for e in es]
        return Type("Tuple", tuple(ts))

    elif tag == "proj":
        i, n, e = term[1], term[2], term[3]
        e_t = infer(e, env)
        tuple_t = Type("Tuple", tuple(fresh_var() for _ in range(n)))
        subst = unify(e_t, tuple_t, {})
        return apply(subst, tuple_t.args[0][i])

    elif tag == "let":
        x, e1, e2 = term[1], term[2], term[3]
        e1_t = infer(e1, env)
        fv = free_vars(e1_t) - free_env(env)
        e1_gen = generalize(e1_t, fv)
        return infer(e2, env + [{x: e1_gen}])

    elif tag == "letrec":
        group, body = term[1], term[2]
        names = [item[0] for item in group]
        monos = {name: fresh_var() for name in names}
        env2 = env + [monos]
        expr_ts = []
        for _, expr in group:
            expr_ts.append(infer(expr, env2))
        for name, t in zip(names, expr_ts):
            unify(monos[name], t, {})
        outer_fvs = free_env(env)
        gen_ts = []
        for t in expr_ts:
            fv = free_vars(t) - outer_fvs
            gen_ts.append(generalize(t, fv))
        env3 = env + [{name: t for name, t in zip(names, gen_ts)}]
        return infer(body, env3)

    else:
        raise ValueError("Malformed: unknown tag")

def var_name(idx):
    res = []
    while idx >= 0:
        res.append(chr(ord('a') + idx % 26))
        idx = idx // 26 - 1
    return ''.join(reversed(res))

def to_str(t, var_map):
    if t.tag == "Int": return "Int"
    if t.tag == "Bool": return "Bool"
    if t.tag == "Var": return var_map[t.args[0]]
    if t.tag == "Fun": return f"({to_str(t.args[0], var_map)} -> {to_str(t.args[1], var_map)})"
    if t.tag == "List": return f"(List {to_str(t.args[0], var_map)})"
    if t.tag == "Tuple":
        if not t.args: return "(Tuple)"
        return f"(Tuple {' '.join(to_str(e, var_map) for e in t.args)})"
    return "?"

def group_type(term):
    global _var_counter
    _var_counter = 0

    validate_term(term)

    a1 = fresh_var()
    a2 = fresh_var()
    a3 = fresh_var()
    a4 = fresh_var()
    a5 = fresh_var()
    a6 = fresh_var()
    a7 = fresh_var()

    eq_t = Type("Fun", a1, Type("Fun", a1, TBool))
    eq_gen = generalize(eq_t, free_vars(eq_t))

    nil_t = Type("List", a2)
    nil_gen = generalize(nil_t, free_vars(nil_t))

    cons_t = Type("Fun", a3, Type("Fun", Type("List", a3), Type("List", a3)))
    cons_gen = generalize(cons_t, free_vars(cons_t))

    head_t = Type("Fun", Type("List", a4), a4)
    head_gen = generalize(head_t, free_vars(head_t))

    tail_t = Type("Fun", Type("List", a5), Type("List", a5))
    tail_gen = generalize(tail_t, free_vars(tail_t))

    isnil_t = Type("Fun", Type("List", a6), TBool)
    isnil_gen = generalize(isnil_t, free_vars(isnil_t))

    add_t = Type("Fun", TInt, Type("Fun", TInt, TInt))
    add_gen = generalize(add_t, free_vars(add_t))

    init_env = [{
        "add": add_gen,
        "eq": eq_gen,
        "nil": nil_gen,
        "cons": cons_gen,
        "head": head_gen,
        "tail": tail_gen,
        "isnil": isnil_gen
    }]

    res_t = infer(term, init_env)

    all_vars = free_vars(res_t)
    sorted_vars = sorted(all_vars, key=lambda v: v.args[0])
    var_map = {v.args[0]: var_name(i) for i, v in enumerate(sorted_vars)}

    return to_str(res_t, var_map)

import sys

class Type:
    __slots__ = ('tag', 'args')
    def __init__(self, tag, *args):
        self.tag = tag
        self.args = args
    def __eq__(self, other):
        return isinstance(other, Type) and self.tag == other.tag and self.args == other.args
    def __hash__(self):
        return hash((self.tag, self.args))

TInt = Type("Int")
TBool = Type("Bool")

_var_counter = 0
_subst = {}

def fresh_var():
    global _var_counter
    t = Type("Var", _var_counter)
    _var_counter += 1
    return t

def free_vars(t):
    if t.tag == "Var": return {t}
    if t.tag in ("Int", "Bool"): return set()
    if t.tag == "Fun": return free_vars(t.args[0]) | free_vars(t.args[1])
    if t.tag == "List": return free_vars(t.args[0])
    if t.tag == "Tuple":
        res = set()
        for e in t.args: res |= free_vars(e)
        return res
    return set()

def apply(t):
    if t.tag == "Var" and t in _subst:
        return apply(_subst[t])
    if t.tag == "Fun":
        return Type("Fun", apply(t.args[0]), apply(t.args[1]))
    if t.tag == "List":
        return Type("List", apply(t.args[0]))
    if t.tag == "Tuple":
        return Type("Tuple", tuple(apply(e) for e in t.args))
    return t

def occurs(v, t):
    if t.tag == "Var": return t == v
    if t.tag == "Fun": return occurs(v, t.args[0]) or occurs(v, t.args[1])
    if t.tag == "List": return occurs(v, t.args[0])
    if t.tag == "Tuple": return any(occurs(v, e) for e in t.args)
    return False

def unify(t1, t2):
    t1 = apply(t1)
    t2 = apply(t2)
    if t1 == t2: return
    if t1.tag == "Var":
        if occurs(t1, t2): raise ValueError("Infinite type")
        _subst[t1] = t2
        return
    if t2.tag == "Var":
        if occurs(t2, t1): raise ValueError("Infinite type")
        _subst[t2] = t1
        return
    if t1.tag != t2.tag or len(t1.args) != len(t2.args):
        raise ValueError("Type mismatch")
    for a1, a2 in zip(t1.args, t2.args):
        unify(a1, a2)

def generalize(t, fvs):
    sub = {}
    for v in fvs:
        sub[v] = fresh_var()
    # Apply the new substitution to t
    def apply_sub(t):
        if t.tag == "Var" and t in sub:
            return sub[t]
        if t.tag == "Fun":
            return Type("Fun", apply_sub(t.args[0]), apply_sub(t.args[1]))
        if t.tag == "List":
            return Type("List", apply_sub(t.args[0]))
        if t.tag == "Tuple":
            return Type("Tuple", tuple(apply_sub(e) for e in t.args))
        return t
    return apply_sub(t)

def free_env(env):
    res = set()
    for scope in env:
        for t in scope.values():
            res |= free_vars(t)
    return res

def lookup(name, env):
    for scope in reversed(env):
        if name in scope:
            return scope[name]
    raise ValueError("Unbound variable")

def validate_term(term):
    if isinstance(term, bool):
        return
    if isinstance(term, int):
        return
    if isinstance(term, str):
        if not term: raise ValueError("Malformed: empty str")
        return
    if not isinstance(term, tuple) or len(term) == 0:
        raise ValueError("Malformed: invalid term structure")

    tag = term[0]
    if not isinstance(tag, str):
        raise ValueError("Malformed: non-str tag")

    if tag == "lam":
        if len(term) != 3: raise ValueError("Malformed: lam arity")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed: lam param")
        validate_term(term[2])
    elif tag == "app":
        if len(term) != 3: raise ValueError("Malformed: app arity")
        validate_term(term[1])
        validate_term(term[2])
    elif tag == "if":
        if len(term) != 4: raise ValueError("Malformed: if arity")
        validate_term(term[1])
        validate_term(term[2])
        validate_term(term[3])
    elif tag == "let":
        if len(term) != 4: raise ValueError("Malformed: let arity")
        if not isinstance(term[1], str) or not term[1]: raise ValueError("Malformed: let name")
        validate_term(term[2])
        validate_term(term[3])
    elif tag == "letrec":
        if len(term) != 3: raise ValueError("Malformed: letrec arity")
        group = term[1]
        if not isinstance(group, tuple) or len(group) == 0: raise ValueError("Malformed: letrec group")
        names = set()
        for item in group:
            if not isinstance(item, tuple) or len(item) != 2: raise ValueError("Malformed: letrec pair")
            name, expr = item
            if not isinstance(name, str) or not name: raise ValueError("Malformed: letrec name")
            if name in names: raise ValueError("Malformed: letrec duplicate name")
            names.add(name)
            validate_term(expr)
        validate_term(term[2])
    elif tag == "tuple":
        if len(term) - 1 == 1: raise ValueError("Malformed: tuple n=1")
        for i in range(1, len(term)):
            validate_term(term[i])
    elif tag == "proj":
        if len(term) != 4: raise ValueError("Malformed: proj arity")
        i, n, e = term[1], term[2], term[3]
        if isinstance(i, bool) or not isinstance(i, int): raise ValueError("Malformed: proj i")
        if isinstance(n, bool) or not isinstance(n, int): raise ValueError("Malformed: proj n")
        if n < 2: raise ValueError("Malformed: proj n<2")
        if not (0 <= i < n): raise ValueError("Malformed: proj i out of range")
        validate_term(e)
    else:
        raise ValueError("Malformed: unknown tag")

def infer(term, env):
    if isinstance(term, int):
        return apply(TInt)
    if isinstance(term, bool):
        return apply(TBool)
    if isinstance(term, str):
        return apply(lookup(term, env))

    tag = term[0]
    if tag == "lam":
        x, body = term[1], term[2]
        x_t = fresh_var()
        body_t = infer(body, env + [{x: x_t}])
        return apply(Type("Fun", x_t, body_t))

    elif tag == "app":
        f, a = term[1], term[2]
        f_t = infer(f, env)
        a_t = infer(a, env)
        r_t = fresh_var()
        unify(f_t, Type("Fun", a_t, r_t))
        return apply(r_t)

    elif tag == "if":
        c, t, e = term[1], term[2], term[3]
        unify(infer(c, env), TBool)
        t_t = infer(t, env)
        e_t = infer(e, env)
        unify(t_t, e_t)
        return apply(t_t)

    elif tag == "tuple":
        es = term[1:]
        ts = [infer(e, env) for e in es]
        return apply(Type("Tuple", tuple(ts)))

    elif tag == "proj":
        i, n, e = term[1], term[2], term[3]
        e_t = infer(e, env)
        tuple_t = Type("Tuple", tuple(fresh_var() for _ in range(n)))
        unify(e_t, tuple_t)
        return apply(tuple_t.args[0][i])

    elif tag == "let":
        x, e1, e2 = term[1], term[2], term[3]
        e1_t = infer(e1, env)
        e1_t = apply(e1_t)
        fv = free_vars(e1_t) - free_env(env)
        e1_gen = generalize(e1_t, fv)
        return infer(e2, env + [{x: e1_gen}])

    elif tag == "letrec":
        group, body = term[1], term[2]
        names = [item[0] for item in group]
        monos = {name: fresh_var() for name in names}
        env2 = env + [monos]
        expr_ts = [apply(infer(expr, env2)) for _, expr in group]
        for name, t in zip(names, expr_ts):
            unify(monos[name], t)
        outer_fvs = free_env(env)
        gen_ts = []
        for t in expr_ts:
            fv = free_vars(t) - outer_fvs
            gen_ts.append(generalize(t, fv))
        env3 = env + [{name: t for name, t in zip(names, gen_ts)}]
        return infer(body, env3)

    else:
        raise ValueError("Malformed: unknown tag")

def var_name(idx):
    res = []
    while idx >= 0:
        res.append(chr(ord('a') + idx % 26))
        idx = idx // 26 - 1
    return ''.join(reversed(res))

def to_str(t, var_map):
    if t.tag == "Int": return "Int"
    if t.tag == "Bool": return "Bool"
    if t.tag == "Var": return var_map[t.args[0]]
    if t.tag == "Fun": return f"(-> {to_str(t.args[0], var_map)} {to_str(t.args[1], var_map)})"
    if t.tag == "List": return f"(List {to_str(t.args[0], var_map)})"
    if t.tag == "Tuple":
        if not t.args: return "(Tuple)"
        return f"(Tuple {' '.join(to_str(e, var_map) for e in t.args)})"
    return "?"

def group_type(term):
    global _var_counter
    _var_counter = 0
    _subst.clear()

    validate_term(term)

    a1 = fresh_var()
    a2 = fresh_var()
    a3 = fresh_var()
    a4 = fresh_var()
    a5 = fresh_var()
    a6 = fresh_var()
    a7 = fresh_var()

    eq_t = Type("Fun", a1, Type("Fun", a1, TBool))
    eq_gen = generalize(eq_t, free_vars(eq_t))

    nil_t = Type("List", a2)
    nil_gen = generalize(nil_t, free_vars(nil_t))

    cons_t = Type("Fun", a3, Type("Fun", Type("List", a3), Type("List", a3)))
    cons_gen = generalize(cons_t, free_vars(cons_t))

    head_t = Type("Fun", Type("List", a4), a4)
    head_gen = generalize(head_t, free_vars(head_t))

    tail_t = Type("Fun", Type("List", a5), Type("List", a5))
    tail_gen = generalize(tail_t, free_vars(tail_t))

    isnil_t = Type("Fun", Type("List", a6), TBool)
    isnil_gen = generalize(isnil_t, free_vars(isnil_t))

    add_t = Type("Fun", TInt, Type("Fun", TInt, TInt))
    add_gen = generalize(add_t, free_vars(add_t))

    init_env = [{
        "add": add_gen,
        "eq": eq_gen,
        "nil": nil_gen,
        "cons": cons_gen,
        "head": head_gen,
        "tail": tail_gen,
        "isnil": isnil_gen
    }]

    res_t = infer(term, init_env)
    res_t = apply(res_t)

    all_vars = free_vars(res_t)
    sorted_vars = sorted(all_vars, key=lambda v: v.args[0])
    var_map = {v.args[0]: var_name(i) for i, v in enumerate(sorted_vars)}

    return to_str(res_t, var_map)

import itertools

def group_type(term):
    class TVar:
        __slots__ = ('id',)
        def __init__(self, id): self.id = id
    class TInt: pass
    class TBool: pass
    class TFun:
        __slots__ = ('a', 'b')
        def __init__(self, a, b): self.a = a; self.b = b
    class TList:
        __slots__ = ('a',)
        def __init__(self, a): self.a = a
    class TTuple:
        __slots__ = ('ts',)
        def __init__(self, ts): self.ts = ts

    var_counter = itertools.count(1)
    def fresh_var(): return TVar(next(var_counter))

    def eq_types(t1, t2):
        if type(t1) is not type(t2): return False
        if isinstance(t1, TVar): return t1.id == t2.id
        if isinstance(t1, (TInt, TBool)): return True
        if isinstance(t1, TFun): return eq_types(t1.a, t2.a) and eq_types(t1.b, t2.b)
        if isinstance(t1, TList): return eq_types(t1.a, t2.a)
        if isinstance(t1, TTuple):
            if len(t1.ts) != len(t2.ts): return False
            return all(eq_types(a, b) for a, b in zip(t1.ts, t2.ts))
        return False

    def apply(subst, t):
        if isinstance(t, TVar):
            res = subst.get(t)
            return apply(subst, res) if res is not None else t
        if isinstance(t, TFun): return TFun(apply(subst, t.a), apply(subst, t.b))
        if isinstance(t, TList): return TList(apply(subst, t.a))
        if isinstance(t, TTuple): return TTuple([apply(subst, x) for x in t.ts])
        return t

    def occurs(var, t):
        if isinstance(t, TVar): return t.id == var.id
        if isinstance(t, TFun): return occurs(var, t.a) or occurs(var, t.b)
        if isinstance(t, TList): return occurs(var, t.a)
        if isinstance(t, TTuple): return any(occurs(var, x) for x in t.ts)
        return False

    def bind(var, t, subst):
        t = apply(subst, t)
        if isinstance(t, TVar) and t.id == var.id: return subst
        if occurs(var, t): raise ValueError("Infinite type")
        new_subst = {var: t}
        for k, v in subst.items():
            new_subst[k] = apply(new_subst, v)
        return new_subst

    def unify(t1, t2, subst=None):
        if subst is None: subst = {}
        t1 = apply(subst, t1)
        t2 = apply(subst, t2)
        if eq_types(t1, t2): return subst
        if isinstance(t1, TVar): return bind(t1, t2, subst)
        if isinstance(t2, TVar): return bind(t2, t1, subst)
        if isinstance(t1, TFun) and isinstance(t2, TFun):
            return unify(t1.b, t2.b, unify(t1.a, t2.a, subst))
        if isinstance(t1, TList) and isinstance(t2, TList):
            return unify(t1.a, t2.a, subst)
        if isinstance(t1, TTuple) and isinstance(t2, TTuple):
            if len(t1.ts) != len(t2.ts): raise ValueError("Tuple length mismatch")
            for a, b in zip(t1.ts, t2.ts):
                subst = unify(a, b, subst)
            return subst
        raise ValueError("Type mismatch")

    def free_vars(t):
        fs = set()
        def collect(t):
            if isinstance(t, TVar): fs.add(t)
            elif isinstance(t, TFun): collect(t.a); collect(t.b)
            elif isinstance(t, TList): collect(t.a)
            elif isinstance(t, TTuple):
                for x in t.ts: collect(x)
        collect(t)
        return fs

    def free_env(env):
        fs = set()
        for scope in env:
            for t in scope.values():
                fs |= free_vars(t)
        return fs

    def instantiate(t):
        subst = {v: fresh_var() for v in free_vars(t)}
        return apply(subst, t)

    def generalize(t, env):
        fv = free_vars(t) - free_env(env)
        subst = {v: fresh_var() for v in fv}
        return apply(subst, t)

    def make_prim(name):
        if name == 'add': return TFun(TInt, TFun(TInt, TInt))
        if name == 'eq':
            a = fresh_var()
            return TFun(a, TFun(a, TBool))
        if name == 'nil':
            a = fresh_var()
            return TList(a)
        if name == 'cons':
            a = fresh_var()
            return TFun(a, TFun(TList(a), TList(a)))
        if name == 'head':
            a = fresh_var()
            return TFun(TList(a), a)
        if name == 'tail':
            a = fresh_var()
            return TFun(TList(a), TList(a))
        if name == 'isnil':
            a = fresh_var()
            return TFun(TList(a), TBool)
        raise ValueError(f"Unknown primitive: {name}")

    INIT_ENV = [ {name: make_prim(name) for name in ['add', 'eq', 'nil', 'cons', 'head', 'tail', 'isnil']} ]

    def infer(term, env):
        if isinstance(term, bool): raise ValueError("Bool is not Int")
        if isinstance(term, int): return TInt
        if term in (True, False): return TBool
        if isinstance(term, str):
            if not term: raise ValueError("Empty string variable")
            for scope in env:
                if term in scope:
                    return instantiate(scope[term])
            raise ValueError(f"Unbound variable: {term}")
        if not isinstance(term, tuple) or len(term) == 0:
            raise ValueError("Malformed term")
        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Malformed tag")

        if tag == 'lam':
            if len(term) != 3: raise ValueError
            x, body = term[1], term[2]
            if not isinstance(x, str) or not x: raise ValueError
            x_t = fresh_var()
            new_env = env + [{x: x_t}]
            body_t = infer(body, new_env)
            return TFun(x_t, body_t)

        elif tag == 'app':
            if len(term) != 3: raise ValueError
            f, a = term[1], term[2]
            f_t = infer(f, env)
            a_t = infer(a, env)
            r_t = fresh_var()
            unify(f_t, TFun(a_t, r_t))
            return r_t

        elif tag == 'if':
            if len(term) != 4: raise ValueError
            c, t, e = term[1], term[2], term[3]
            c_t = infer(c, env)
            unify(c_t, TBool)
            t_t = infer(t, env)
            e_t = infer(e, env)
            unify(t_t, e_t)
            return t_t

        elif tag == 'let':
            if len(term) != 4: raise ValueError
            x, e1, e2 = term[1], term[2], term[3]
            if not isinstance(x, str) or not x: raise ValueError
            e1_t = infer(e1, env)
            e1_t_gen = generalize(e1_t, env)
            new_env = env + [{x: e1_t_gen}]
            return infer(e2, new_env)

        elif tag == 'letrec':
            if len(term) != 3: raise ValueError
            group, body = term[1], term[2]
            if not isinstance(group, tuple) or len(group) == 0: raise ValueError
            names = [g[0] for g in group]
            if len(names) != len(set(names)): raise ValueError("Duplicate names in letrec")
            for name, expr in group:
                if not isinstance(name, str) or not name: raise ValueError
            mono_env = env + [dict(zip(names, [fresh_var() for _ in names]))]
            group_types = []
            for name, expr in group:
                t = infer(expr, mono_env)
                group_types.append(t)
            for name, t in zip(names, group_types):
                unify(mono_env[-1][name], t)
            rec_env = env + [dict(zip(names, [generalize(t, env) for t in group_types]))]
            return infer(body, rec_env)

        elif tag == 'tuple':
            es = term[1:]
            if len(es) == 1: raise ValueError("Tuple with n=1 is malformed")
            ts = [infer(e, env) for e in es]
            return TTuple(ts)

        elif tag == 'proj':
            if len(term) != 4: raise ValueError
            i, n, e = term[1], term[2], term[3]
            if isinstance(i, bool) or isinstance(n, bool): raise ValueError
            if not isinstance(i, int) or not isinstance(n, int): raise ValueError
            if n < 2: raise ValueError
            if not (0 <= i < n): raise ValueError
            e_t = infer(e, env)
            if not isinstance(e_t, TTuple): raise ValueError
            if len(e_t.ts) != n: raise ValueError
            return e_t.ts[i]

        else:
            raise ValueError(f"Unknown tag: {tag}")

    final_t = infer(term, INIT_ENV)

    # Collect vars in order of first appearance
    collected = []
    def collect_order(t):
        if isinstance(t, TVar):
            if t not in collected: collected.append(t)
        elif isinstance(t, TFun): collect_order(t.a); collect_order(t.b)
        elif isinstance(t, TList): collect_order(t.a)
        elif isinstance(t, TTuple):
            for x in t.ts: collect_order(x)
    collect_order(final_t)

    # Map to names a, b, ...
    def to_name(idx):
        s = ''
        idx += 1
        while idx > 0:
            idx, r = divmod(idx - 1, 26)
            s = chr(ord('a') + r) + s
        return s

    var_map = {v: to_name(i) for i, v in enumerate(collected)}

    def type_to_string(t):
        if isinstance(t, TInt): return "Int"
        if isinstance(t, TBool): return "Bool"
        if isinstance(t, TVar): return var_map[t]
        if isinstance(t, TFun): return f"(-> {type_to_string(t.a)} {type_to_string(t.b)})"
        if isinstance(t, TList): return f"(List {type_to_string(t.a)})"
        if isinstance(t, TTuple):
            if len(t.ts) == 0: return "(Tuple)"
            parts = " ".join(type_to_string(x) for x in t.ts)
            return f"(Tuple {parts})"

    return type_to_string(final_t)

import copy

# --- Type Definitions ---

class TypeVar:
    def __init__(self, id):
        self.id = id
    def __eq__(self, other):
        return isinstance(other, TypeVar) and self.id == other.id
    def __hash__(self):
        return hash(self.id)
    def __repr__(self):
        return f"TVar({self.id})"

class TBool:
    def __eq__(self, other): return isinstance(other, TBool)
    def __hash__(self): return hash('Bool')
    def __repr__(self): return 'Bool'

class TInt:
    def __eq__(self, other): return isinstance(other, TInt)
    def __hash__(self): return hash('Int')
    def __repr__(self): return 'Int'

class TFun:
    def __init__(self, arg, res):
        self.arg = arg
        self.res = res
    def __eq__(self, other):
        return isinstance(other, TFun) and self.arg == other.arg and self.res == other.res
    def __hash__(self):
        return hash((self.arg, self.res))

class TList:
    def __init__(self, item):
        self.item = item
    def __eq__(self, other):
        return isinstance(other, TList) and self.item == other.item
    def __hash__(self):
        return hash(('List', self.item))

class TTuple:
    def __init__(self, items):
        self.items = tuple(items)
    def __eq__(self, other):
        return isinstance(other, TTuple) and self.items == other.items
    def __hash__(self):
        return hash(('Tuple', self.items))

class Scheme:
    def __init__(self, type_, quantified_vars):
        self.type = type_
        self.quantified_vars = quantified_vars # Set of TypeVar objects

    def instantiate(self):
        mapping = {}
        for var in self.quantified_vars:
            mapping[var] = TypeVar(get_fresh_id())

        def replace(t):
            if isinstance(t, TypeVar):
                return mapping.get(t, t)
            if isinstance(t, TFun):
                return TFun(replace(t.arg), replace(t.res))
            if isinstance(t, TList):
                return TList(replace(t.item))
            if isinstance(t, TTuple):
                return TTuple([replace(x) for x in t.items])
            return t

        return replace(self.type)

# --- Substitution & Unification ---

def apply_sub(sub, t):
    if isinstance(t, TypeVar):
        return sub.get(t, t)
    if isinstance(t, TFun):
        return TFun(apply_sub(sub, t.arg), apply_sub(sub, t.res))
    if isinstance(t, TList):
        return TList(apply_sub(sub, t.item))
    if isinstance(t, TTuple):
        return TTuple([apply_sub(sub, x) for x in t.items])
    return t

def unify(t1, t2):
    # Returns a substitution dict
    sub = {}
    stack = [(t1, t2)]

    while stack:
        u, v = stack.pop()
        u = apply_sub(sub, u)
        v = apply_sub(sub, v)

        if u == v:
            continue

        if isinstance(u, TypeVar):
            if u in v: # Occurs check
                raise ValueError("Infinite type")
            if u in sub:
                stack.append((sub[u], v))
            else:
                sub[u] = v
                # Apply new binding to remaining stack
                # We iterate stack and apply sub? 
                # Actually, standard algo applies sub to u and v at start of loop.
                # But if we add to sub, we should process it.
                # The loop continues, next iteration will apply sub.
                # But we need to ensure u in sub is handled.
                # We can just continue, next pop will handle it.
                # However, if u is in sub, we pushed (sub[u], v).
                # If v is a TypeVar, we might need to push it back?
                # Let's rely on the fact that we apply sub at start.
                pass
        elif isinstance(v, TypeVar):
            if v in u: # Occurs check
                raise ValueError("Infinite type")
            if v in sub:
                stack.append((u, sub[v]))
            else:
                sub[v] = u
        elif isinstance(u, TFun) and isinstance(v, TFun):
            stack.append((u.arg, v.arg))
            stack.append((u.res, v.res))
        elif isinstance(u, TList) and isinstance(v, TList):
            stack.append((u.item, v.item))
        elif isinstance(u, TTuple) and isinstance(v, TTuple):
            if len(u.items) != len(v.items):
                raise ValueError("Tuple size mismatch")
            for a, b in zip(u.items, v.items):
                stack.append((a, b))
        else:
            raise ValueError("Type mismatch")

    return sub

# --- Free Vars ---

def free_vars_of_type(t):
    if isinstance(t, TypeVar):
        return {t}
    if isinstance(t, TFun):
        return free_vars_of_type(t.arg) | free_vars_of_type(t.res)
    if isinstance(t, TList):
        return free_vars_of_type(t.item)
    if isinstance(t, TTuple):
        res = set()
        for item in t.items:
            res |= free_vars_of_type(item)
        return res
    return set()

def free_vars_of_scheme(scheme):
    return free_vars_of_type(scheme.type) - scheme.quantified_vars

def free_vars_of_env(env):
    res = set()
    for scope in env:
        for name, val in scope.items():
            if isinstance(val, Scheme):
                res |= free_vars_of_scheme(val)
            else:
                res |= free_vars_of_type(val)
    return res

# --- Global State ---

_fresh_counter = 0

def get_fresh_id():
    global _fresh_counter
    _fresh_counter += 1
    return _fresh_counter

def reset_fresh():
    global _fresh_counter
    _fresh_counter = 0

# --- Environment ---

def build_initial_env():
    env = [{}]

    eq_a = TypeVar(get_fresh_id())
    env["eq"] = Scheme(TFun(eq_a, TFun(eq_a, TBool)), {eq_a})

    nil_a = TypeVar(get_fresh_id())
    env["nil"] = Scheme(TList(nil_a), {nil_a})

    cons_a = TypeVar(get_fresh_id())
    env["cons"] = Scheme(TFun(cons_a, TFun(TList(cons_a), TList(cons_a))), {cons_a})

    head_a = TypeVar(get_fresh_id())
    env["head"] = Scheme(TFun(TList(head_a), head_a), {head_a})

    tail_a = TypeVar(get_fresh_id())
    env["tail"] = Scheme(TFun(TList(tail_a), TList(tail_a)), {tail_a})

    isnil_a = TypeVar(get_fresh_id())
    env["isnil"] = Scheme(TFun(TList(isnil_a), TBool), {isnil_a})

    env["add"] = Scheme(TFun(TInt, TFun(TInt, TInt)), set())

    return env

# --- Term Validation ---

def validate_term(term):
    if isinstance(term, int):
        if isinstance(term, bool):
            raise ValueError("Bool is not Int")
        return

    if isinstance(term, bool):
        return

    if isinstance(term, str):
        if not term:
            raise ValueError("Empty string")
        return

    if isinstance(term, tuple):
        if not term:
            raise ValueError("Empty tuple")

        tag = term[0]
        if not isinstance(tag, str):
            raise ValueError("Non-str tag")

        if tag == "lam":
            if len(term) != 3: raise ValueError("Lam arity")
            x, body = term[1], term[2]
            if not isinstance(x, str) or not x: raise ValueError("Lam var")
            validate_term(body)

        elif tag == "app":
            if len(term) != 3: raise ValueError("App arity")
            validate_term(term[1])
            validate_term(term[2])

        elif tag == "if":
            if len(term) != 4: raise ValueError("If arity")
            validate_term(term[1])
            validate_term(term[2])
            validate_term(term[3])

        elif tag == "let":
            if len(term) != 4: raise ValueError("Let arity")
            x = term[1]
            if not isinstance(x, str) or not x: raise ValueError("Let var")
            validate_term(term[2])
            validate_term(term[3])

        elif tag == "letrec":
            if len(term) != 3: raise ValueError("Letrec arity")
            group = term[1]
            body = term[2]
            if not isinstance(group, tuple) or not group:
                raise ValueError("Letrec group")
            names = set()
            for pair in group:
                if not isinstance(pair, tuple) or len(pair) != 2:
                    raise ValueError("Letrec pair")
                name, expr = pair
                if not isinstance(name, str) or not name:
                    raise ValueError("Letrec name")
                if name in names:
                    raise ValueError("Duplicate name in letrec")
                names.add(name)
                validate_term(expr)
            validate_term(body)

        elif tag == "tuple":
            if len(term) == 2:
                raise ValueError("Tuple n=1")
            for item in term[1:]:
                validate_term(item)

        elif tag == "proj":
            if len(term) != 4: raise ValueError("Proj arity")
            i, n = term[1], term[2]
            if not isinstance(i, int) or isinstance(i, bool):
                raise ValueError("Proj i")
            if not isinstance(n, int) or isinstance(n, bool):
                raise ValueError("Proj n")
            if n < 2: raise ValueError("Proj n<2")
            if i < 0 or i >= n: raise ValueError("Proj i out of bounds")
            validate_term(term[3])

        else:
            raise ValueError(f"Unknown tag {tag}")
    else:
        raise ValueError("Malformed term")

# --- Inference ---

def lookup(name, env):
    for scope in reversed(env):
        if name in scope:
            val = scope[name]
            if isinstance(val, Scheme):
                return val.instantiate()
            return val
    raise ValueError(f"Unbound variable: {name}")

def generalize_type(t, env):
    env_fv = free_vars_of_env(env)
    target_fv = free_vars_of_type(t)
    quantified = target_fv - env_fv

    if not quantified:
        return Scheme(t, set())

    mapping = {}
    for var in quantified:
        mapping[var] = TypeVar(get_fresh_id())

    def replace(t):
        if isinstance(t, TypeVar):
            return mapping.get(t, t)
        if isinstance(t, TFun):
            return TFun(replace(t.arg), replace(t.res))
        if isinstance(t, TList):
            return TList(replace(t.item))
        if isinstance(t, TTuple):
            return TTuple([replace(x) for x in t.items])
        return t

    return Scheme(replace(t), quantified)

def infer(term, env):
    if isinstance(term, int):
        return TInt

    if isinstance(term, bool):
        return TBool

    if isinstance(term, str):
        return lookup(term, env)

    if isinstance(term, tuple):
        tag = term[0]

        if tag == "lam":
            x = term[1]
            body = term[2]
            param_t = TypeVar(get_fresh_id())
            new_env = env + [{x: param_t}]
            body_t = infer(body, new_env)
            return TFun(param_t, body_t)

        elif tag == "app":
            f = term[1]
            a = term[2]
            f_t = infer(f, env)
            a_t = infer(a, env)
            res_t = TypeVar(get_fresh_id())
            sub = unify(f_t, TFun(a_t, res_t))
            return apply_sub(sub, res_t)

        elif tag == "if":
            cond = term[1]
            then_b = term[2]
            else_b = term[3]

            cond_t = infer(cond, env)
            unify(cond_t, TBool)

            then_t = infer(then_b, env)
            else_t = infer(else_b, env)

            unify(then_t, else_t)
            return then_t

        elif tag == "let":
            x = term[1]
            e1 = term[2]
            e2 = term[3]

            e1_t = infer(e1, env)
            scheme = generalize_type(e1_t, env)
            new_env = env + [{x: scheme}]
            return infer(e2, new_env)

        elif tag == "letrec":
            group = term[1]
            body = term[2]

            # Create fresh monomorphic vars for names
            vars_map = {}
            new_env_group = env + [{}]
            for name, expr in group:
                tv = TypeVar(get_fresh_id())
                vars_map[name] = tv
                new_env_group[-1][name] = tv

            # Infer bodies with monomorphic vars
            inferred_types = {}
            for name, expr in group:
                t = infer(expr, new_env_group)
                inferred_types[name] = t
                # Unify monomorphic var with inferred type
                unify(vars_map[name], t)

            # Generalize each name w.r.t outer env (env)
            final_env = env
            for name, expr in group:
                t = inferred_types[name]
                scheme = generalize_type(t, env)
                final_env = final_env + [{name: scheme}]

            return infer(body, final_env)

        elif tag == "tuple":
            items = term[1:]
            if len(items) == 0:
                return TTuple([])
            types = [infer(item, env) for item in items]
            return TTuple(types)

        elif tag == "proj":
            i = term[1]
            n = term[2]
            e = term[3]

            e_t = infer(e, env)
            if not isinstance(e_t, TTuple):
                raise ValueError("Proj on non-tuple")
            if len(e_t.items) != n:
                raise ValueError("Proj tuple size mismatch")
            return e_t.items[i]

    raise ValueError("Unknown term")

# --- Output Formatting ---

def type_to_str(t, var_map):
    if isinstance(t, TypeVar):
        return var_map[t.id]
    if isinstance(t, TBool):
        return "Bool"
    if isinstance(t, TInt):
        return "Int"
    if isinstance(t, TFun):
        return f"({type_to_str(t.arg, var_map)} -> {type_to_str(t.res, var_map)})"
    if isinstance(t, TList):
        return f"(List {type_to_str(t.item, var_map)})"
    if isinstance(t, TTuple):
        if len(t.items) == 0:
            return "(Tuple)"
        items_str = " ".join(type_to_str(item, var_map) for item in t.items)
        return f"(Tuple {items_str})"
    return "?"

def collect_vars(t):
    if isinstance(t, TypeVar):
        return {t}
    if isinstance(t, TFun):
        return collect_vars(t.arg) | collect_vars(t.res)
    if isinstance(t, TList):
        return collect_vars(t.item)
    if isinstance(t, TTuple):
        res = set()
        for item in t.items:
            res |= collect_vars(item)
        return res
    return set()

def group_type(term):
    validate_term(term)
    reset_fresh()
    env = build_initial_env()

    result_t = infer(term, env)

    # Apply final substitution to simplify
    # The unify function accumulates substitutions, but we didn't return them.
    # However, the types constructed during inference are already unified.
    # We just need to collect vars and map them.

    vars_set = collect_vars(result_t)
    # Sort by ID
    sorted_vars = sorted(vars_set, key=lambda v: v.id)

    # Map IDs to names
    var_map = {}
    for i, var in enumerate(sorted_vars):
        # Generate name
        idx = i
        name = ""
        while idx >= 0:
            name = chr(ord('a') + (idx % 26)) + name
            idx = idx // 26 - 1
        var_map[var.id] = name

    return type_to_str(result_t, var_map)

import sys

# Type ADT
class Type: pass
class TInt(Type): pass
class TBool(Type): pass
class TVar(Type):
    def __init__(self, id): self.id = id
    def __eq__(self, other): return isinstance(other, TVar) and self.id == other.id
    def __hash__(self): return hash(self.id)
class TFun(Type):
    def __init__(self, arg, res): self.arg = arg; self.res = res
class TList(Type):
    def __init__(self, elem): self.elem = elem
class TTuple(Type):
    def __init__(self, elems): self.elems = elems

# Global state
var_counter = 0
def fresh_var():
    global var_counter
    tv = TVar(var_counter)
    var_counter += 1
    return tv

# Unification
def unify(t1, t2, sub):
    t1 = apply(sub, t1)
    t2 = apply(sub, t2)
    if isinstance(t1, TVar):
        if isinstance(t2, TVar):
            if t1.id == t2.id: return sub
            sub[t1] = t2
            return sub
        if occurs(t1, t2): raise ValueError("Infinite type")
        sub[t1] = t2
        return sub
    if isinstance(t2, TVar):
        if occurs(t2, t1): raise ValueError("Infinite type")
        sub[t2] = t1
        return sub
    if isinstance(t1, TFun) and isinstance(t2, TFun):
        sub = unify(t1.arg, t2.arg, sub)
        return unify(t1.res, t2.res, sub)
    if isinstance(t1, TList) and isinstance(t2, TList):
        return unify(t1.elem, t2.elem, sub)
    if isinstance(t1, TTuple) and isinstance(t2, TTuple):
        if len(t1.elems) != len(t2.elems): raise ValueError("Tuple length mismatch")
        for e1, e2 in zip(t1.elems, t2.elems):
            sub = unify(e1, e2, sub)
        return sub
    if isinstance(t1, TInt) and isinstance(t2, TInt): return sub
    if isinstance(t1, TBool) and isinstance(t2, TBool): return sub
    raise ValueError("Type mismatch")

def occurs(v, t):
    if isinstance(t, TVar): return t.id == v.id
    if isinstance(t, TFun): return occurs(v, t.arg) or occurs(v, t.res)
    if isinstance(t, TList): return occurs(v, t.elem)
    if isinstance(t, TTuple): return any(occurs(v, e) for e in t.elems)
    return False

def apply(sub, t):
    if isinstance(t, TVar):
        return sub.get(t, t)
    if isinstance(t, TFun):
        return TFun(apply(sub, t.arg), apply(sub, t.res))
    if isinstance(t, TList):
        return TList(apply(sub, t.elem))
    if isinstance(t, TTuple):
        return TTuple([apply(sub, e) for e in t.elems])
    return t

def free_vars(t):
    if isinstance(t, TVar): return {t.id}
    if isinstance(t, TFun): return free_vars(t.arg) | free_vars(t.res)
    if isinstance(t, TList): return free_vars(t.elem)
    if isinstance(t, TTuple):
        fvs = set()
        for e in t.elems: fvs |= free_vars(e)
        return fvs
    return set()

def env_free_vars(env):
    fvs = set()
    for d in env:
        for t in d.values():
            fvs |= free_vars(t)
    return fvs

def generalize(t, env):
    fvs = free_vars(t)
    env_fvs = env_free_vars(env)
    to_gen = fvs - env_fvs
    new_sub = {}
    for vid in to_gen:
        new_sub[TVar(vid)] = fresh_var()
    return apply(new_sub, t)

def lookup_env(env, name):
    for d in reversed(env):
        if name in d: return d[name]
    raise ValueError(f"Unbound variable: {name}")

def validate_term(term):
    if isinstance(term, bool):
        if term not in (True, False): raise ValueError
    elif isinstance(term, int):
        if isinstance(term, bool): raise ValueError
    elif isinstance(term, str):
        if not term: raise ValueError
    elif isinstance(term, tuple):
        if not term: raise ValueError
        tag = term[0]
        if not isinstance(tag, str): raise ValueError
        if tag == "lam":
            if len(term) != 3: raise ValueError
            x, body = term[1], term[2]
            if not isinstance(x, str) or not x: raise ValueError
            validate_term(body)
        elif tag == "app":
            if len(term) != 3: raise ValueError
            validate_term(term[1])
            validate_term(term[2])
        elif tag == "if":
            if len(term) != 4: raise ValueError
            validate_term(term[1])
            validate_term(term[2])
            validate_term(term[3])
        elif tag == "let":
            if len(term) != 4: raise ValueError
            x = term[1]
            if not isinstance(x, str) or not x: raise ValueError
            validate_term(term[2])
            validate_term(term[3])
        elif tag == "letrec":
            if len(term) != 3: raise ValueError
            group = term[1]
            if not isinstance(group, tuple) or not group: raise ValueError
            names = set()
            for pair in group:
                if not isinstance(pair, tuple) or len(pair) != 2: raise ValueError
                n, e = pair
                if not isinstance(n, str) or not n: raise ValueError
                if n in names: raise ValueError
                names.add(n)
                validate_term(e)
            validate_term(term[2])
        elif tag == "tuple":
            if len(term) == 2: raise ValueError # n=1
            for e in term[1:]:
                validate_term(e)
        elif tag == "proj":
            if len(term) != 4: raise ValueError
            i, n, e = term[1], term[2], term[3]
            if isinstance(i, bool) or not isinstance(i, int): raise ValueError
            if isinstance(n, bool) or not isinstance(n, int): raise ValueError
            if n < 2: raise ValueError
            if i < 0 or i >= n: raise ValueError
            validate_term(e)
        else:
            raise ValueError
    else:
        raise ValueError

def infer(term, env, sub):
    if isinstance(term, bool):
        return TBool, sub
    if isinstance(term, int):
        return TInt, sub
    if isinstance(term, str):
        return lookup_env(env, term), sub
    if isinstance(term, tuple):
        tag = term[0]
        if tag == "lam":
            x, body = term[1], term[2]
            tv = fresh_var()
            new_env = env + [{x: tv}]
            res, sub = infer(body, new_env, sub)
            return TFun(tv, res), sub
        elif tag == "app":
            f_t, sub = infer(term[1], env, sub)
            a_t, sub = infer(term[2], env, sub)
            res_tv = fresh_var()
            sub = unify(f_t, TFun(a_t, res_tv), sub)
            return res_tv, sub
        elif tag == "if":
            c_t, sub = infer(term[1], env, sub)
            sub = unify(c_t, TBool, sub)
            t_t, sub = infer(term[2], env, sub)
            e_t, sub = infer(term[3], env, sub)
            sub = unify(t_t, e_t, sub)
            return t_t, sub
        elif tag == "let":
            x, e1, e2 = term[1], term[2], term[3]
            t1, sub = infer(e1, env, sub)
            t1_gen = generalize(t1, env)
            new_env = env + [{x: t1_gen}]
            return infer(e2, new_env, sub)
        elif tag == "letrec":
            group, body = term[1], term[2]
            name_vars = {n: fresh_var() for n, _ in group}
            new_env = env + [name_vars]
            inferred_types = []
            for n, e in group:
                t, sub = infer(e, new_env, sub)
                inferred_types.append(t)
            for n, t in zip([name for name, _ in group], inferred_types):
                var = name_vars[n]
                sub = unify(var, t, sub)
            env_fvs = env_free_vars(env)
            generalized = []
            for n, t in zip([name for name, _ in group], inferred_types):
                t_gen = generalize(t, env)
                generalized.append(t_gen)
            final_env = env + [{n: t_gen for n, t_gen in zip([name for name, _ in group], generalized)}]
            return infer(body, final_env, sub)
        elif tag == "tuple":
            es = term[1:]
            ts = []
            for e in es:
                t, sub = infer(e, env, sub)
                ts.append(t)
            return TTuple(ts), sub
        elif tag == "proj":
            i, n, e = term[1], term[2], term[3]
            t, sub = infer(e, env, sub)
            target = TTuple([fresh_var() for _ in range(n)])
            sub = unify(t, target, sub)
            actual = apply(sub, target)
            return actual.elems[i], sub
        else:
            raise ValueError("Unknown tag")
    raise ValueError("Malformed term")

def to_string(t):
    if isinstance(t, TInt): return "Int"
    if isinstance(t, TBool): return "Bool"
    if isinstance(t, TVar): return f"v{t.id}"
    if isinstance(t, TFun): return f"(-> {to_string(t.arg)} {to_string(t.res)})"
    if isinstance(t, TList): return f"(List {to_string(t.elem)})"
    if isinstance(t, TTuple):
        if not t.elems: return "(Tuple)"
        return f"(Tuple {' '.join(to_string(e) for e in t.elems)})"

def collect_ids(t, order):
    if isinstance(t, TVar):
        if t.id not in order: order.append(t.id)
    elif isinstance(t, TFun):
        collect_ids(t.arg, order)
        collect_ids(t.res, order)
    elif isinstance(t, TList):
        collect_ids(t.elem, order)
    elif isinstance(t, TTuple):
        for e in t.elems:
            collect_ids(e, order)

def id_to_name(idx):
    name = ""
    idx += 1
    while idx > 0:
        idx -= 1
        name = chr(ord('a') + idx % 26) + name
        idx //= 26
    return name

def group_type(term):
    validate_term(term)
    INIT_ENV = [
        {
            "add": TFun(TInt, TFun(TInt, TInt)),
            "eq": TFun(TVar(0), TFun(TVar(0), TBool)),
            "nil": TList(TVar(1)),
            "cons": TFun(TVar(2), TFun(TList(TVar(2)), TList(TVar(2)))),
            "head": TFun(TList(TVar(3)), TVar(3)),
            "tail": TFun(TList(TVar(4)), TList(TVar(4))),
            "isnil": TFun(TList(TVar(5)), TBool)
        }
    ]
    res_type, _ = infer(term, INIT_ENV, {})
    order = []
    collect_ids(res_type, order)
    name_map = {vid: id_to_name(i) for i, vid in enumerate(order)}
    def rename(t):
        if isinstance(t, TVar):
            return name_map[t.id]
        if isinstance(t, TFun):
            return f"(-> {rename(t.arg)} {rename(t.res)})"
        if isinstance(t, TList):
            return f"(List {rename(t.elem)})"
        if isinstance(t, TTuple):
            if not t.elems: return "(Tuple)"
            return f"(Tuple {' '.join(rename(e) for e in t.elems)})"
        return ""
    return rename(res_type)

import sys
sys.setrecursionlimit(100000)

def branch_influence(n, edges, entry, exits, targets):
    # 1. Input Validation
    def check_int(val):
        return isinstance(val, int) and not isinstance(val, bool)

    if not check_int(n) or n < 1:
        raise ValueError("n must be an int >= 1 (bool is not an int); entry must be an int in 0..n-1; edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1; exits and targets must each be a list, tuple or set of ints in 0..n-1.")
    if not check_int(entry) or not (0 <= entry < n):
        raise ValueError("n must be an int >= 1 (bool is not an int); entry must be an int in 0..n-1; edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1; exits and targets must each be a list, tuple or set of ints in 0..n-1.")
    if not isinstance(edges, list):
        raise ValueError("n must be an int >= 1 (bool is not an int); entry must be an int in 0..n-1; edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1; exits and targets must each be a list, tuple or set of ints in 0..n-1.")
    for e in edges:
