            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    if not isinstance(targets, (list, tuple, set)):
        raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    for t in targets:
        if not isinstance(t, int) or isinstance(t, bool) or t < 0 or t >= n:
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    # 2. Forward Reachability (R)
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)

    R = set()
    queue = deque([entry])
    R.add(entry)
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in R:
                R.add(v)
                queue.append(v)

    if not R:
        return ([], sorted(targets))

    # 3. Backward Reachability to END (A)
    rev_adj = defaultdict(list)
    for u in R:
        for v in adj[u]:
            if v in R:
                rev_adj[v].append(u)

    A = set()
    queue = deque()
    exits_in_R = exits.intersection(R)
    for e in exits_in_R:
        if e not in A:
            A.add(e)
            queue.append(e)

    while queue:
        u = queue.popleft()
        for v in rev_adj[u]:
            if v not in A:
                A.add(v)
                queue.append(v)

    if not A:
        return ([], sorted(targets))

    # 4. Post-Dominator Tree Construction via Lengauer-Tarjan
    # Reversed graph with END as virtual root
    rev_A_adj = defaultdict(list)
    for u in A:
        for v in adj[u]:
            if v in A:
                rev_A_adj[v].append(u)

    END = n
    rev_A_adj[END] = list(exits_in_R)

    # Data structures for Lengauer-Tarjan
    parent = {END: None}
    tree_adj = defaultdict(list)
    bucket = defaultdict(list)
    ancestor = {END: None}
    val = {END: END}
    semi = {END: END}
    idom = {END: None}
    dsu = {END: END}
    visited = {END}

    # Iterative DFS to build tree and discovery order
    stack = [END]
    order = []
    while stack:
        u = stack[-1]
        pushed = False
        for v in rev_A_adj[u]:
            if v not in visited:
                visited.add(v)
                parent[v] = u
                tree_adj[u].append(v)
                val[v] = v
                semi[v] = v
                dsu[v] = v
                ancestor[v] = None
                stack.append(v)
                pushed = True
                break
        if not pushed:
            stack.pop()
            order.append(u)

    # eval and link for path compression
    def eval(u):
        if ancestor[u] is None:
            return u
        if eval(ancestor[u]) != ancestor[u]:
            ancestor[u] = eval(ancestor[u])
            if semi[val[u]] < semi[val[ancestor[u]]]:
                val[u] = val[ancestor[u]]
        return val[u]

    def link(v, u):
        parent[v] = u
        ancestor[v] = u
        dsu[v] = v

    # Compute semi-dominators
    for u in reversed(order):
        for v in rev_A_adj[u]:
            if v in visited:
                w = eval(v)
                if semi[val[w]] < semi[u]:
                    semi[u] = semi[val[w]]
                bucket[val[w]].append(u)
            else:
                link(v, u)

    # Compute immediate dominators
    for u in reversed(order):
        for w in bucket[u]:
            z = eval(w)
            if semi[z] == semi[w]:
                idom[w] = z
            else:
                idom[w] = -1
        bucket[u].clear()
        if u != END:
            u_parent = parent[u]
            if idom[u_parent] == -1:
                idom[u_parent] = idom[u]
            else:
                idom[u_parent] = u

    # Resolve -1 entries
    for u in order:
        if idom[u] == -1 and u != END:
            idom[u] = idom[idom[u]]

    # Build post-dominator tree parent array
    post_dom_parent = {END: None}
    for u in A:
        post_dom_parent[u] = idom[u]

    # 5. Control Dependencies & C Extraction
    # G_ctrl: y -> x means y is control dependent on x
    G_ctrl = defaultdict(set)

    # Precompute subtree sizes or use a simpler method
    # Since we need to find for each x, the lowest ancestor of each successor s that is not a strict descendant of x
    # We can use the post-dominator tree structure.

    # To avoid O(V^2), we can use the fact that control dependencies can be computed in O(E α(V))
    # But for simplicity and given constraints, we'll use a direct approach with path compression on the tree.

    # Actually, we can compute for each node y, the set of x that control it.
    # But that's large. Instead, we compute dependencies and then do BFS.

    # For each x in A, for each successor s in A:
    #   Find bd = lowest ancestor of s in post-dominator tree that is not a strict descendant of x.
    #   All ancestors of bd (including bd) are control dependent on x.

    # To speed up, we can mark nodes as processed for each x.
    # Given N=40k, this should be acceptable.

    for x in A:
        for s in adj[x]:
            if s not in A:
                continue
            # Find bd
            bd = s
            while bd is not None and bd != x and bd != END:
                # Check if bd is a strict descendant of x in post-dominator tree
                # We can walk up from bd to root and check if we hit x
                # But that's O(V). Instead, we can use the property:
                # bd is a strict descendant of x iff x is an ancestor of bd in post-dominator tree.
                # We can check this by walking up from bd until we hit an ancestor of x or root.
                # Actually, we can just walk up from bd and stop when we find a node that is not in x's subtree.
                # To do this efficiently, we can precompute entry/exit times for DFS order on post-dominator tree.
                pass
            # Simpler: walk up from s until we find a node that is not a strict descendant of x.
            # A node y is a strict descendant of x iff x is an ancestor of y in post-dominator tree.
            # We can check this by walking up from y and seeing if we encounter x.
            # But that's O(depth).
            # Given constraints, let's use a visited set per x to avoid reprocessing.

            bd = s
            while bd is not None and bd != x and bd != END:
                # Check if bd is a strict descendant of x
                is_desc = False
                curr = bd
                while curr is not None and curr != x and curr != END:
                    curr = post_dom_parent[curr]
                if curr == x:
                    is_desc = True
                if not is_desc:
                    break
                bd = post_dom_parent[bd]

            # Now bd is the lowest ancestor of s not a strict descendant of x (or x itself, or END)
            # All ancestors of bd (including bd) are control dependent on x
            curr = bd
            while curr is not None:
                if curr != x:
                    G_ctrl[curr].add(x)
                curr = post_dom_parent[curr]

    # Compute C: smallest set such that every node x on which some node of T ∪ C is control dependent belongs to C
    T = targets.intersection(A)
    C = set()
    queue = deque(T)
    C.update(T)

    while queue:
        y = queue.popleft()
        for x in G_ctrl[y]:
            if x not in C:
                C.add(x)
                queue.append(x)

    # Output
    sorted_C = sorted(C)
    targets_outside_A = sorted(targets.difference(A))

    return (sorted_C, targets_outside_A)

