def branch_influence(n, edges, entry, exits, targets):
    # 1. Input Validation
    if not isinstance(n, int) or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1 (bool is not an int)")
    if not isinstance(entry, int) or isinstance(entry, bool) or entry < 0 or entry >= n:
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
        if not isinstance(e[0], int) or isinstance(e[0], bool) or e[0] < 0 or e[0] >= n:
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
        if not isinstance(e[1], int) or isinstance(e[1], bool) or e[1] < 0 or e[1] >= n:
            raise ValueError("edges must be a list of pairs (tuples or lists of length 2) of ints in 0..n-1")
    if not isinstance(exits, (list, tuple, set)):
        raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    for e in exits:
        if not isinstance(e, int) or isinstance(e, bool) or e < 0 or e >= n:
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    if not isinstance(targets, (list, tuple, set)):
        raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")
    for t in targets:
        if not isinstance(t, int) or isinstance(t, bool) or t < 0 or t >= n:
            raise ValueError("exits and targets must each be a list, tuple or set of ints in 0..n-1")

    # 2. Forward Reachability (R)
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)

    R = set()
    q = deque([entry])
    R.add(entry)
    while q:
        u = q.popleft()
        for v in adj[u]:
            if v not in R:
                R.add(v)
                q.append(v)

    if not R:
        return ([], sorted(targets))

    # 3. Backward Reachability to END (A)
    rev_adj = defaultdict(list)
    for u in R:
        for v in adj[u]:
            if v in R:
                rev_adj[v].append(u)

    A = set()
    q = deque()
    exits_in_R = set(exits) & R
    for e in exits_in_R:
        if e not in A:
            A.add(e)
            q.append(e)
    while q:
        u = q.popleft()
        for v in rev_adj[u]:
            if v not in A:
                A.add(v)
                q.append(v)

    if not A:
        return ([], sorted(targets))

    # 4. Post-Dominator Tree via Lengauer-Tarjan
    A_list = sorted(A)
    node_to_idx = {u: i for i, u in enumerate(A_list)}
    k = len(A_list)
    END = k

    # Build pred_rev: predecessors in rev_graph = successors in original
    pred_rev = [[] for _ in range(k + 1)]
    for u in A_list:
        idx = node_to_idx[u]
        for v in adj[u]:
            if v in node_to_idx:
                pred_rev[idx].append(node_to_idx[v])
    for e in exits_in_R:
        if e in node_to_idx:
            pred_rev[END].append(node_to_idx[e])

    # Children in rev_graph for DFS
    children_rev = [[] for _ in range(k + 1)]
    for u in range(k + 1):
        for v in pred_rev[u]:
            children_rev[v].append(u)

    num = [-1] * (k + 1)
    parent = [-1] * (k + 1)
    semi = [0] * (k + 1)
    idom = [-1] * (k + 1)
    ancestor = [-1] * (k + 1)
    val = [0] * (k + 1)
    bucket = [[] for _ in range(k + 1)]

    # Iterative DFS
    dfs_stack = [(END, iter(children_rev[END]))]
    num[END] = 0
    order = []
    counter = 1

    while dfs_stack:
        u, it = dfs_stack[-1]
        pushed = False
        for v in it:
            if num[v] == -1:
                num[v] = counter
                counter += 1
                parent[v] = u
                semi[v] = v
                val[v] = v
                ancestor[v] = -1
                dfs_stack.append((v, iter(children_rev[v])))
                pushed = True
                break
        if not pushed:
            order.append(u)
            dfs_stack.pop()

    def eval(u):
        if ancestor[u] == -1:
            return u
        if eval(ancestor[u]) != ancestor[u]:
            ancestor[u] = eval(ancestor[u])
            if num[semi[val[u]]] < num[semi[val[ancestor[u]]]]:
                val[u] = val[ancestor[u]]
        return val[u]

    def link(v, u):
        ancestor[v] = u

    sorted_nodes = sorted([u for u in range(k + 1) if u != END], key=lambda x: num[x], reverse=True)

    for u in sorted_nodes:
        for v in pred_rev[u]:
            if num[v] != -1:
                w = eval(v)
                if num[semi[val[w]]] < num[semi[u]]:
                    semi[u] = val[w]
                bucket[val[w]].append(u)
            else:
                link(v, u)

        for w in bucket[u]:
            v = eval(w)
            if num[semi[v]] == num[semi[w]]:
                idom[w] = v
            else:
                idom[w] = -1
        bucket[u] = []

        if u != END:
            p = parent[u]
            if p != END:
                if idom[p] == -1:
                    idom[p] = idom[u]
                else:
                    idom[p] = u

    idom[END] = END
    sorted_nodes_inc = sorted([u for u in range(k + 1) if u != END], key=lambda x: num[x])
    for u in sorted_nodes_inc:
        if idom[u] == -1:
            idom[u] = idom[idom[u]]

    post_dom_parent = {}
    for i, u in enumerate(A_list):
        post_dom_parent[u] = A_list[idom[i]]

    # 5. Control Dependencies
    # Precompute subtree entry/exit times for O(1) descendant checks
    pd_children = defaultdict(list)
    for u in A_list:
        p = post_dom_parent[u]
        if p is not None:
            pd_children[p].append(u)

    entry_time = {}
    exit_time = {}
    timer = 0
    stack = [END]
    # We only need times for nodes in A, but END is root.
    # Actually, we can just run DFS on pd_children starting from nodes that are roots in A's post-dom tree.
    # But easier: run DFS from END, record times for all nodes in A.
    dfs_stack = [(END, iter(pd_children[END]))]
    while dfs_stack:
        u, it = dfs_stack[-1]
        pushed = False
        for v in it:
            if v not in entry_time:
                entry_time[v] = timer
                timer += 1
                dfs_stack.append((v, iter(pd_children[v])))
                pushed = True
                break
        if not pushed:
            exit_time[u] = timer
            timer += 1
            dfs_stack.pop()

    def is_descendant(desc, anc):
        # desc is descendant of anc in post-dominator tree
        return entry_time.get(desc, -1) >= entry_time.get(anc, -1) and exit_time.get(desc, -1) <= exit_time.get(anc, -1)

    G_ctrl = defaultdict(set)
    for x in A_list:
        for s in adj[x]:
            if s not in A:
                continue
            # Find lowest ancestor of s not a strict descendant of x
            bd = s
            while bd is not None and bd != x and bd != END:
                if not is_descendant(bd, x):
                    break
                bd = post_dom_parent[bd]

            # Add control dependencies
            curr = bd
            while curr is not None:
                if curr != x:
                    G_ctrl[curr].add(x)
                curr = post_dom_parent[curr]

    # 6. Compute C
    T = set(targets) & A
    C = set()
    q = deque(T)
    C.update(T)

    while q:
        y = q.popleft()
        for x in G_ctrl[y]:
            if x not in C:
                C.add(x)
                q.append(x)

    return (sorted(C), sorted(set(targets) - A))

def live_phi_sites(n, edges, entry, blocks, params):
    # Input validation
    if type(n) is not int or isinstance(n, bool) or n < 1:
        raise ValueError("n must be an int >= 1")
    if type(entry) is not int or isinstance(entry, bool) or entry < 0 or entry >= n:
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges must be a list")
    for e in edges:
        if not (isinstance(e, (list, tuple)) and len(e) == 2):
            raise ValueError("edges must be a list of pairs")
        if not all(type(x) is int and not isinstance(x, bool) and 0 <= x < n for x in e):
            raise ValueError("edge components must be ints in 0..n-1")
    if not isinstance(blocks, dict):
        raise ValueError("blocks must be a dict")
    for k, v in blocks.items():
        if type(k) is not int or isinstance(k, bool) or k < 0 or k >= n:
            raise ValueError("blocks keys must be ints in 0..n-1")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values must be lists or tuples")
        for instr in v:
            if not (isinstance(instr, (list, tuple)) and len(instr) == 2):
                raise ValueError("instructions must be pairs")
            if instr[0] not in ("use", "def", "upd"):
                raise ValueError("invalid op")
            if not isinstance(instr[1], str) or not instr[1]:
                raise ValueError("name must be non-empty str")
    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a collection")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params must be non-empty str")

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    # BFS from entry to find reachable nodes
    reachable = [False] * n
    queue = [entry]
    reachable[entry] = True
    idx = 0
    while idx < len(queue):
        u = queue[idx]
        idx += 1
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                queue.append(v)

    reachable_nodes = [i for i, r in enumerate(reachable) if r]
    if not reachable_nodes:
        return []

    # Build forward/reverse adjacency for reachable subgraph
    succ = [[] for _ in range(n)]
    pred = [[] for _ in range(n)]
    for u in reachable_nodes:
        for v in adj[u]:
            if reachable[v]:
                succ[u].append(v)
                pred[v].append(u)

    # Lengauer-Tarjan dominator tree computation
    dfs_num = [-1] * n
    dfs_rev = [0] * n
    parent = [-1] * n
    num = 0

    stack = [entry]
    while stack:
        u = stack.pop()
        if dfs_num[u] == -1:
            dfs_num[u] = num
            dfs_rev[num] = u
            num += 1
            for v in succ[u]:
                if dfs_num[v] == -1:
                    parent[v] = u
                    stack.append(v)

    sem = [0] * n
    sdom = [0] * n
    idom = [0] * n
    ancestor = [0] * n
    bucket = [[] for _ in range(n)]

    for i in range(num):
        u = dfs_rev[i]
        sem[u] = u
        sdom[u] = u
        ancestor[u] = u
        idom[u] = u

    uf_parent = list(range(num))
    uf_rank = [0] * num

    def find(x):
        if uf_parent[x] != x:
            uf_parent[x] = find(uf_parent[x])
        return uf_parent[x]

    def link(x, y):
        if uf_rank[x] < uf_rank[y]:
            uf_parent[x] = y
        elif uf_rank[x] > uf_rank[y]:
            uf_parent[y] = x
        else:
            uf_parent[y] = x
            uf_rank[x] += 1

    def eval_v(v):
        w = find(v)
        if dfs_num[sem[w]] < dfs_num[sem[v]]:
            sem[v] = sem[w]
        return w

    def link_uv(v, w):
        link(v, w)
        ancestor[w] = v

    for i in range(num - 1, 0, -1):
        u = dfs_rev[i]
        for v in pred[u]:
            if dfs_num[v] != -1:
                w = eval_v(v)
                if sem[w] < sem[u]:
                    sem[u] = sem[w]
                bucket[sem[u]].append(u)

        if parent[u] != -1:
            link_uv(parent[u], u)

        for v in bucket[parent[u]]:
            w = eval_v(v)
            if sem[w] < sem[v]:
                idom[v] = w
            else:
                idom[v] = parent[u]
        bucket[parent[u]] = []

    for i in range(1, num):
        u = dfs_rev[i]
        if idom[u] != sem[u]:
            idom[u] = idom[idom[u]]

    # Compute dominance frontier
    df = [set() for _ in range(n)]
    for u in reachable_nodes:
        for v in succ[u]:
            w = u
            while w != v:
                df[v].add(w)
                w = idom[w]
                if w == -1 or w == v:
                    break
            if u == v:
                df[u].add(u)

    # Build frontier graph: frontier_graph[d] contains y where y in DF(d)
    frontier_graph = [[] for _ in range(n)]
    for u in reachable_nodes:
        for v in df[u]:
            frontier_graph[u].append(v)

    # Parse blocks for reachable nodes
    defs = {}
    uses_exposed = {}

    for u in reachable_nodes:
        if u in blocks:
            block = blocks[u]
            has_def = set()
            for op, name in block:
                if op in ("def", "upd"):
                    has_def.add(name)
                    if name not in defs:
                        defs[name] = set()
                    defs[name].add(u)
                elif op == "use":
                    if name not in has_def:
                        if name not in uses_exposed:
                            uses_exposed[name] = set()
                        uses_exposed[name].add(u)

    # Add entry to D(x) if x in params
    for x in params:
        if x not in defs:
            defs[x] = set()
        defs[x].add(entry)

    # Compute P(x) for each name
    P = {}
    for x in defs:
        start_nodes = defs[x]
        visited = set(start_nodes)
        queue = list(start_nodes)
        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            for v in frontier_graph[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)
        P[x] = visited

    # Compute liveness per name
    live_in = {}
    for x in defs:
        live_out = set()
        for u in uses_exposed.get(x, set()):
            live_out.add(u)

        worklist = list(live_out)
        idx = 0
        while idx < len(worklist):
            u = worklist[idx]
            idx += 1
            for p in pred[u]:
                if p not in reachable_nodes:
                    continue
                if x in defs and p in defs[x]:
                    continue
                if x not in live_out:
                    live_out.add(x)
                    worklist.append(p)
        live_in[x] = live_out

    # Phi decision: phi for x at y iff y in P(x) and x is live-in at y
    phi_nodes = {}
    for x in defs:
        for y in P[x]:
            if x in live_in[x]:
                if y not in phi_nodes:
                    phi_nodes[y] = set()
                phi_nodes[y].add(x)

    # Output assembly
    result = []
    for y in sorted(phi_nodes.keys()):
        names = sorted(phi_nodes[y])
        if names:
            result.append((y, names))

    return result

