    if not isinstance(blocks, dict):
        raise ValueError("blocks must be a dict")
    for k, v in blocks.items():
        if not (type(k) is int and not isinstance(k, bool) and 0 <= k < n):
            raise ValueError("blocks keys must be ints in 0..n-1")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values must be lists or tuples")
        for instr in v:
            if not (isinstance(instr, (list, tuple)) and len(instr) == 2):
                raise ValueError("instructions must be pairs")
            if instr[0] not in ("use", "def", "upd"):
                raise ValueError("invalid op")
            if not isinstance(instr[1], str) or not instr[1]:
                raise ValueError("name must be non-empty str")
    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a collection")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params must be non-empty str")

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    # BFS from entry to find reachable nodes
    reachable = [False] * n
    queue = [entry]
    reachable[entry] = True
    idx = 0
    while idx < len(queue):
        u = queue[idx]
        idx += 1
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                queue.append(v)

    reachable_nodes = [i for i, r in enumerate(reachable) if r]
    if not reachable_nodes:
        return []

    # Build forward/reverse adjacency for reachable subgraph
    succ = [[] for _ in range(n)]
    pred = [[] for _ in range(n)]
    for u in reachable_nodes:
        for v in adj[u]:
            if reachable[v]:
                succ[u].append(v)
                pred[v].append(u)

    # Lengauer-Tarjan dominator tree computation (iterative)
    dfs_num = [-1] * n
    dfs_rev = [0] * n
    parent = [-1] * n
    num = 0

    stack = [entry]
    while stack:
        u = stack.pop()
        if dfs_num[u] == -1:
            dfs_num[u] = num
            dfs_rev[num] = u
            num += 1
            for v in succ[u]:
                if dfs_num[v] == -1:
                    parent[v] = u
                    stack.append(v)

    sem = [0] * num
    sdom = [0] * num
    idom = [0] * num
    ancestor = [0] * num
    bucket = [[] for _ in range(num)]

    for i in range(num):
        u = dfs_rev[i]
        sem[u] = u
        sdom[u] = u
        ancestor[u] = u
        idom[u] = u

    uf_parent = list(range(num))
    uf_rank = [0] * num

    def find(x):
        root = x
        while uf_parent[root] != root:
            root = uf_parent[root]
        while uf_parent[x] != root:
            nxt = uf_parent[x]
            uf_parent[x] = root
            x = nxt
        return root

    def link(x, y):
        if uf_rank[x] < uf_rank[y]:
            uf_parent[x] = y
        elif uf_rank[x] > uf_rank[y]:
            uf_parent[y] = x
        else:
            uf_parent[y] = x
            uf_rank[x] += 1

    def eval_v(v):
        w = find(v)
        if dfs_num[sem[w]] < dfs_num[sem[v]]:
            sem[v] = sem[w]
        return w

    for i in range(num - 1, 0, -1):
        u = dfs_rev[i]
        for v in pred[u]:
            if dfs_num[v] != -1:
                w = eval_v(v)
                if sem[w] < sem[u]:
                    sem[u] = sem[w]
                bucket[sem[u]].append(u)

        if parent[u] != -1:
            link(parent[u], u)
            ancestor[parent[u]] = u

        for v in bucket[parent[u]]:
            w = eval_v(v)
            if sem[w] < sem[v]:
                idom[v] = w
            else:
                idom[v] = parent[u]
        bucket[parent[u]] = []

    for i in range(1, num):
        u = dfs_rev[i]
        if idom[u] != sem[u]:
            idom[u] = idom[idom[u]]

    # Map dominator tree indices back to node indices
    node_to_dfs = [-1] * n
    for i in range(num):
        node_to_dfs[dfs_rev[i]] = i

    # Compute dominance frontier
    df = [set() for _ in range(n)]
    for v in reachable_nodes:
        for p in pred[v]:
            w_dfs = node_to_dfs[p]
            v_dfs = node_to_dfs[v]
            # Walk up from p in dominator tree until we reach v
            while w_dfs != v_dfs:
                df[dfs_rev[w_dfs]].add(v)
                w_dfs = node_to_dfs[idom[dfs_rev[w_dfs]]]
                if w_dfs == -1:
                    break

    # Build frontier graph: frontier_graph[u] contains v where v in DF(u)
    frontier_graph = [[] for _ in range(n)]
    for u in reachable_nodes:
        for v in df[u]:
            frontier_graph[u].append(v)

    # Parse blocks for reachable nodes
    defs = {}
    uses_exposed = {}

    for u in reachable_nodes:
        if u in blocks:
            block = blocks[u]
            has_def = set()
            for op, name in block:
                if op in ("def", "upd"):
                    has_def.add(name)
                    if name not in defs:
                        defs[name] = set()
                    defs[name].add(u)
                elif op == "use":
                    if name not in has_def:
                        if name not in uses_exposed:
                            uses_exposed[name] = set()
                        uses_exposed[name].add(u)

    # Add entry to D(x) if x in params
    params_set = set(params)
    for x in params_set:
        if x not in defs:
            defs[x] = set()
        defs[x].add(entry)

    # Compute P(x) for each name using BFS on frontier graph
    P = {}
    for x in defs:
        start_nodes = defs[x]
        visited = set(start_nodes)
        worklist = list(start_nodes)
        idx = 0
        while idx < len(worklist):
            u = worklist[idx]
            idx += 1
            for v in frontier_graph[u]:
                if v not in visited:
                    visited.add(v)
                    worklist.append(v)
        P[x] = visited

    # Compute liveness per name via backward data flow
    live_in = {}
    for x in defs:
        live_out = set()
        for u in uses_exposed.get(x, set()):
            live_out.add(u)

        worklist = list(live_out)
        idx = 0
        while idx < len(worklist):
            u = worklist[idx]
            idx += 1
            for p in pred[u]:
                if x not in defs or p not in defs[x]:
                    if x not in live_out:
                        live_out.add(x)
                        worklist.append(p)
        live_in[x] = live_out

    # Phi decision: phi for x at y iff y in P(x) and x is live-in at y
    phi_nodes = {}
    for x in defs:
        for y in P[x]:
            if x in live_in[x]:
                if y not in phi_nodes:
                    phi_nodes[y] = set()
                phi_nodes[y].add(x)

    # Output assembly
    result = []
    for y in sorted(phi_nodes.keys()):
        names = sorted(phi_nodes[y])
        if names:
            result.append((y, names))

    return result

