        phi_nodes = P_x & live_in_x
        for node in phi_nodes:
            if node not in results:
                results[node] = set()
            results[node].add(x)

    # 7. Output
    output = []
    for node in sorted(results.keys()):
        names = sorted(results[node])
        output.append((node, names))

    return output

