        for k in range(LOG-1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    # 5. Dominance Frontier
    df_out = [set() for _ in range(n)]
    for u, v in valid_edges:
