        bucket[semi[w]].append(v)
        for z in bucket[w]:
            u = get_eval(z)
            if num[semi[u]] < num[semi[z]]:
                idom[z] = u
            else:
                idom[z] = w
        bucket[w] = []

    for i in range(1, num_nodes):
        v = rev_num[i]
        if idom[v] != semi[v]:
            idom[v] = idom[idom[v]]

