            elif idom[u] != v:
                df[v].add(u)

    # Propagate up the dominator tree
    for i in range(num_nodes - 1, 0, -1):
        u = rev_num[i]
        w = idom[u]
        if w != -1:
            df[w].update(df[u])

    # 6. Per-Name Analysis
    phi_sites = {}

    for x in all_names:
        # P(x) computation
        p_set = set()
        for u in range(n):
            if x in defs[u]:
