                    p_closure.add(v)
                    queue.append(v)

        # Liveness computation
        live_in = [False] * n
        worklist = deque()
        for u in range(n):
            if x in uses_exposed[u]:
                live_in[u] = True
                worklist.append(u)

        while worklist:
