    # 1. Input Validation
    if type(n) is bool or not isinstance(n, int) or n < 1:
        raise ValueError("n must be an int >= 1")
    if not isinstance(entry, int) or entry < 0 or entry >= n:
        raise ValueError("entry an int in 0..n-1")
    if not isinstance(edges, list):
        raise ValueError("edges a list of pairs")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("edges must be pairs")
        if not all(isinstance(x, int) and 0 <= x < n for x in e):
            raise ValueError("edge nodes out of range")
    if not isinstance(blocks, dict):
        raise ValueError("blocks a dict")
    for k, v in blocks.items():
        if not isinstance(k, int) or k < 0 or k >= n:
            raise ValueError("blocks keys out of range")
        if not isinstance(v, (list, tuple)):
            raise ValueError("blocks values must be lists/tuples")
        for instr in v:
            if not isinstance(instr, (list, tuple)) or len(instr) != 2:
                raise ValueError("instructions must be pairs")
            op, name = instr
            if op not in ("use", "def", "upd"):
                raise ValueError("invalid op")
            if not isinstance(name, str) or not name:
                raise ValueError("name must be non-empty str")
    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be a collection")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("params elements must be non-empty str")

    # 2. Reachability & Graph Construction
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)

    reachable = [False] * n
    queue = deque([entry])
    reachable[entry] = True
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if not reachable[v]:
                reachable[v] = True
                queue.append(v)

    r_adj = [[] for _ in range(n)]
    r_pred = [[] for _ in range(n)]
    for u in range(n):
        if reachable[u]:
            for v in adj[u]:
                if reachable[v]:
                    r_adj[u].append(v)
                    r_pred[v].append(u)

    # 3. Instruction Analysis
    defs = [set() for _ in range(n)]
    uses_exposed = [set() for _ in range(n)]
    all_names = set()

    for u in range(n):
        if not reachable[u]:
            continue
        instrs = blocks.get(u, [])
        current_defs = set()
        for op, name in instrs:
            all_names.add(name)
            if op in ("use", "upd"):
                if name not in current_defs:
                    uses_exposed[u].add(name)
            if op in ("def", "upd"):
                defs[u].add(name)
                current_defs.add(name)

    # 4. Dominators (Lengauer-Tarjan)
    num = [-1] * n
    semi = [-1] * n
    idom = [-1] * n
    ancestor = [-1] * n
    bucket = [[] for _ in range(n)]
    parent = [-1] * n
    num_nodes = 0

    stack = [entry]
    num[entry] = 0
    rev_num = [-1] * n
    rev_num[0] = entry
    num_nodes = 1

    while stack:
        u = stack[-1]
        pushed = False
        for v in r_adj[u]:
            if num[v] == -1:
                num[v] = num_nodes
                rev_num[num_nodes] = v
                parent[v] = u
                num_nodes += 1
                stack.append(v)
                pushed = True
                break
        if not pushed:
            stack.pop()

    for i in range(num_nodes):
        v = rev_num[i]
        semi[v] = v
        idom[v] = v
        ancestor[v] = -1

    def get_eval(v):
        if ancestor[v] == -1:
            return v
        path = []
        curr = v
        while ancestor[curr] != -1:
            path.append(curr)
            curr = ancestor[curr]
        root = curr
        best = root
        for node in path:
            if num[semi[node]] < num[semi[best]]:
                best = node
        for node in path:
            ancestor[node] = root
        return best

    for i in range(num_nodes - 1, 0, -1):
        v = rev_num[i]
        w = parent[v]
        if w == -1:
            continue
        u = get_eval(v)
        if num[semi[u]] < num[semi[w]]:
            semi[v] = semi[u]
        ancestor[v] = w
        bucket[semi[w]].append(v)
        for z in bucket[w]:
            u = get_eval(z)
            if num[semi[u]] < num[semi[z]]:
                idom[z] = u
            else:
                idom[z] = w
        bucket[w] = []

    for i in range(1, num_nodes):
        v = rev_num[i]
        if idom[v] != semi[v]:
            idom[v] = idom[idom[v]]
    idom[entry] = -1

    # 5. LCA Setup
    LOG = max(1, n.bit_length())
    up = [[-1] * n for _ in range(LOG)]
    depth = [-1] * n
    depth[entry] = 0

    # Build dominator tree BFS for depth
    dt_adj = [[] for _ in range(n)]
    for u in range(n):
        if reachable[u] and idom[u] != -1:
            dt_adj[idom[u]].append(u)

    q = deque([entry])
    while q:
        u = q.popleft()
        for v in dt_adj[u]:
            depth[v] = depth[u] + 1
            q.append(v)

    for u in range(n):
        if reachable[u]:
            up[0][u] = idom[u]

    for k in range(1, LOG):
        for u in range(n):
            if up[k-1][u] != -1:
                up[k][u] = up[k-1][up[k-1][u]]
            else:
                up[k][u] = -1

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        diff = depth[u] - depth[v]
        for k in range(LOG):
            if (diff >> k) & 1:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG - 1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    # 6. Dominance Frontier
    df_of = [set() for _ in range(n)]
    for u in range(n):
        if not reachable[u]:
            continue
        for v in r_adj[u]:
            if u == v:
                df_of[u].add(u)
                continue
            w = lca(u, v)
            while w != v:
                df_of[v].add(w)
                w = idom[w]
                if w == -1:
                    break

    frontier_adj = [[] for _ in range(n)]
    for v in range(n):
        if not reachable[v]:
            continue
        for d in df_of[v]:
            if d != -1:
                frontier_adj[d].append(v)

    # 7. Per-Name Analysis
    phi_sites = {}

    for x in all_names:
        # P(x) computation
        p_set = set()
        for u in range(n):
            if x in defs[u]:
                p_set.add(u)
        if x in params:
            p_set.add(entry)

        p_closure = set(p_set)
        queue = deque(p_set)
        while queue:
            u = queue.popleft()
            for v in frontier_adj[u]:
                if v not in p_closure:
                    p_closure.add(v)
                    queue.append(v)

        # Liveness computation
        live_in = [False] * n
        worklist = deque()
        for u in range(n):
            if x in uses_exposed[u]:
                live_in[u] = True
                worklist.append(u)

        while worklist:
            v = worklist.popleft()
            for u in r_pred[v]:
                if x not in defs[u]:
                    if not live_in[u]:
                        live_in[u] = True
                        worklist.append(u)

        # Phi decision
        for u in range(n):
            if u in p_closure and live_in[u]:
                if u not in phi_sites:
                    phi_sites[u] = set()
                phi_sites[u].add(x)

    # 8. Output Assembly
    result = []
    for u in sorted(phi_sites.keys()):
        names = sorted(phi_sites[u])
        result.append((u, names))

    return result

