        visited_p = set(p_set)
        head = 0
        while head < len(frontier_q):
            curr = frontier_q[head]
            head += 1
            for w in df[curr]:
                if w not in visited_p:
                    visited_p.add(w)
                    frontier_q.append(w)

        live_in = set(uses_exposed.get(x, set()))
        live_q = list(live_in)
        head = 0
        while head < len(live_q):
