        for k in range(LOG-1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    df = [set() for _ in range(n)]
    for u in reachable_nodes:
        for v in adj[u]:
            if u == v:
                df[u].add(u)
            else:
                w = lca(u, v)
                if w == v:
                    df[v].add(v)
                else:
                    while w != v:
                        df[v].add(w)
                        w = idom[w]

    # 5. Per-Name Analysis
    defs = {}
    uses_exposed = {}
    node_defs = {}

    for u in reachable_nodes:
        if u not in reachable_blocks:
            continue
        node_defs[u] = set()
        seen = set()
        for op, name in reachable_blocks[u]:
            if op in ("def", "upd"):
                defs.setdefault(name, set()).add(u)
                node_defs[u].add(name)
                seen.add(name)
            if op in ("use", "upd"):
                if name not in seen:
                    uses_exposed.setdefault(name, set()).add(u)

    all_names = set(defs.keys()) | set(uses_exposed.keys())
    phi_nodes = {}

    for x in all_names:
        p_set = set(defs.get(x, set()))
        if x in params_set:
            p_set.add(entry)

        frontier_q = list(p_set)
        visited_p = set(p_set)
        head = 0
        while head < len(frontier_q):
            curr = frontier_q[head]
            head += 1
            for w in df[curr]:
                if w not in visited_p:
                    visited_p.add(w)
                    frontier_q.append(w)

        live_in = set(uses_exposed.get(x, set()))
        live_q = list(live_in)
        head = 0
        while head < len(live_q):
            curr = live_q[head]
            head += 1
            for p in pred[curr]:
                if x not in node_defs.get(p, set()):
                    if p not in live_in:
                        live_in.add(p)
                        live_q.append(p)

        for y in p_set:
            if y in live_in:
                phi_nodes.setdefault(y, set()).add(x)

    result = []
    for node in sorted(phi_nodes.keys()):
        names = sorted(phi_nodes[node])
        if names:
            result.append((node, names))

    return result

