def live_phi_sites(n, edges, entry, blocks, params):
    # 1. Validation
    if type(n) is bool or not isinstance(n, int) or n < 1:
        raise ValueError("n must be an int >= 1")
    if type(entry) is bool or not isinstance(entry, int) or not (0 <= entry < n):
        raise ValueError("entry must be an int in 0..n-1")
    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges must be a list")
    for e in edges:
        if not (isinstance(e, (list, tuple)) and len(e) == 2):
            raise ValueError("edges must be pairs")
        if type(e[0]) is bool or not isinstance(e[0], int) or not (0 <= e[0] < n):
            raise ValueError("edge source invalid")
        if type(e[1]) is bool or not isinstance(e[1], int) or not (0 <= e[1] < n):
            raise ValueError("edge dest invalid")

    if not isinstance(blocks, dict):
        raise ValueError("blocks must be a dict")
    valid_ops = {"use", "def", "upd"}
    for k, v in blocks.items():
        if type(k) is bool or not isinstance(k, int) or not (0 <= k < n):
            raise ValueError("block key invalid")
        if not isinstance(v, (list, tuple)):
            raise ValueError("block value must be list/tuple")
        for inst in v:
            if not (isinstance(inst, (list, tuple)) and len(inst) == 2):
                raise ValueError("instruction must be pair")
            if inst[0] not in valid_ops:
                raise ValueError("invalid op")
            if not isinstance(inst[1], str) or not inst[1]:
                raise ValueError("name must be non-empty str")

    if not isinstance(params, (list, tuple, set, frozenset)):
        raise ValueError("params must be collection")
    for p in params:
        if not isinstance(p, str) or not p:
            raise ValueError("param must be non-empty str")

    params_set = set(params)

    # 2. Reachability
    succ = [[] for _ in range(n)]
    for u, v in edges:
        succ[u].append(v)

    reachable = [False] * n
    q = [entry]
    reachable[entry] = True
    head = 0
    while head < len(q):
        u = q[head]
        head += 1
        for v in succ[u]:
            if not reachable[v]:
                reachable[v] = True
                q.append(v)

    reachable_nodes = [i for i, r in enumerate(reachable) if r]
    if not reachable_nodes:
        return []

    adj = [[] for _ in range(n)]
    pred = [[] for _ in range(n)]
    for u in reachable_nodes:
        for v in succ[u]:
            if reachable[v]:
                adj[u].append(v)
                pred[v].append(u)

    reachable_blocks = {u: blocks[u] for u in reachable_nodes if u in blocks}

    # 3. Dominators (Lengauer-Tarjan)
    pre = [-1] * n
    parent = [-1] * n
    rev_pre = [-1] * n
    order = []
    stack = [entry]
    pre[entry] = 0
    rev_pre[0] = entry
    idx = 1
    while stack:
        u = stack[-1]
        found = False
        for v in adj[u]:
            if pre[v] == -1:
                pre[v] = idx
                rev_pre[idx] = v
                parent[v] = u
                stack.append(v)
                idx += 1
                found = True
                break
        if not found:
            order.append(stack.pop())

    nodes_by_pre = [rev_pre[i] for i in range(idx)]

    idom = [0] * n
    semi = [0] * n
    bucket = [[] for _ in range(n)]
    anc = list(range(n))
    val = list(range(n))
    for i in range(n): semi[i] = i

    def eval(v):
        if anc[v] == v:
            return v
        u = eval(anc[v])
        if pre[semi[val[anc[v]]]] < pre[semi[val[v]]]:
            val[v] = val[anc[v]]
        anc[v] = anc[anc[v]]
        return val[v]

    for i in range(len(nodes_by_pre) - 1, 0, -1):
        v = nodes_by_pre[i]
        for w in adj[v]:
            if pre[w] != -1:
                u = eval(w)
                if pre[semi[u]] < pre[semi[v]]:
                    semi[v] = semi[u]
        anc[v] = parent[v]
        bucket[semi[v]].append(v)
        for w in bucket[parent[v]]:
            u = eval(w)
            if semi[u] == semi[w]:
                idom[w] = semi[w]
            else:
                idom[w] = u
        bucket[parent[v]] = []

    for i in range(len(nodes_by_pre) - 1, 0, -1):
        v = nodes_by_pre[i]
        if idom[v] != semi[v]:
            idom[v] = idom[idom[v]]

    # 4. LCA & Frontier
    depth = [0] * n
    LOG = 16
    up = [[-1] * n for _ in range(LOG)]

    for v in nodes_by_pre:
        if v == entry:
            depth[v] = 0
            up[0][v] = v
        else:
            depth[v] = depth[idom[v]] + 1
            up[0][v] = idom[v]

    for k in range(1, LOG):
        for v in nodes_by_pre:
            if up[k-1][v] != -1:
                up[k][v] = up[k-1][up[k-1][v]]
            else:
                up[k][v] = -1

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        for k in range(LOG-1, -1, -1):
            if depth[u] - (1 << k) >= depth[v]:
                u = up[k][u]
        if u == v:
            return u
        for k in range(LOG-1, -1, -1):
            if up[k][u] != up[k][v]:
                u = up[k][u]
                v = up[k][v]
        return up[0][u]

    df = [[] for _ in range(n)]
    for u in reachable_nodes:
        for v in adj[u]:
            if u == v:
                df[u].append(v)
            else:
                w = lca(u, v)
                curr = w
                while curr != v:
                    df[curr].append(v)
                    curr = idom[curr]

    # 5. Per-Name Analysis
    defs = {}
    uses_exposed = {}
    node_defs = {}

    for u in reachable_nodes:
        if u not in reachable_blocks:
            continue
        node_defs[u] = set()
        seen = set()
        for op, name in reachable_blocks[u]:
            if op in ("def", "upd"):
                defs.setdefault(name, set()).add(u)
                node_defs[u].add(name)
                seen.add(name)
            if op in ("use", "upd"):
                if name not in seen:
                    uses_exposed.setdefault(name, set()).add(u)

    all_names = set(defs.keys()) | set(uses_exposed.keys())
    phi_nodes = {}

    for x in all_names:
        p_set = set(defs.get(x, set()))
        if x in params_set:
            p_set.add(entry)

        frontier_q = list(p_set)
        visited_p = set(p_set)
        head = 0
        while head < len(frontier_q):
            curr = frontier_q[head]
            head += 1
            for w in df[curr]:
                if w not in visited_p:
                    visited_p.add(w)
                    frontier_q.append(w)

        live_in = set(uses_exposed.get(x, set()))
        live_q = list(live_in)
        head = 0
        while head < len(live_q):
            curr = live_q[head]
            head += 1
            for p in pred[curr]:
                if x not in node_defs.get(p, set()):
                    if p not in live_in:
                        live_in.add(p)
                        live_q.append(p)

        for y in p_set:
            if y in live_in:
                phi_nodes.setdefault(y, set()).add(x)

    result = []
    for node in sorted(phi_nodes.keys()):
        names = sorted(phi_nodes[node])
        if names:
            result.append((node, names))

    return result

def format_sigfigs(s, sig, mode):
    # 1. Validate inputs
    if isinstance(sig, bool) or not isinstance(sig, int):
        raise ValueError("sig must be an int")
    if not (1 <= sig <= 2000):
        raise ValueError("sig must be in 1..2000")

    valid_modes = {
        "nearest_even", "nearest_away", "nearest_zero",
        "toward_zero", "away_zero", "toward_neg", "toward_pos", "zero_five"
    }
    if mode not in valid_modes:
        raise ValueError("Invalid mode")

    if not isinstance(s, str):
        raise ValueError("s must be a string")

    if len(s) > 100000:
        raise ValueError("s too long")

    # 2. Parse s
    sign = ""
    idx = 0
    if s[0] in '+-':
        sign = s[0]
        idx = 1

    # Find exponent part
    exp_str = ""
    mantissa_str = s[idx:]
    exp_idx = -1
    for i, c in enumerate(mantissa_str):
        if c in 'eE':
            exp_idx = i
            break

    if exp_idx != -1:
        exp_str = mantissa_str[exp_idx+1:]
        mantissa_str = mantissa_str[:exp_idx]

        # Validate exponent part
        if not exp_str:
            raise ValueError("Invalid exponent")
        if exp_str[0] in '+-':
            exp_digits = exp_str[1:]
        else:
            exp_digits = exp_str

        if not exp_digits.isdigit():
            raise ValueError("Invalid exponent digits")
        if len(exp_digits) < 1 or len(exp_digits) > 10:
            raise ValueError("Invalid exponent length")
        exp_val = int(exp_digits)
    else:
        exp_val = 0

    # Validate mantissa part
    if '.' not in mantissa_str:
        if not mantissa_str.isdigit():
            raise ValueError("Invalid mantissa")
        dot_pos = len(mantissa_str)
    else:
        parts = mantissa_str.split('.')
        if len(parts) != 2:
            raise ValueError("Invalid mantissa")
        before, after = parts
        if not (before.isdigit() or after.isdigit()) or (before == "" and after == ""):
            raise ValueError("Invalid mantissa")
        if '.' in before or '.' in after:
            raise ValueError("Invalid mantissa")
        dot_pos = len(before)

    # Collect digits
    digits_str = mantissa_str.replace('.', '')
    if not digits_str.isdigit():
        raise ValueError("Invalid mantissa digits")
    D = list(digits_str)

    # 3. Handle Zero
    if all(d == '0' for d in D):
        # Zero case
        if sig == 1:
            res = "0"
        else:
            res = "0." + "0" * (sig - 1)
        return res + "e+00"

    # 4. Find first non-zero digit
    first_nonzero = -1
    for i, d in enumerate(D):
        if d != '0':
            first_nonzero = i
            break

    # 5. Calculate exponent of the first significant digit
    E_first = dot_pos - 1 - first_nonzero + exp_val

    # 6. Determine cut index
    cut = first_nonzero + sig - 1

    # 7. Check if rounding is needed
    if cut >= len(D):
        # No rounding needed, just pad
        current_digits = D[first_nonzero:]
        current_digits.extend(['0'] * (sig - len(current_digits)))

        mantissa = "".join(current_digits[:sig])
        exp_str = str(abs(E_first)).zfill(2)
        exp_sign = "+" if E_first >= 0 else "-"
        res = mantissa[0] + ("." + mantissa[1:] if sig > 1 else "")
        res += f"e{exp_sign}{exp_str}"
        if sign == '-':
            res = "-" + res
        return res

    # 8. Rounding logic
    drop_digits = D[cut+1:]

    # Analyze dropped part
    # States: < half, == half, > half
    # Check if all zeros
    is_zero = all(d == '0' for d in drop_digits)

    is_half = False
    is_greater = False
    is_less = False

    if not is_zero:
        first_drop = drop_digits[0]
        rest_drop = drop_digits[1:]

        if first_drop > '5':
            is_greater = True
        elif first_drop < '5':
            is_less = True
        else: # first_drop == '5'
            if all(d == '0' for d in rest_drop):
                is_half = True
            else:
                is_greater = True

    # Decide whether to increment magnitude
    increment = False

    if mode == "toward_zero":
        increment = False
    elif mode == "away_zero":
        increment = not is_zero
    elif mode == "toward_neg": # floor
        if sign == '-':
            increment = not is_zero
        else:
            increment = False
    elif mode == "toward_pos": # ceil
        if sign == '+':
            increment = not is_zero
        else:
            increment = False
    elif mode == "nearest_even":
        if is_greater:
            increment = True
        elif is_half:
            if D[cut] in '13579':
                increment = True
        else:
            increment = False
    elif mode == "nearest_away":
        if is_greater or is_half:
            increment = True
        else:
            increment = False
    elif mode == "nearest_zero":
        if is_greater:
            increment = True
        else:
            increment = False
    elif mode == "zero_five":
        if not is_zero and D[cut] in '05':
            increment = True
        else:
            increment = False

    # Apply increment
    if increment:
        idx = cut
        while idx >= first_nonzero:
            if D[idx] == '9':
                D[idx] = '0'
                idx -= 1
            else:
                D[idx] = str(int(D[idx]) + 1)
                break
        else:
            # Carry propagated out of first_nonzero
            D.insert(first_nonzero, '1')
            E_first += 1

    # 9. Format result
    res_digits = D[first_nonzero : first_nonzero + sig]

    mantissa = "".join(res_digits)

    # Range check
    if E_first < -999999999 or E_first > 999999999:
        raise ValueError("Exponent out of range")

    exp_str = str(abs(E_first)).zfill(2)
    exp_sign = "+" if E_first >= 0 else "-"

    res = mantissa[0] + ("." + mantissa[1:] if sig > 1 else "")
    res += f"e{exp_sign}{exp_str}"

    if sign == '-':
        res = "-" + res

    return res

