        raise ValueError("mode must be one of the allowed strings")

    if not isinstance(s, str) or len(s) > 100000:
        raise ValueError("s must be a string of length <= 100000")

    # Parse s
    # Format: [sign] digits [. digits] [e/sign digits]
    idx = 0
    n = len(s)
    sign = 1
    if idx < n and s[idx] in '+-':
        if s[idx] == '-':
            sign = -1
        idx += 1

    # Digits part
    digits = []
    dot_pos = -1
    while idx < n and s[idx] != 'e' and s[idx] != 'E':
        if s[idx] == '.':
            if dot_pos != -1:
                raise ValueError("Multiple decimal points")
            dot_pos = len(digits)
        elif '0' <= s[idx] <= '9':
            digits.append(int(s[idx]))
        else:
            raise ValueError("Invalid character in s")
        idx += 1

    if dot_pos == -1:
        dot_pos = len(digits)

    # Exponent part
    E_exp = 0
    if idx < n and s[idx] in 'eE':
        idx += 1
        if idx < n and s[idx] in '+-':
            exp_sign = 1 if s[idx] == '+' else -1
            idx += 1
        else:
            exp_sign = 1

        exp_digits = []
        while idx < n and '0' <= s[idx] <= '9':
            exp_digits.append(s[idx])
            idx += 1

        if not exp_digits:
            raise ValueError("Exponent missing digits")
        if len(exp_digits) > 10:
            raise ValueError("Exponent too long")

        E_exp = int(''.join(exp_digits)) * exp_sign

    if idx < n:
        raise ValueError("Trailing characters in s")

    # Check for zero
    if all(d == 0 for d in digits):
        zero_str = "0" if sig == 1 else "0." + "0" * (sig - 1)
        return f"{zero_str}e+00"

    # Find first non-zero digit
    first_nonzero_idx = 0
    for i, d in enumerate(digits):
        if d != 0:
            first_nonzero_idx = i
            break

    # Calculate exponent of the first significant digit
    # Value = sign * (integer formed by digits) * 10^(E_exp - (len(digits) - dot_pos))
    # The first significant digit is at index first_nonzero_idx.
    # Its position in the integer is (len(digits) - 1 - first_nonzero_idx) from right.
    # So its power of 10 is: E_exp - (len(digits) - dot_pos) + (len(digits) - 1 - first_nonzero_idx)
    # Simplifies to: E_exp + dot_pos - 1 - first_nonzero_idx
    exp = E_exp + dot_pos - 1 - first_nonzero_idx

