        drop = S[sig:]

        # Analyze dropped part
        is_zero = all(d == 0 for d in drop)
        if is_zero:
            is_half = False
            is_greater = False
        else:
            # Check if exactly half: first digit 5, rest 0
            if drop[0] == 5 and all(d == 0 for d in drop[1:]):
                is_half = True
                is_greater = False
            else:
                is_half = False
                is_greater = True

        # Determine if we round up
        do_round_up = False

        if mode == "toward_zero":
            do_round_up = False
        elif mode == "away_zero":
            do_round_up = not is_zero
        elif mode == "toward_neg": # floor
            if sign < 0:
                do_round_up = not is_zero # For negative, floor is away from zero
            else:
                do_round_up = False
        elif mode == "toward_pos": # ceiling
            if sign > 0:
                do_round_up = not is_zero # For positive, ceiling is away from zero
            else:
                do_round_up = False
        elif mode == "nearest_even":
            if is_greater:
                do_round_up = True
            elif is_half:
                # Tie: round to even last digit
                last_digit = keep[-1]
                if last_digit % 2 != 0:
                    do_round_up = True
                else:
                    do_round_up = False
            else:
                do_round_up = False
        elif mode == "nearest_away":
            if is_greater or is_half:
                do_round_up = True
            else:
                do_round_up = False
        elif mode == "nearest_zero":
            if is_greater:
                do_round_up = True
            else:
                do_round_up = False
        elif mode == "zero_five":
            if not is_zero:
                last_digit = keep[-1]
                if last_digit in (0, 5):
                    do_round_up = True
                else:
                    do_round_up = False
            else:
                do_round_up = False

        if do_round_up:
            # Increment the number formed by keep
            # Convert to string to handle large numbers easily
            keep_str = ''.join(map(str, keep))
            val = int(keep_str) + 1
            new_keep_str = str(val)

            if len(new_keep_str) > sig:
                # Overflow: e.g., 99 -> 100
                # Mantissa becomes 1.00...0
                # Exponent increases by 1
                S = [1] + [0] * (sig - 1)
                exp += 1
            else:
                S = [int(c) for c in new_keep_str]

    # Format output
    # Sign
    res_sign = "-" if sign < 0 else ""

    # Mantissa
    mantissa = str(S[0])
    if sig > 1:
        mantissa += "." + ''.join(map(str, S[1:]))

    # Exponent
    abs_exp = abs(exp)
    exp_str = f"{abs_exp:02d}"
    exp_sign = "+" if exp >= 0 else "-"

    return f"{res_sign}{mantissa}e{exp_sign}{exp_str}"

