    # Normalize step to m * 10^e where m not divisible by 10
    while N_s % 10 == 0 and E_s < 0:
        N_s //= 10
        E_s += 1
    d = max(0, -E_s)

    # Compute k = floor(x / step) and remainder
    diff = E_x - E_s
    if diff >= 0:
        # num = N_x * 10^diff, den = N_s
        # Check if diff is too large early to avoid memory blowup
        if diff > 3005:
            # x/step will be huge, definitely exceeds size limit unless N_x=0
            if N_x == 0:
                k = 0
                r = 0
                den = 1
            else:
                raise ValueError("Result exceeds size limit.")
        else:
            num = N_x * (10 ** diff)
            den = N_s
            q_abs = num // den
            r = num % den
    else:
        # num = N_x, den = N_s * 10^(-diff)
        # -diff can be large, but if it's > 3000, x/step is tiny (< 10^-3000)
        if -diff > 3005:
            if N_x == 0:
                k = 0
                r = 0
                den = 1
            else:
                # x is non-zero but step is massively larger, x/step is tiny
                # q_abs will be 0, r = N_x
                q_abs = 0
                r = N_x
                den = N_s * (10 ** (-diff))
        else:
            num = N_x
            den = N_s * (10 ** (-diff))
            q_abs = num // den
            r = num % den

    # Adjust q for sign of x
    if sign_x == -1:
        q = -q_abs - (1 if r > 0 else 0)
    else:
        q = q_abs

    up = q + 1
    down = q

    # Determine k_target
    if r == 0:
        k = q
    else:
        cmp = 2 * r - den
        if cmp < 0:  # closer to down
            if mode == "ceil":
                k = up
            elif mode == "outward":
                k = up if sign_x > 0 else down
            else:
                k = down
        elif cmp > 0:  # closer to up
            if mode == "floor":
                k = down
            elif mode == "outward":
                k = down if sign_x < 0 else up
            else:
                k = up
        else:  # tie
            if mode == "tie_even":
                k = up if up % 2 == 0 else down
            elif mode == "tie_odd":
                k = up if up % 2 != 0 else down
            elif mode == "tie_away":
                k = up if sign_x >= 0 else down
            elif mode == "tie_zero":
                k = down if sign_x >= 0 else up
            else:
