        k_bits = k_abs.bit_length()
        S_bits = S.bit_length()
        R_bits = k_bits + S_bits
        R_len_est = int(R_bits * 0.30103) + 2
        if max(1, R_len_est - d) + d > 3000:
            raise ValueError("Result exceeds size limit.")

    # Compute actual result
    R = k_abs * S
    s_R = str(R)

    if k == 0:
        return "0" if d == 0 else "0." + "0" * d

    if len(s_R) <= d:
        frac = "0" * (d - len(s_R)) + s_R
        int_part = "0"
    else:
        frac = s_R[-d:]
        int_part = s_R[:-d]

    res = (int_part + "." + frac) if d > 0 else int_part
    if k < 0:
        res = "-" + res

    return res

