            frac_p = s[dot_idx+1:exp_idx] or '0'
            digits = int_p + frac_p
            exp_part = s[exp_idx+1:] if exp_idx < len(s) else '0'
            E = int(exp_part) - len(frac_p)
        else:
            digits = s[i:exp_idx]
            exp_part = s[exp_idx+1:] if exp_idx < len(s) else '0'
            E = int(exp_part)

        if not digits: raise ValueError("No digits found.")
        return sign, int(digits), E

    sign_x, N_x, E_x = parse_dec(x)
    sign_s, N_s, E_s = parse_dec(step)

